(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.5"]={"from":120,"a":[["\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא קבליה עליה\u0004 \u0005[קיבלו עליו]\u0006 \u0003באלוה\u0004 והשתחווה מפני כבוד המלכות — \u0003לא כלום הוא. אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה ששגה במחשבתו ועבד עבודה זרה \u0003מאהבה\u0004 או \u0003מיראה\u0004 מפני אדם? והרי זו הוכחה שאף זו קרויה עבודה זרה!","\u0003ורבא אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003לא,\u0004 אלא כאן מדובר \u0003באומר מותר,\u0004 שסבר אותו כהן גדול שעבודה זרה מעיקרה מותרת.","ומקשים: אם מדובר באופן שהוא \u0003אומר מותר,\u0004 הלא \u0003היינו\u0004 \u0005[זהו]\u0006 בדיוק \u0003העלם דבר,\u0004 ומה ההבדל בין רבי וחכמים?","ומשיבים: ההבדל בינם הוא \u0003באומר מותר לגמרי,\u0004 שסבר שאין כל איסור בעבודה זרה, ואילו \u0003העלם דבר\u0004 בהלכה כוונתו שיש \u0003קיום מקצת\u0004 מן המצוה \u0003וביטול מקצת\u0004 ממנה בשגגה.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' זכאי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 דברי ברייתא זו: \u0003זיבח וקיטר וניסך והשתחוה\u0004 לעבודה זרה \u0003בהעלם אחד\u0004 (בשגגה אחת), שלא נודע לו איסורם בינתיים — \u0003אינו חייב אלא\u0004 קרבן חטאת \u0003אחת,\u0004 ואין מחייבים אותו בקרבן על כל עבודה ועבודה לחוד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003פוק תני לברא\u0004 \u0005[צא\u0006 ו\u0005שנה בחוץ],\u0006 כלומר, בבית המדרש אין מכניסים ברייתא כגון זו, והלכה שחייב על כל עבודה לעצמה.","\u0003אמר ר' אבא: הא\u0004 \u0005[זה]\u0006 ש\u0003אמר\u0004 \u0003ר' זכאי\u0004 תלוי ב\u0003מחלוקת\u0004 התנאים \u0003ר' יוסי ור' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 איסור \u0003הבערה\u0004 של אש בשבת, שנתפרש בתורה ולא נכלל בשאר המלאכות האחרות בשבת (\"לא תבערו אש בכל מושבותיכם ביום השבת\". שמות לה, ג), \u0003ללאו יצאה,\u0004 ללמד שאין זו כשאר המלאכות שחייבים עליהן סקילה, אלא יש בה איסור \"לא תעשה\" בלבד שעונשו מלקות, אלו \u0003דברי ר' יוסי.\u0004","\u0003ור' נתן אומר: לחלק יצאה\u0004 הבערה זו, להיות כדוגמה לכל שאר המלאכות, ונלמד (במדת \"דבר שיצא מן הכלל ללמד\" וכו') שכשם שנתייחד איסור להבערה, כך יש איסור מיוחד בכל מלאכה ומלאכה מן המלאכות האסורות בשבת, שאם עשה כמה מלאכות בשגגה אחת חייב קרבן על כל מלאכה ומלאכה.","ויכולים אנו להשוות מחלוקת זו גם לענייננו, ונאמר: \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003הבערה ללאו יצאה, השתחואה נמי\u0004 \u0005[גם כן]\u0006 שנתפרטה בתורה מכל שאר עבודות אסורות (\"לא תשתחוה להם ולא תעבדם\". שמות כ, ה), גם היא \u0003ללאו יצאה,\u0004 ללמד שבהשתחוואה אין מיתת בית דין אלא איסור לא תעשה בלבד.","ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003הבערה לחלק יצאה, השתחואה נמי\u0004 \u0005[גם כן]\u0006 \u0003לחלק יצאה,\u0004 ולשיטה זו חייב קרבן על כל עבודה ועבודה לחוד, כשם שחייב על השתחוואה לחוד. והברייתא ששנה ר' זכאי כשיטת ר' יוסי היא.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על השוואה זו, \u0003רב יוסף: דילמא\u0004 \u0005[שמא]\u0006 אינו כן, אלא \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי התם\u0004 \u0005[שם],\u0006 בדיני שבת ש\u0003הבערה ללאו יצאה,\u0004 אלא משום \u0003דנפקא ליה\u0004 \u0005[שיוצא לו,\u0006 שהוא למד\u0005]\u0006 דין \u0003חילוק מלאכות\u0004 בשבת, שיש חיוב בכל אחת מהן ממקור אחר, מדרשת הכתוב \u0003\"מאחת מהנה\".\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר,\u0004 נאמר: \u0003\"\u0004נפש כי תחטא בשגגה מכל מצות ה' אשר לא תעשינה \u0003ועשה מאחת מהנה\"\u0004 (ויקרא ד, ב), ומצירוף לשון יחיד ולשון רבים באותו כתוב למד הוא: \u0003פעמים שחייב\u0004 חטאת \u0003אחת על כולן, פעמים שחייב על כל אחת ואחת.\u0004","\u0003ואמר ר' יונתן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשה מאחת מהנה\",\u0004 וכך הוא מוצא בכתוב מקום לדרשה: \u0003\"אחת\",\u0004 ולשון צמצום: \u0003\"מאחת\",\u0004 וכן \u0003\"הנה\",\u0004 ובצמצום: \u0003\"מהנה\",\u0004 \"מאחת מהנה\" יחד ללמד שיש \u0003אחת שהיא הנה\u0004 (רבות), \u0003ו\u0004יש \u0003הנה שהיא אחת.\u0004","וכך ביאורו לענין הלכות שבת: \u0003\"אחת\"\u0004 — שעשה מלאכה שלימה כגון שכתב מלה שלימה שהתכוון לה, כגון \u0003\"שמעון\", \"מאחת\"\u0004 (שמשמעו: מקצת אחת) — שכתב רק חלק מן האותיות כגון \u0003\"שם\" מ\"שמעון\",\u0004 אך כיון שכתב שתי אותיות שהן שיעור מלאכת הכתיבה, אף שלא גמר כפי שהיתה כוונתו, חייב על כתיבה זו.","\u0003\"הנה\"\u0004 הכוונה ל\u0003אבות\u0004 (עיקרי) המלאכות, \u0003\"מהנה\"\u0004 — מה שנובע מהן, \u0003תולדות\u0004 המלאכות (מלאכות הדומות להן), \u0003אחת שהיא הנה\u0004 — עבירה אחת שיש בה הרבה פרטים כ\u0003זדון שבת,\u0004 כלומר, שידע ששבת הוא, \u0003ושגגות מלאכות,\u0004 שלא ידע שמלאכות אלה אסורות בשבת, ובשגגה כזו חייב להביא קרבן חטאת על כל מלאכה ומלאכה שעשה. \u0003הנה שהיא אחת,\u0004 כלומר, מלאכות רבות, עבירות רבות שדינן כאחת — \u0003שגגת שבת,\u0004 שאינו יודע ששבת היום, \u0003וזדון מלאכות,\u0004 שיודע שמלאכות אלה אסורות בשבת, אלא שכח ששבת היום ואינו חייב אלא קרבן אחד, ולענייננו ברור שר' יוסי מקבל עיקרון זה של חילוק מלאכות בשבת, אלא שהוא מוצא לו ראיה ממקור אחר ולא ממלאכת ההבערה.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 בענין עבודה זרה, ש\u0003לא נפקא ליה\u0004 \u0005[יצא לו]\u0006 \u0003חילוק מלאכות\u0004 (עבודות) \u0003מדוכתא אחריתי\u0004 \u0005[ממקור אחר],\u0006 שמא \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003השתחואה לחלק יצאה\u0004 ויודו הכל שחייב על כל עבודה לעצמה.","על שתי הדעות, של ר' אבא ושל רב יוסף, מקשים: \u0003חילוק מלאכות\u0004 שב\u0003עבודה זרה נמי תיפוק ליה\u0004 \u0005[גם כן תצא לו,\u0006 ילמד\u0005]\u0006 מאותו מקור שלמד להלכות שבת, \u0003מ\"אחת מהנה\",\u0004 שהרי אותו כתוב לא נתייחד לדיני שבת דווקא, וכדרך שדרשנו לענין הלכות שבת נדרוש לענין עבודה זרה: \u0003\"אחת\"\u0004 — לחייב על עבודה שלמה של עבירה כגון \u0003זביחה, \"מאחת\"\u0004 (מקצת אחת) — כגון שלא גמר את כל השחיטה אלא עשה מקצתה, שחתך בה רק \u0003סימן אחד\u0004 מסימני שחיטה (קנה או ושט).","\u0003\"הנה\"\u0004 — פירושו \u0003אבות,\u0004 אחת מאבות (עיקרי) העבודות האסורות שלמדים מדרכי עבודת ה', כגון \u0003זיבוח, קיטור, ניסוך, והשתחואה. \"מהנה\"\u0004 — \u0003תולדות,\u0004 כגון \u0003שבר מקל לפניה,\u0004 לפני עבודה זרה שדרכה בעבודה במקל, ושבירת המקל בפניה דומה קצת לעבודת הזובח, שגם הוא שובר את מפרקת הבהמה לפני הנעבד.","\u0003אחת שהיא הנה\u0004 יתפרש באופן של \u0003זדון עבודה זרה,\u0004 כלומר, יודע שעבודה זרה אסורה, \u0003ושגגת עבודות\u0004 שלא ידע שעבודות אלה שעשה אסורות. \u0003הנה שהיא אחת\u0004 — \u0003שגגת עבודה זרה,\u0004 ששגג בעיקר, שלא ידע איסור עבודה זרה או שלא ידע שעבודה זרה היא, \u0003וזדון עבודות\u0004 שידע שעבודות אלה אסורות לעבודה זרה.","את הקושיה הזו מנסים לסתור: \u0003האי\u0004 \u0005[זו]\u0006 \u0003שגגת עבודה זרה היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבר]\u0006 השוגג ש\u0003בית הכנסת הוא והשתחוה לו\u0004 — \u0003הרי לבו לשמים\u0004 ובוודאי פטור,","\u0003אלא דחזא אנדרטא וסגיד ליה\u0004 \u0005[שראה פסל אדם והשתחווה לו],\u0006 \u0003אי קבליה עליה\u0004 \u0005[אם קיבלו עליו]\u0006 כאלוה \u0003מזיד הוא, אי\u0004 \u0005[אם]\u0006 \u0003לא קבליה עליה\u0004 \u0005[קיבלו עליו]\u0006 אלא לכבוד בלבד עשה, \u0003לא כלום הוא,\u0004","\u0003אלא\u0004 תאמר שהשתחווה לפסל \u0003מאהבה ומיראה\u0004 של אדם, ולא ידע שאסור. \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 ש\u0003אמר חייב\u0004 על כך, וכיון ששגג חייב להביא קרבן, \u0003אלא ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר פטור, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003אלא\u0004 לדעתו אפשר לפרש זאת \u0003באומר מותר,\u0004 שסבור שעבודה זרה בכלל מותרת היא. ותמהים: אם כן \u0003תפשוט\u0004 \u0005[תפתור]\u0006 על ידי כך, אותה שאלה \u0003דבעא מיניה\u0004 \u0005[ששאל ממנו]\u0006 \u0003רבא מרב נחמן:\u0004 מי שהיה \u0003העלם זה וזה בידו,\u0004 כלומר, ששכח שיש איסור כללי בדבר, כגון שלא ידע ששבת היום וגם לא ידע שעבודות אלה אסורות בשבת, \u0003מהו?\u0004","ואותה שאלה נשארה בלתי פתורה במקומה, \u0003תיפשוט\u0004 \u0005[תפתור]\u0006 מכאן ש\u0003אינו חייב אלא אחת\u0004 לפי דרשה אחרונה זו. \u0003ו\u0004אכן תמוה שתיפתר כך שאלה שלא נמצא לה פתרון! ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 \u0003ותפשוט\u0004 את הבעיה מכאן.","ואולם על כל הלימוד העיקרי מקשים: \u0003ומי מצית מוקמת להני קראי\u0004 \u0005[האם יכול אתה להעמיד,\u0006 להסביר, \u0005את הכתובים האלה]\u0006 בענין \"אחת מהנה\" \u0003בעבודה זרה?\u0004 ש\u0003אילו הכא\u0004 \u0005[כאן]\u0006 בפרשה זו שכתוב בה \"אחת מהנה\" \u0003כתיב\u0004 \u0005[נאמר]\u0006 שכהן \u0003משיח\u0004 שחטא בשגגה מביא \u0003פר, ובנשיא\u0004 שכאשר שגג מביא \u0003שעיר, וביחיד\u0004 ששגג מביא \u0003כשבה\u0004 או \u0003שעירה,\u0004","\u0003ואילו בעבודה זרה תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ושוין ש\u0004הכהן הגדול ששגג מביא \u0003שעירה כ\u0004פי שמביא ה\u0003יחיד,\u0004 משמע שדיני שגגת עבודה זרה נלמדים כולם ממקור אחר (במדבר פרק ט\"ו).","ומסכמים: \u0003ותו לא מידי\u0004 \u0005[ושוב אין דבר],\u0006 כלומר, שוב אין להוסיף על כל טענה וויכוח בנושא זה, שהצעה זו ללמוד חילוק מלאכות בעבודה זרה אין לה כל בסיס, וקושייתו של רב יוסף נשארת קיימת במקומה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל לבבל, \u0003אמר:\u0004"],["\u0003הכי תנא קמיה\u0004 \u0005[כך שנה לפניו]\u0006 ר' זכאי לפני ר' יוחנן: \u0003חומר בשבת משאר מצות,\u0004 ולעומת זאת \u0003חומר בשאר מצות מבשבת.\u0004 כיצד? — \u0003חומר בשבת, שהשבת\u0004 אם \u0003עשה שתים\u0004 ממלאכותיה \u0003בהעלם אחד\u0004 (בשגגה אחת) — \u0003חייב על כל אחת ואחת\u0004 קרבן חטאת מיוחד, \u0003מה שאין כן בשאר מצות.\u0004 ואילו \u0003חומר בשאר מצות, שבשאר מצות\u0004 אם \u0003שגג בלא מתכוין,\u0004 כלומר, שעשה דבר ללא כוונה כלל למעשה עבירה זה — \u0003חייב\u0004 עליה קרבן, \u0003מה שאין כן בשבת.\u0004 את דברי הברייתא הזו מבררים עתה לפרטיהם.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חומר בשבת, שהשבת\u0004 אם \u0003עשה\u0004 בה \u0003שתים\u0004 בהעלם אחד חייב על כל אחת. \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אילימא דעבד\u0004 \u0005[אם תאמר שעשה]\u0006 שתי מלאכות בשבת כגון \u0003קצירה וטחינה, דכוותה גבי\u0004 \u0005[שכיוצא בה אצל]\u0006 \u0003שאר מצות\u0004 — ש\u0003אכל חלב ו\u0004אכל \u0003דם,\u0004 ואולם הרי במקרה כגון זה \u0003הכא תרתי מיחייב\u0004 \u0005[כאן\u0006 בשבת \u0005שתי\u0006 חטאות הוא \u0005מתחייב],\u0006 \u0003והכא תרתי מיחייב\u0004 \u0005[וכאן\u0006 בשאר המצוות גם כן \u0005שתים\u0006 הוא \u0005מתחייב]!\u0006","\u0003אלא, גבי\u0004 \u0005[אצל]\u0006 \u0003שאר מצות\u0004 ש\u0003אינו חייב אלא אחת היכי דמי\u0004 \u0005[כיצד הוא]?\u0006 — כגון ש\u0003אכל חלב ו\u0004אחר כך עוד \u0003חלב\u0004 בשגגה אחת, ולפיכך חייב רק חטאת אחת. ואולם \u0003דכוותה גבי\u0004 \u0005[כיוצא בה אצל]\u0006 \u0003שבת\u0004 — \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003קצירה וקצירה,\u0004 הרי גם במקרה כזה אין הבדל בדין; \u0003הכא\u0004 \u0005[כאן,\u0006 בשאר מלאכות\u0005]\u0006 \u0003חדא מיחייב\u0004 \u0005[\u0006חטאת \u0005אחת\u0006 הוא \u0005מתחייב],\u0006 \u0003והכא חדא מיחייב\u0004 \u0005[ו\u0006גם כאן בשבת חטאת \u0005אחת\u0006 הוא \u0005מתחייב]\u0006 ולא יותר! ולא נראה שיש חומרות המיוחדות לשבת ולשאר מצוות.","ומעירים: \u0003והיינו\u0004 \u0005[וזוהי]\u0006 הסיבה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' זכאי \u0003פוק תני לברא\u0004 \u0005[צא ושנה בחוץ]\u0006 שאין ברייתא זו ראויה להכנס לבית המדרש.","ותוהים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה]\u0006 שגרמה לר' יוחנן לבטל את הברייתא? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 \u0003דעבד\u0004 \u0005[שעשה]\u0006 מלאכות \u0003קצירה וטחינה\u0004 בשבת, ומה שנאמר \u0003\"מה שאין כן בשאר מצות\", אתאן\u0004 \u0005[הגענו]\u0006 בפירוש הברייתא \u0003ל\u0004דין \u0003עבודה זרה,\u0004 וכשיטת \u0003ר' אמי.\u0004 ש\u0003אמר ר' אמי:\u0004 מי ש\u0003זיבח וקיטר וניסך בהעלם אחד\u0004 — \u0003אינו חייב אלא אחת,\u0004 ואם כן הרי לנו הבדל בין מצוות שבת שעל כל פרט מפרטיה מתחייב לחוד, ובמצוה אחרת שיש בה כמה פרטי עבירה אין חייבים על כל אחד מהם אם עשאם כאחת.","ומסבירים: \u0003לא מיתוקמא ליה\u0004 \u0005[אינה\u0006 יכולה אותה ברייתא \u0005לעמוד,\u0006 להתפרש \u0005לו]\u0006 \u0003ב\u0004ענין \u0003עבודה זרה, דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנויה בסוף\u0006 אותה ברייתא\u0005]:\u0006 \u0003חומר בשאר מצות, שבשאר מצות שגג בלא מתכוין\u0004 — \u0003חייב.\u0004 ונברר האם דברים אלה יכולים להתייחס לגבי העובד עבודה זרה.","\u0003שוגג בלא מתכוין\u0004 כלל \u0003בעבודה זרה היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אי דקסבר\u0004 \u0005[אם שסבור]\u0006 ש\u0003בית הכנסת הוא והשתחוה לו\u0004 — \u0003הרי לבו לשמים\u0004 ובוודאי אין מקום לחייבו כלל, \u0003אלא\u0004 יש לומר \u0003דחזא אנדרטא וסגיד ליה\u0004 \u0005[שראה פסל אדם והשתחווה לו],\u0006 ובמקרה כזה \u0003אי קבליה עליה\u0004 \u0005[אם קיבלו\u0006 \u0003עליו]\u0004 \u0003באלוה\u0004 — הלא \u0003מזיד הוא\u0004 וחייב מיתה ולא קרבן, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא קבליה עליה\u0004 \u0005[קיבלו עליו]\u0006 — \u0003לא כלום היא\u0004 העבודה שעשה, ואפילו קרבן אינו מביא.","\u0003אלא\u0004 תפרש שעבד עבודה זרה \u0003מאהבה ומיראה\u0004 של אדם, \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003אביי,\u0004 ש\u0003אמר\u0004 ש\u0003חייב\u0004 על עבודה מעין זו, וזה שעבד שגג בחשבו כי הדבר מותר, \u0003אלא לרבא\u0004 ש\u0003אמר\u0004 ש\u0003פטור\u0004 על כך, ואינו חייב אלא אם קיבלו עליו כאלוה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי לפיו אין בכך אפילו שגגה!","\u0003אלא\u0004 אם תאמר ששגגה זו בעבודה זרה היתה \u0003באומר מותר,\u0004 שסבר שאין בכלל איסור עבודה זרה, \u0003מה שאין כן בשבת\u0004 שלפי שיטה זו בשבת יהיה \u0003פטור לגמרי\u0004 כשאומר מותר, בעוד שבעבודה זרה בשגגה כזאת חייב חטאת.","ואולם הרי \u0003עד כאן לא\u0004 שמענו כי \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן\u0004 בדיני שבת לגבי מי ש\u0003העלם זה וזה\u0004 בידו שנעלם ממנו יום השבת, ואף נעלם ממנו שמלאכות אלה אסורות, \u0003אלא\u0004 לענין זה היה דיון: \u0003אי לחיובי חדא אי לחיובי תרתי\u0004 \u0005[אם לחייבו\u0006 חטאת \u0005אחת או לחייבו שתים],\u0006 ואולם שיהיה \u0003פטור לגמרי\u0004 — \u0003ליכא למאן\u0004 \u0005[אין מי]\u0006 ש\u0003אמר\u0004 שיהיה פטור לגמרי כשלא ידע כלל דיני שבת! ואין איפוא להסביר שכך הובנה הברייתא המבדילה בין שבת למצוות אחרות.","את הקושיה הזו דוחים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה]\u0006 בדבר? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כך: \u0003רישא\u0004 \u0005[תחילת\u0006 אותה ברייתא\u0005]\u0006 המחלקת בין שבת לשאר מצוות — הרי הכוונה לחלוקה בין שבת ל\u0003עבודה זרה, וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בשאר מצות\u0004 חוץ מעבודה זרה.","ונסביר כך את הברייתא: \u0003ושגג בלא מתכוין\u0004 בשאר המצוות הרי זה כגון שהיה חלב בפיו \u0003דקסבר\u0004 \u0005[שסבר]\u0006 ש\u0003רוק הוא\u0004 בפיו \u0003ובולעו,\u0004 שאז חייב להביא קרבן על שגגתו זו. \u0003מה שאין כן בשבת\u0004 שבכגון זה \u0003פטור,\u0004 כגון מי \u0003שנתכוין להגביה את\u0004 הדבר \u0003התלוש\u0004 ונתברר שהיה הדבר מחובר, \u0003וחתך את המחובר\u0004 בלא דעת — \u0003פטור,\u0004 שאינו חייב בשבת על מלאכה שלא נתכוון לעשותה.","\u0003ו\u0004יתפרשו הדברים \u0003כ\u0004שיטת \u0003רב נחמן אמר שמואל,\u0004 ש\u0003אמר: המתעסק בחלבים\u0004 או \u0003בעריות\u0004 — \u0003חייב\u0004 קרבן על מה שעבר בהן, כלומר, גם מי שלא נתכוון כלל למעשה של עבירה, אלא נתעסק באלה לפי תומו ונזדמן לו בתוך כדי כך שאכל חלב או שבעל את הערוה, שאף שלא התכוון למעשה זה כלל — חייב, \u0003שכן\u0004 במציאות \u0003נהנה\u0004 מהדבר. ואולם \u0003המתעסק בשבת\u0004 — \u0003פטור,\u0004 שבשבת רק \u0003מלאכת מחשבת אסרה תורה,\u0004 ודבר שאינו עשוי בכוונה תחילה אינו קרוי \"מלאכת מחשבת\". ואם כן, אפשר לפרש ברייתא זו על פי ההלכה, ומדוע דחאה ר' יוחנן?","ומסבירים: \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 \u0003דלא מוקים מתניתא רישא בחד טעמא וסיפא בחד טעמא\u0004 \u0005[שאינו מעמיד,\u0006 מסביר, \u0005משנה תחילתה בטעם אחד וסופה בטעם אחד]\u0006 אם לא נאמר הדבר במפורש, ולשיטת הפרשנות שלו כל משנה עוסקת מתחילתה עד סופה בנושא אחד.","שכיוצא בו \u0003אמר ר' יוחנן: מאן דמתרגם\u0004 \u0005[מי שמסביר]\u0006 \u0003לי\u0004 את המשנה בענין \u0003חבית אליבא דחד תנא\u0004 \u0005[על פי שיטתו של תנא אחד],\u0006 \u0003מובילנא מאניה בתריה לבי מסותא\u0004 \u0005[אוביל\u0006 את \u0005בגדיו אחריו לבית המרחץ],\u0006 כלומר, אשמש אותו שימוש כעבד. שאף שיש מקום לפרש את המשנה ההיא ולחלק אותה לשני מקרים או על פי שתי שיטות — איני מקבל דרך פירוש זו. וכן דרכו בברייתא זו שאי אפשר לפרשה בנושא אחד, ואין הוא נכון לקיימה.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו קודם, אם מביאים יותר מחטאת אחת על עבודה זרה בשוגג,"],["\u0003אמר ר' אמי:\u0004 מי ש\u0003זיבח וקיטר וניסך בהעלם אחד\u0004 (בשגגה אחת) לעבודה זרה — \u0003אינו חייב\u0004 להביא \u0003אלא\u0004 קרבן חטאת \u0003אחת. אמר אביי: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אמי?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004לא תשתחוה להם ו\u0003לא תעבדם\"\u0004 (שמות כ, ה), \u0003הכתוב עשאן\u0004 את כל העבודות השונות \u0003כולן\u0004 כ\u0003עבודה אחת.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך],\u0006 כשיטת ר' אמי? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: שלש השתחואות,\u0004 כלומר, שלוש פעמים שנכתב בתורה איסור השתחוואה \u0003בעבודה זרה\u0004 (\"לא תשתחוה להם ולא תעבדם\". \u0005שמות כ, ד\u0006. \"לא תשתחוה לאלהיהם ולא תעבדם\" \u0005שמות כג, כד\u0006. \"כי לא תשתחוה לאל אחר\".\u0005 שמות לד, יד\u0006), \u0003למה\u0004 לי?","אלא, \u0003אחת לכדרכה,\u0004 שחייב על השתחוואה אם זו דרך הפולחן הרגילה של אותה עבודה זרה, \u0003ואחת\u0004 איסור השתחוואה לעבודה זרה, אפילו אם זו \u0003שלא כדרכה, ואחת לחלק\u0004 בין העבודות השונות בעבודה זרה, ללמדנו שחייב קרבן על כל אחת ואחת מהן שעשה. הרי שאין דעת אביי כר' אמי!","ומשיבים: אכן, רק \u0003לדבריו,\u0004 לפי דבריו ושיטתו, של \u0003ר' אמי קאמר\u0004 \u0005[אמר],\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[ולו,\u0006 הוא עצמו \u0005אינו סבור כן].\u0006","\u0003גופא\u0004 \u0005[לגוף]\u0006 מדרש ההלכה שהזכרנו, \u0003אמר אביי: שלש השתחואות\u0004 שנאמרו \u0003בעבודה זרה למה?\u0004 — \u0003אחת לכדרכה, ואחת שלא כדרכה ואחת לחלק.\u0004","ומקשים: והלא לאיסור השתחוואה \u0003לכדרכה\u0004 אין צורך בפסוק מיוחד, כי \u0003מ\"איכה יעבדו הגוים האלה\u0004 את אלהיהם ואעשה כן גם אני\u0003\"\u0004 (דברים יב, ל) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 האיסור, ואין צורך בלימוד מיוחד!","\u0003אלא\u0004 כך יש לומר: \u0003אחת\u0004 לחייב את המשתחווה לעבודה זרה כזו שההשתחוואה היא \u0003כדרכה ושלא כדרכה,\u0004 שעבודתה בדרך כבוד, אבל לא בהשתחוואה, \u0003ואחת\u0004 בהשתחוואה \u0003לשלא כדרכה\u0004 לגמרי, \u0003ואחת לחלק.\u0004","במשנה נמנים בין חייבי סקילה \u0003המקבלו עליו באלוה, האומר לו \"אלי אתה\". אמר רב נחמן אמר רבה בר אבוה אמר רב: כיון שאמר לו \"אלי אתה\"\u0004 אפילו לא עבדה — \u0003חייב.\u0004","ושואלים: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין אמר רב הלכה זו? \u0003אי לקטלא\u0004 \u0005[אם ל\u0006חייב \u0005מיתה]\u0006 למי שעשה כן בזדון — הלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 וודאי שלא בא לחזור על דברי המשנה, \u0003אלא ל\u0004חייב את האומר כן בשגגה \u0003קרבן\u0004 חטאת.","ותמהים: \u0003ו\u0004האם דעה זו היא \u0003אפילו לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אינו חייב\u0004 להביא קרבן \u0003אלא על דבר שיש בו מעשה, כגון זיבוח וקיטור וניסוך והשתחואה. ואמר ריש לקיש: מאן תנא\u0004 \u0005[מי שנה]\u0006 \u0003השתחואה\u0004 בכלל אלה? \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003מעשה\u0004 גמור כדי לחייבו, ועל כל עשיה שהיא מתחייב. ו\u0003מכלל\u0004 דבריו אתה למד \u0003דרבנן סברי\u0004 \u0005[שחכמים\u0006 החולקים על ר' עקיבא \u0005סבורים]\u0006 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003מעשה\u0004 של ממש. ואם השתחוואה אינה נחשבת מעשה — כל שכן אמירה בלבד!","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב נמי\u0004 \u0005[גם כן],\u0006 על פי שיטתו של \u0003ר' עקיבא קאמר\u0004 \u0005[אמר].\u0006","ותוהים: אם \u0003ל\u0004שיטת \u0003ר' עקיבא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003היינו\u0004 \u0005[\u0006הרי \u0005זהו]\u0006 בדיוק כמו \u0003מגדף,\u0004 שאף בו מחייב ר' עקיבא בלא מעשה!","ודוחים: בכל זאת יש בכך חידוש, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003עד כאן לא\u0004 שמענו שהיה \u0003מחייב ר' עקיבא קרבן אלא במגדף, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 במפורש שהעובר דינו \u0003כרת\u0004 (\"את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה\". במדבר טו, ל), \u0003אבל הכא\u0004 \u0005[כאן],\u0006 במקבל על עצמו עבודה זרה ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003כרת\u0004 במפורש \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן","\u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאתקושי אתקוש\u0004 \u0005[שהושוו\u0006 הדברים\u0005]\u0006 זה לזה בכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004...עשו להם עגל מסכה \u0003וישתחוו לו ויזבחו לו ויאמרו\u0004 אלה אלהיך ישראל אשר העלוך מארץ מצרים\u0003\"\u0004 (שמות לב, ח), ומכאן למדים שאמירה וזביחה דין אחד להם.","אגב הזכרת פסוק זה \u0003אמר ר' יוחנן: אלמלא וי\"ו שב\"העלוך\"\u0004 שאמרו בלשון רבים \u0003נתחייבו שונאיהם של ישראל\u0004 (כינוי לעם ישראל, בלשון סגי—נהור) \u0003כלייה,\u0004 שהרי בכל זאת לא כפרו בכל, שהודו שה' העלם ממצרים, אלא שעשו את העגל לשותף לו.","ומעירים: דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו באותו ענין, ששנינו, \u0003אחרים אומרים: אלמלא וי\"ו שב\"העלוך\" נתחייבו שונאיהם של ישראל כלייה,\u0004 שלא כפרו בקדוש ברוך הוא לגמרי, אלא ששיתפוהו בדבר אחר.","\u0003אמר לו ר' שמעון בן יוחאי: והלא כל המשתף שם שמים ודבר אחר\u0004 כשותף לה' \u0003נעקר מן העולם, שנאמר: \"\u0004זובח לאלהים יחרם \u0003בלתי לה' לבדו\"\u0004 (שמות כב, יט), ומכאן נלמד עד כמה חמורה העבירה של שיתוף, ואין לומר שאין חייבים עליה כליה. \u0003אלא מה תלמוד לומר: \"אשר העלוך\"\u0004 בלשון רבים? ללמדנו \u0003שאיוו אלוהות הרבה,\u0004 שלשון רבים זאת משמעה שרצו לעבוד לא רק את העגל, אלא גם אלים אחרים.","שנינו במשנה: \u0003אבל המגפף והמנשק\u0004 את העבודה זרה, ו\u0003המכבד והמרבץ\u0004 לפניה, אינו חייב מיתה אלא הם באזהרה בלבד, שעבר על מצוות \"לא תעשה\". \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' אלעזר: על כולם לוקה, חוץ מ\u0004מי שהיה \u0003נודר בשמו והמקיים בשמו.\u0004","ומקשים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003הנודר בשמו והמקיים בשמו דלא לקי\u0004 \u0005[שאינו לוקה]?\u0006 אם תאמר \u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 איסור \u0003לאו שאין בו מעשה,\u0004 שהרי לא עשה מעשה גמור, ולפיכך אין לוקים עליו, \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 המגפף והמנשק אין ללקות עליהם כי \u0003לאו שבכללות הוא,\u0004 כלומר, האיסור שבהם נובע מתוך מצות לא תעשה אחת בתורה שנלמדים ממנה דברים מרובים ושאינם מענין אחד, \u0003ו\u0004כלל הוא ש\u0003אין לוקין על לאו שבכללות!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בנושא זה: \u0003מנין לאוכל מן הבהמה קודם שתצא נפשה שהוא\u0004 עובר \u0003ב\"לא תעשה\"?\u0004 — \u0003תלמוד לומר: \"לא תאכלו על הדם\"\u0004 (ויקרא יט, כו), כלומר, בעוד הדם (נפש הבהמה הקרויה דם) בקרבה.","\u0003דבר אחר\u0004 נלמד מאותו פסוק \"\u0003לא תאכלו על הדם\u0004\" לומר: \u0003לא תאכלו בשר\u0004 מן הקרבנות \u0003ועדין דם במזרק,\u0004 שעדיין לא נזרק הדם על המזבח, שרק לאחר זריקה הותר הבשר לאכילת הכהנים.","\u0003ר' דוסא אומר: מניין שאין מברין על הרוגי בית דין,\u0004 שאין נותנים לאבלים, קרובי הנידון למוות, סעודה ראשונה משל אחרים, כשם שעושים \"סעודת הבראה\" לשאר אבלים? — \u0003תלמוד לומר: \"לא תאכלו על הדם\",\u0004 אל תאכלו סעודת הבראה על דם הנידונים.","\u0003ר' עקיבא אומר: מנין לסנהדרין שהרגו את הנפש,\u0004 שדנו אדם למות, \u0003שאין טועמין כלום כל אותו היום\u0004 שדנו בו? — \u0003תלמוד לומר: \"לא תאכלו על הדם\".\u0004","\u0003אמר ר' יוחנן: אזהרה לבן סורר ומורה מנין?\u0004 שאמנם ענשו של בן סורר ומורה נאמר, אך היכן נאמר שאסור לעשות מעשים אלה? — \u0003תלמוד לומר: \"לא תאכלו על הדם\",\u0004 שאסור לאכול אכילה זו שסופה שיידון עליה למוות, ודמו בראשו.","\u0003ואמר ר' אבין בר חייא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זה \u0003ר' אבין בר כהנא: על כולם,\u0004 על כל איסורים אלה שלמדו חכמים מכתוב זה \u0003אינו לוקה\u0004 אף על אחד מהם, \u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003לאו שבכללות\u0004 שכולל נושאים רבים ושונים בכתוב אחד, ואם כן כיון שאף המגדף והמנשק כולם נלמדים מלאו שבכללות, לא היה ראוי להלקות עליהם. וקשה לרב דימי!","\u0003אלא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' אלעזר\u0004 נוסח אחר: \u0003על כולן,\u0004 על כל העבירות המנויות במשנה, אף שעובר בהן על מצוות \"לא תעשה\" מן התורה \u0003אינו לוקה, חוץ מן הנודר בשמו והמקיים בשמו.\u0004","ושואלים: \u0003מאי שנא אהנך דלא לקי\u0004 \u0005[במה שונה על אלה\u0006 האחרים \u0005שאינו לוקה]?\u0006 משום \u0003דהוה ליה\u0004 \u0005[שהרי הם]\u0006 \u0003לאו שבכללות\u0004 כפי שבארנו, אך הרי \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 הנודר והמקיים בשם עבודה זרה \u0003לאו שאין בו מעשה נינהו\u0004 \u0005[הם],\u0006 ואין לוקים עליהם!","ומשיבים: הדין \u0003ההוא\u0004 של ר' אלעזר הוא \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: לאו שאין בו מעשה לוקין עליו.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בקרבן הפסח: \"ו \u0003לא תותירו ממנו עד בקר\u0004 והנותר ממנו עד בוקר באש תשרופו\" (שמות יב, י), \u0003בא הכתוב ליתן\u0004 מצות \u0003\"עשה\"\u0004 (\"באש תשרפו\") \u0003אחר \"לא תעשה\"\u0004 (של \"לא תותירו\"),"],["\u0003לומר שאין לוקין עליו,\u0004 שכל מצות \"לא תעשה\" שיש לה תיקון על ידי מעשה (\"ניתק לעשה\") אין לוקים עליה, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' יעקב אומר: לא מן השם הוא זה,\u0004 כלומר, לא מטעם זה אין לוקים, \u0003אלא משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 המותיר מבשר הפסח \u0003לאו שאין בו מעשה. ו\u0004כלל הוא ש\u0003כל לאו שאין בו מעשה אין לוקין עליו.\u0004","\u0003מכלל\u0004 דבריהם למדנו ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 שכל לאו שאין בו מעשה \u0003לוקין עליו.\u0004 ומכאן גם לענייננו שהנודר בשמו והמקיים בשמו של אליל חייב מלקות אף כי אין בו מעשה.","שנינו במשנה שכל \u0003הנודר בשמו והמקיים בשמו\u0004 — \u0003הרי זה ב\"לא תעשה\".\u0004 ושואלים: \u0003הנודר בשמו והמקיים בשמו מנלן\u0004 \u0005[מנין לנו]\u0006 איסור זה?","ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 משמעות הכתוב \u0003\"ושם אלהים אחרים לא תזכירו\u0004 לא ישמע על פיך\u0003\"\u0004 (שמות כג, יג), היא, \u0003שלא יאמר אדם לחבירו: שמור\u0004 (חכה) \u0003לי בצד עבודה זרה פלונית. \"לא ישמע על פיך\"\u0004 — \u0003שלא ידור\u0004 נדר \u0003בשמו, ולא יקיים\u0004 (ישבע או יאשר, יחזק) דבר \u0003בשמו, ולא יגרום לאחרים\u0004 (גויים) \u0003שידרו בשמו ויקיימו בשמו.\u0004","\u0003דבר אחר: \"לא ישמע על פיך\"\u0004 — הרי זו \u0003אזהרה\u0004 (המקור ללאו, לאיסור) \u0003למסית ולמדיח\u0004 שלא יעשו כן.","ותוהים: \u0003מסית\u0004 לשם מה צריך ללמדו מכאן? \u0003בהדיא כתיב ביה\u0004 \u0005[במפורש נאמר בו]\u0006 בענשו של מסית: \u0003\"וכל ישראל ישמעו ויראו\u0004 ולא יוסיפו לעשות כדבר הרע הזה בקרבך\u0003\"\u0004 (דברים יג, יב), שבפירוש נאמר איסור לאו (\"לא יוסיפו\")! \u0003אלא\u0004 יש לומר שהיא \u0003אזהרה למדיח\u0004 את הרבים לעבודה זרה, שאזהרתו לא נאמרה במפורש ונלמדת מכאן.","שנינו בברייתא ש\u0003לא יגרום לאחרים שידרו בשמו ושיקיימו בשמו.\u0004 ומעירים: \u0003מסייעא ליה לאבוה\u0004 \u0005[מסייעת\u0006 הברייתא \u0005לו ל\u0006שיטת \u0005אביו]\u0006 של \u0003שמואל,\u0004 ש\u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: אסור לאדם שיעשה שותפות עם הגוי,\u0004 כיון שבתוך עסקיהם המשותפים עלולים הם להגיע לסכסוך, ו\u0003שמא יתחייב לו\u0004 השותף הגוי \u0003שבועה, ונשבע בעבודה זרה שלו, והתורה אמרה \"לא ישמע על פיך\",\u0004 לא על פיך ואף לא תגרום שישמע בפי אחרים.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003עולא\u0004 מארץ ישראל לבבל, \u0003בת\u0004 \u0005[לן]\u0006 \u0003ב\u0004מקום הנקרא \u0003קלנבו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והיכא בת מר\u0004 \u0005[והיכן לן אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בקלנבו. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ושם אלהים אחרים לא תזכירו\",\u0004 ו\"קלנבו\" שם עבודה זרה הוא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: כל עבודה זרה הכתובה בתורה מותר להזכיר שמה\u0004 שכיון שהותר הדבר בקריאת המקרא הותר גם במקום אחר. ושאל רבא: \u0003והא היכא כתיבא\u0004 \u0005[ו\u0006עבודה זרה \u0005זו היכן\u0006 היא \u0005כתובה]?\u0006 אמר לו: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כרע בל קרס נבו\"\u0004 (ישעיה מו, א).","ושואלים: \u0003ואי לא כתיבא\u0004 \u0005[ואם אינה כתובה]\u0006 — \u0003לא,\u0004 אסור להזכיר את שמה?! \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב משרשיא\u0004 על כך ממה ששנינו במסכת זבים: \u0003ראה\u0004 הזב זיבה \u0003אחת מרובה כשלש\u0004 זיבות רגילות, \u0003שהיא\u0004 משך זמן הזיבה \u0003כ\u0004מהלך \u0003מ\u0004מקום העבודה זרה \u0003גדיון\u0004 עד \u0003לשילה, שהן\u0004 כשיעור זמן של \u0003שתי טבילות ושני ספוגין\u0004 (התנגבות במגבת, בספוג) — \u0003הרי זה זב גמור\u0004 אף בפעם יחידה זו, ואין צורך שתצא ממנו זיבה בשלוש פעמים נפרדות. מכל מקום במשנה זו נזכר \"גדיון\" אף על פי שהוא שם עבודה זרה!\u0003אמר רבינא: \"גד\" נמי מכתב כתיב\u0004 \u0005[גם כן כתוב\u0006 במקרא\u0005]\u0006\u0003,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הערכים לגד שלחן\"\u0004 (ישעיה סה, יא).","\u0003אמר רב נחמן: כל ליצנותא אסירא\u0004 \u0005[ליצנות אסורה],\u0006 \u0003חוץ מליצנותא\u0004 \u0005[מליצנות]\u0006 של \u0003עבודה זרה, דשריא\u0004 \u0005[ש\u0006היא \u0005מותרת].\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כרע בל קרס נבו... קרסו כרעו יחדו לא יכלו מלט משא\"\u0004 (ישעיה מו, א–ב), והוא מפרשו שהם כורעים לעשות צרכיהם ואינם יכולים לעצור את משא הצואה שלהם.","\u0003וכתיב\u0004 \u0005[וכתוב]\u0006 כעין זה: \u0003\"דברו... לעגלות בית און יגורו שכן שמרון כי אבל עליו עמו וכמריו עליו יגילו על כבודו\u0004 \u0003כי\u0004 \u0003גלה ממנו\"\u0004 (הושע י, ד-ה), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"כבודו\" אלא \"כבידו\",\u0004 כלומר, משא צואתו היוצא ממנו, וכל אלה לשון גנאי המותר כלפי עבודה זרה בלבד.","\u0003אמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ועתה יוספו לחטא ויעשו להם מסכה מכספם כתבונם עצבים\u0004 מעשה חרשים כלה להם הם אומרים זבחי אדם עגלים ישקון\u0003\"\u0004 (הושע יג, ב), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כתבונם עצבים\"? מלמד שכל אחד ואחד עשה דמות\u0004 (\"תבונם\" = תבניתם) \u0003יראתו\u0004 (אליל שלו) \u0003ומניחה בכיסו, בשעה שזוכרה\u0004 (נזכר בה) \u0003מוציאה מתוך חיקו ומחבקה ומנשקה.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זבחי אדם עגלים ישקון\"\u0004 (הושע יג, ב)? \u0003אמר ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי: שהיו כומרים נותנים עיניהם בבעלי ממון, ומרעיבים את העגלים\u0004 שהיו להם כעבודה זרה, \u0003ועושין דמות עצבים\u0004 (פסלים) כתבניתם של בעלי ממון אלה, \u0003ומעמידין\u0004 אותם עצבים \u0003בצד אבוסיהן\u0004 של העגלים \u0003ומוציאין אותן\u0004 את העגלים \u0003לחוץ. כיון שראו אותן\u0004 העגלים את בעלי הממון, והרי היו רגילים לראות דמויות כעין אלה ליד אבוסם, היו \u0003רצין אחריהן וממשמשין בהן.\u0004 ואז היו \u0003אומרים\u0004 הכמרים \u0003לו\u0004 לאותו איש: \u0003עבודה זרה חפץ בך,\u0004 שהרי העגל בא ומנשק אותך, \u0003יבא ויזבח\u0004 האיש את \u0003עצמו לו\u0004 והיו יורשים את רכושו.","\u0003אמר רבא:\u0004 פירוש זה אינו מדוקדק בפסוק כי \u0003האי\u0004 \u0005[\u0006לשון \u0005זה]\u0006 \u0003\"זבחי אדם עגלים ישקון\"\u0004 אינו מתאים, אלא \u0003\"עגלים ישקון לזבח אדם\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא אמר רבא,\u0004 כך יש להבין את הפסוק: \u0003כל הזובח את בנו לעבודה זרה, אמר לו\u0004 הכומר: \u0003דורון גדול הקריב לו\u0004 לעבודה זרה, ולכן זכותו ש\u0003יבא וישק לו.\u0004 הוא שנאמר \"זובחי אדם\" — יהיה שכרם שעגלים ישקו.","\u0003אמר רב יהודה אמר רב:\u0004 נאמר בבני העמים שהושיבו האשורים בשומרון: \u0003\"ואנשי בבל עשו את סכות בנות\"\u0004 (מלכים ב' יז, ל), \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 ענין עבודה זרה זו? — דמות \u0003תרנגולת. \"ואנשי כות עשו את נרגל\"\u0004 (מלכים ב' יז, ל), \u0003ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 — \u0003תרנגול. \"ואנשי חמת עשו את אשימא\"\u0004 (מלכים ב' יז, ל), \u0003ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 \u0003ברחא קרחא\u0004 \u0005[תיש קרח].\u0006 \u0003\"והעוים עשו את נבחן ואת תרתק\"\u0004 (מלכים ב' יז, לא), \u0003ומאי ניהו\u0004 \u0005[ומה הם]?\u0006 \u0003כלב וחמור.\u0004","\u0003\"והספרוים שרפים את בניהם\u0004 \u0003ואת בנותיהם באש לאדרמלך וענמלך אלהי ספרוים\"\u0004 (מלכים ב' יז, לא), \u0003ומאי ניהו\u0004 \u0005[ומה הם]?\u0006 — \u0003הפרד והסוס.\u0004 ומשום מה קרואים הם כך? \u0003אדרמלך\u0004 קרוי פרד משום \u0003דאדר ליה למריה\u0004 \u0005[מהדר את אדוניו]\u0006 \u0003בטעינה,\u0004 משום שהוא טוען במשא האדון, \u0003וענמלך\u0004 קרוי הסוס משום \u0003דעני ליה למריה בקרבא\u0004 \u0005[שעונה\u0006 ומסייע \u0005לו לאדוניו בקרב].\u0006","ומספרים: \u0003אף חזקיה מלך יהודה ביקש אביו לעשות לו כן,\u0004 לשרפו למולך, \u0003אלא שסכתו אמו\u0004 בדם \u0003סלמנדרא\u0004 שהיא חיה היוצאת מתנור שבוערת בו האש שבע שנים והסך מדמה אינו נשרף.","\u0003אמר רב יהודה אמר רב: יודעין היו ישראל בעבודה זרה שאין בה ממש\u0004 ולא האמינו בה, \u0003ולא עבדו עבודה זרה אלא\u0004 כדי \u0003להתיר להם עריות בפרהסיא,\u0004 שרוב פולחנן היה כרוך בגילוי עריות בפרהסיה, ורק לכך דבקו בעבודה זרה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב משרשיא:\u0004 נאמר: \u0003\"כזכר בניהם מזבחותם\u0004 ואשריהם על עץ רענן על גבעות הגבוהות\u0003\"\u0004 (ירמיה יז, ב), \u0003ואמר רבי אלעזר: כאדם שיש לו געגועין על בנו\u0004 כך נזכרו הם בעבודה זרה שלהם! ומדרשה זו משמע שדבקו באמת בעבודה זרה.","ומשיבים: דבר זה היה \u0003בתר דאביקו ביה\u0004 \u0005[לאחר\u0006 \u0003שדבקו בה\u0004 בעבודה זרה\u0005]\u0006 שאז החלו להאמין בה באמת, אך מתחילה לא נהו אחריה אלא בשל תאוותם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שהיו דבוקים לעבודה זרה מחמת עצמה ולא בשל תאוה לעריות: על הנאמר \u0003\"ונתתי\u0004 את \u0003פגריכם על פגרי גלוליכם\"\u0004 (ויקרא כו, ל). \u0003אמר, אליהו הצדיק\u0004 (הנביא) \u0003היה מחזר על תפוחי\u0004 (נפוחי) \u0003רעב ש\u0004היו \u0003בירושלים. פעם אחת מצא תינוק\u0004 אחד \u0003שהיה תפוח ומוטל באשפה.\u0004","\u0003אמר לו\u0004 אליהו לתינוק: \u0003מאיזה משפחה אתה? אמר לו\u0004 התינוק: \u0003ממשפחה פלונית אני. אמר לו\u0004 אליהו: \u0003כלום\u0004 (האם) \u0003נשתייר\u0004 מישהו \u0003מאותה משפחה? אמר לו\u0004 התינוק: \u0003לאו\u0004 \u0005[לא]\u0006 נשתייר מהם אף אחד \u0003חוץ ממני. אמר לו\u0004 אליהו: \u0003אם אני מלמדך דבר שאתה חי בו, אתה למד? אמר לו\u0004 התינוק: \u0003הן\u0004 (כן). \u0003אמר לו\u0004 אליהו: \u0003אמור בכל יום \"שמע ישראל ה' אלהינו ה' אחד\"\u0004 (דברים ו, ד). \u0003אמר לו\u0004 אותו תינוק:"],["\u0003הס, שלא להזכיר בשם ה'\u0004 (ראה עמוס ו, י), שלא רצה התינוק אף לשמוע הזכרת ה', \u0003שלא לימדו אביו ואמו.\u0004","\u0003מיד הוציא\u0004 אותו תינוק את \u0003יראתו מחיקו ומחבקה ומנשקה, עד שנבקעה כריסו\u0004 מחמת רעב \u0003ונפלה יראתו לארץ ונפל הוא עליה, לקיים מה שנאמר \"ונתתי את פגריכם על פגרי גלוליכם\"\u0004 (ויקרא כו, ל), הרי שהיו דבוקים בעבודה זרה! ומשיבים: גם דבר זה היה \u0003בתר דאביקו ביה\u0004 \u0005[לאחר שדבקו בה].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 עוד ראיה: נאמר \u0003\"ויזעקו בקול גדול אל ה' אלהיהם\"\u0004 (נחמיה ט, ד), ושואלים: \u0003מאי אמור\u0004 \u0005[מה אמרו]\u0006 באותה תפילה וזעקה? \u0003אמר רב יהודה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יונתן: \"\u0004\u0003בייא בייא\"\u0004 \u0005[\"ווי ווי\"]!\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 היצר הרע של עבודה זרה, \u0003דאחרביה לביתא וקליא להיכלא, וקטלינהו לצדיקי, ואגלינהו לישראל מארעייהו\u0004 \u0005[שהחריב את בית\u0006 המקדש, \u0005ושרף את ההיכל, והרג את הצדיקים, והגלה את ישראל מארצם],\u0006 \u0003ועדיין הוא מרקד בינן\u0004 \u0005[בינינו].\u0006 \u0003כלום\u0004 האם לא \u0003יהבתיה לן\u0004 \u0005[נתתו לנו]\u0006 \u0003אלא\u0004 כדי \u0003לקבולי ביה אגרא\u0004 \u0005[שנקבל בו שכר]\u0006 כאשר נכבוש יצר זה — \u0003לא איהו בעינן\u0004 \u0005[אותו אנו רוצים]\u0006 \u0003ולא אגריה בעינן\u0004 \u0005[\u0006את \u0005שכרו אנו רוצים].\u0006 הרי שהיו קשורים מאד לעבודה זרה! ודוחים: גם זו \u0003בתר דאביקו ביה\u0004 \u0005[אחר שדבקו בה]\u0006 בעבודה זרה.","וממשיכים את המעשה באנשי כנסת הגדולה: \u0003יתבו תלתא יומא בתעניתא, בעו רחמי\u0004 \u0005[ישבו שלושה ימים בתענית, בקשו רחמים]\u0006 משמים. \u0003נפל להו פיתקא מרקיעא דהוה כתיב בה\u0004 \u0005[להם פתק מן הרקיע שהיה כתוב בו]\u0006 \u0003\"אמת\",\u0004 לומר שהסכים ה' לבקשתם.","על כך \u0003אמר ר' חנינא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003חותמו של הקדוש ברוך הוא \"אמת\"\u0004 הוא, שפתק זה היה סימן שמסכים למה שבקשו.","\u0003נפק כגוריא דנורא\u0004 \u0005[יצא כגור\u0006 אריות \u0005של אש]\u0006 \u0003מבית קדשי הקדשים. אמר להו\u0004 \u0005[להם]\u0006 זכריה ה\u0003נביא לישראל: היינו יצרא\u0004 \u0005[זהו יצר\u0006 הרע\u0005]\u0006 של \u0003עבודה זרה. בהדי דקתפסי ליה אישתמיט ביניתא מיניה, ואזל קליה בארבע מאה פרסי\u0004 \u0005[תוך כדי שתפסו אותו נשמטה,\u0006 נמרטה, \u0005שערה ממנו, והלך קולו\u0006 מחמת הכאב \u0005ארבע מאות פרסה].\u0006 \u0003אמרו: היכי ניעבד\u0004 \u0005[כיצד נעשה],\u0006 \u0003דילמא משמיא מרחמי עליה\u0004 \u0005[שמא משמים ירחמו עליו]\u0006 אם נבוא להרגו, שהרי ודאי יצעק עוד יותר?","\u0003אמר להו\u0004 \u0005[להם]\u0006 ה\u0003נביא: שדיוהו בדודא דאברא, וכסיוה באברא, דשייף קליה\u0004 \u0005[זרקו אותו בתוך דוד של עופרת, וכסו אותו בעופרת, שישאב\u0006 את \u0005קולו\u0006 ולא ישמע\u0005].\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר זאת הרשעה וישלך אתה אל תוך האיפה וישלך את האבן העופרת אל פיה\"\u0004 (זכריה ה, ח), וכך נפטרו מיצר הרע של עבודה זרה.","\u0003אמרי\u0004 \u0005[אמרו]\u0006 אז: \u0003הואיל ועת רצון הוא ניבעי רחמי איצרא\u0004 \u0005[נבקש רחמים\u0006 שניפטר גם \u0005מיצר]\u0006 ה\u0003עבירה,\u0004 יצר המין, \u0003בעו רחמי, אימסר בידייהו\u0004 \u0005[בקשו רחמים ונמסר בידם].\u0006","\u0003חבשוהו תלתא יומי\u0004 \u0005[כלאו אותו,\u0006 את היצר הרע הזה, \u0005שלושה ימים],\u0006 \u0003איבעו ביעתא\u0004 \u0005[הוצרכו\u0006 ל\u0005ביצה\u0006 טריה\u0005]\u0006 \u0003בת יומא\u0004 \u0005[יום]\u0006 \u0003לחולה, ולא אשכחו\u0004 \u0005[מצאו],\u0006 שבטל יצר המין מן העולם ולא נוצרו עוד ביצים. \u0003אמרו: היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 אם \u0003ניבעי פלגא\u0004 \u0005[נבקש\u0006 רק \u0005חצי]\u0006 שיבטל חצי כוחו, יודעים אנו כי \u0003פלגא מרקיעא לא יהבי\u0004 \u0005[מחצית\u0006 דבר \u0005מן השמים אין נותנים].\u0006 מה עשו? \u0003כחלינהו לעיניה\u0004 \u0005[עוורו את עיניו]\u0006 של יצר רע זה, \u0003אהני ביה דלא איגרי איניש בקרובתיה\u0004 \u0005[הועיל\u0006 הדבר \u0005בו,\u0006 ביצר \u0005ש\u0006שוב \u0005אין אדם מתגרה\u0006 כל כך \u0005בקרובותיו]\u0006 האסורות לו.","\u0003אמר רב יהודה אמר רב: מעשה בגויה אחת שהיתה חולה ביותר, אמרה\u0004 על עצמה: \u0003אם תעמוד\u0004 (תחלים) \u0003ההיא אשה,\u0004 כלומר, אני \u0003מחוליה, תלך ותעבוד לכל עבודה זרה שבעולם. עמדה\u0004 מחוליה והלכה \u0003ועבדה לכל עבודה זרה שבעולם. כיון שהגיע לפעור, שאלה לכומרים: במה עובדין לזו? אמרו לה: אוכלין תרדין\u0004 (שהם משלשלים), \u0003ושותין שכר\u0004 שאף הוא משלשל, \u0003ומתריזין בפניה\u0004 צואה. \u0003אמרה: מוטב שתחזור ההוא אשה לחוליה, ולא תעבוד עבודה זרה בכך.\u0004","ודרש רב יהודה: \u0003אתם בית ישראל אינן כן,\u0004 כאשה זו שלא יכלה לסבול את הגועל שבדבר, אלא נאמר בהם ביחסם לעבודה זרה \u0003\"הנצמדים לבעל פעור\"\u0004 (במדבר כה, ה) — שהוא דביקות מרובה \u0003כצמיד\u0004 \u0003פתיל\u0004 הכרוך בחוזק על הכלי, ואולם ביחסם כלפי הקדוש ברוך נאמר בהם \u0003\"ואתם הדבקים בה' אלהיכם\"\u0004 (דברים ד, ד) — \u0003כשתי תמרות הדבוקות זו בזו\u0004 שהן רק נוגעות אבל לא צמודות בחוזקה.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]\u0006 אותה השוואה ברוח שונה: \u0003\"הנצמדים לבעל פעור\"\u0004 — \u0003כצמיד על ידי אשה,\u0004 שאינו הדוק אלא רק סמוך לה. \u0003\"ואתם הדבקים בה' אלהיכם\"\u0004 — \u0003דבוקים ממש.\u0004","ועוד לענין פעור \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה\u0004 ביהודי אחד \u0003סבטא בן אלס\u0004 שמו, \u0003שהשכיר חמורו\u0004 ואת שירותיו \u0003לגויה אחת,\u0004 והיה מחמר אחריה. \u0003כיון שהגיעה לפעור, אמרה לו: המתן עד שאכנס ואצא. לאחר שיצאה אמר לה: אף את המתיני עד שאכנס ואצא. אמרה לו: ו\u0004כי \u0003לא יהודי אתה?\u0004 וכיצד הנך עובד עבודה זרה? \u0003אמר לה: ומאי\u0004 \u0005[ומה]\u0006 \u0003איכפת ליך\u0004 \u0005[לך]?\u0006 \u0003נכנס, פער בפניו\u0004 של הפסל עצמו, \u0003וקינח\u0004 עצמו \u0003בחוטמו,\u0004 שרצה לבזות עבודה זרה ככל האפשר, אלא שלא עלתה בידו כי \u0003היו כומרין\u0004 של פעור \u0003מקלסין\u0004 (משבחים) \u0003לו, ואומרים: מעולם לא היה אדם שעבדו לזו בכך,\u0004 עבודה משובחת כל כך. שהוא נתכוון לבזות את פעור והתברר שעשה לו עבודה כדרכו.","וכך היא ההלכה: \u0003הפוער עצמו לבעל פעור\u0004 — \u0003הרי זה עבודתו, אף על גב דמיכוין לביזוי\u0004 \u0005[אף על פי שמתכוון לבזותו],\u0006 והעושה כן הריהו שוגג בעבודה זרה. וכן \u0003הזורק אבן למרקוליס\u0004 — \u0003זו היא עבודתו, אף על גב דמיכוין למירגמיה\u0004 \u0005[אף על פי שמתכוון לרוגמו].\u0006","מסופר: \u0003רב מנשה הוה קאזיל\u0004 \u0005[היה הולך]\u0006 \u0003ל\u0004מקום הקרוי \u0003בי תורתא. אמרו לו: עבודה זרה היא דקאי הכא\u0004 \u0005[שעומדת כאן]\u0006 בגל אבנים זה. \u0003שקל פיסא שדא ביה\u0004 \u0005[לקח רגב וזרק בו]\u0006 לבזותה, \u0003אמרו לו: מרקוליס היא\u0004 ועבודתו בזריקה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"הזורק אבן למרקוליס\" תנן\u0004 \u0005[שנינו],\u0006 שזורק לפניו בדרך פולחן ואני לבזותו נתכוונתי.","\u0003אתא\u0004 \u0005[הלך]\u0006 ו\u0003שאל בי מדרשא\u0004 \u0005[בבית המדרש]\u0006 מהי הגרסה המדוייקת. \u0003אמרו לו: \"הזורק אבן במרקוליס\" תנן\u0004 \u0005[שנינו],\u0006 ומשמע: \u0003אף על גב דמיכוין למירגמיה\u0004 \u0005[אף על פי שנתכוין לרוגמו].\u0006 \u0003אמר להו\u0004 \u0005[להם,\u0006 לחכמים\u0005]:\u0006 \u0003איזיל אישקלה\u0004 \u0005[אלך\u0006 ו\u0005אקח אותה]\u0006 את האבן שזרקתי. \u0003אמרו לו: אחד הנוטלה ואחד הנותנה\u0004 — \u0003חייב,\u0004 ומדוע? — \u0003כל חדא וחדא רווחא לחבירתה שביק\u0004 \u0005[כל אחת ואחת,\u0006 מן האבנים הנלקחות משם, \u0005רווח לחברתה\u0006 היא \u0005מותירה],\u0006 שאם אתה מסלק אחת הרי נותן אתה מקום לחברתה.","\u0003הנותן מזרעו למולך\u0004 שנאמר בתורה שעונשו סקילה, \u0003אינו חייב עד שימסור\u0004 את ילדיו \u0003למולך\u0004 (לכמרים של המולך), \u0003ויעביר\u0004 את הילד \u0003באש. מסר למולך ולא העביר באש,\u0004 או ש\u0003העביר באש ולא מסר למולך\u0004 — \u0003אינו חייב עד שימסור למולך ויעביר באש.\u0004","\u0003קתני\u0004 \u0005[שנה]\u0006 בתחילת המשנה (ס,ב) \u0003עבודה זרה\u0004 דרכי ההתחייבות בעבודתה לחוד, \u0003וקתני\u0004 \u0005[ושנה]\u0006 כיצד מתחייבים בעבודת ה\u0003מולך\u0004 לחוד ולא צרפם יחד. \u0003אמר ר' אבין:\u0004 מכאן משמע כי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מולך לאו\u0004 \u0005[לא]\u0006 \u0003עבודה זרה היא\u0004 כשאר עבודות זרות, אלא ייחוד יש לה, שאין עבודתה אלא בדרך מיוחדת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 מחלוקת בענין זה: \u0003אחד\u0004 המוסר והמעביר בנו \u0003למולך, ואחד\u0004 המוסרו כן \u0003לשאר עבודה זרה\u0004 — \u0003חייב,\u0004 שאין מולך אלא דוגמה לשאר עבודות זרות. \u0003ר' אלעזר בר' שמעון אומר:\u0004 המוסר \u0003למולך\u0004 — \u0003חייב, שלא למולך\u0004 — \u0003פטור.\u0004","\u0003אמר אביי: ר' אלעזר בר' שמעון ור' חנינא בן אנטיגנוס אמרו דבר אחד\u0004 בהלכה, ששיטה אחת להם. כיצד? — \u0003ר' אלעזר בר' שמעון הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006 וכן מצאנו בדברי \u0003ר' חנינא בן אנטיגנוס\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 ש\u0003ר' חנינא בן אנטיגנוס אומר: מפני מה תפסה תורה לשון \"מולך\"?\u0004 — לומר: \u0003כל\u0004 דבר \u0003שהמליכוהו עליהם\u0004 וקראו \"מולך\", ו\u0003אפילו\u0004 היה זה \u0003צרור, ואפילו קיסם,\u0004 אך משמע כי המעביר בנו למי שאינו נקרא \"מולך\" אינו חייב, והרי שדעתו כדעת ר' אלעזר בר' שמעון.","\u0003רבא אמר:\u0004 לא שיטה אחת היא, ויש הבדל בין השיטות, שלגבי \u0003מולך עראי איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שלר' אלעזר בר' שמעון חייבים רק על מולך הקבוע לכך, ולר' חנינא אף על פולחן עראי."],["\u0003אמר ר' ינאי: אינו חייב\u0004 על מסירה למולך \u0003עד שימסרנו\u0004 את בנו \u0003לכומרים, שנאמר: \"ומזרעך לא תתן להעביר למלך\"\u0004 (ויקרא יח, כא), הרי שהאיסור קשור בנתינה — מסירה לכמרי המולך.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יכול העביר\u0004 את בנו באש \u0003ולא מסר\u0004 אותו לכמרי המולך \u0003יהא חייב?\u0004 — \u0003תלמוד לומר: \"לא תתן\",\u0004 כלומר, נתינה מעכבת. \u0003מסר למולך ולא העביר\u0004 באש, \u0003יכול יהא חייב?\u0004 — \u0003תלמוד לומר: \"להעביר\"\u0004 שאף העברה מעכבת. \u0003מסר והעביר שלא למולך\u0004 אלא לעבודה זרה אחרת, \u0003יכול יהא חייב?\u0004 — \u0003תלמוד לומר: \"למלך\".\u0004","\u0003מסר והעביר למולך ולא\u0004 העביר \u0003באש, יכול יהא חייב?\u0004 — \u0003נאמר כאן \"להעביר\" ונאמר להלן \"לא ימצא בך מעביר בנו ובתו באש\"\u0004 (דברים יח, י), \u0003מה להלן\u0004 העברה זו היא \u0003באש\u0004 דווקא, \u0003אף כאן באש. ומה כאן\u0004 מדובר שמעביר ל\u0003מולך, אף להלן מולך\u0004 דווקא.","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא:\u0004 אדם ש\u0003העביר\u0004 את \u0003כל זרעו\u0004 למולך — \u0003פטור, שנאמר \"מזרעך\"\u0004 לצמצם: \u0003ולא כל זרעך.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: העביר\u0004 את הבן והוא, הבן, \u0003סומא מהו?\u0004 או שמעבירו כשהוא \u0003ישן, מהו\u0004 הדין בכגון זה? האם צריך שיהא הבן מסוגל לעבור בעצמו, או שאין זה מעכב? וכן אם העביר את \u0003בן בנו\u0004 או את \u0003בן בתו מהו?\u0004","ומשיבים: \u0003תפשוט מיהא חדא\u0004 \u0005[תפתור לפחות אחת]\u0006 משאלות אלה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"כי מזרעו נתן למלך\"\u0004 (ויקרא כ, ג), \u0003מה תלמוד לומר\u0004 בתוספת זו? — \u0003לפי שנאמר \"לא ימצא בך מעביר בנו ובתו באש\", אין לי\u0004 ללמוד מכאן \u0003אלא\u0004 איסור כשמעביר \u0003בנו ובתו\u0004 בלבד, ואולם \u0003בן בנו ובן בתו מנין\u0004 שחייב אף עליהם? — \u0003תלמוד לומר: \"בתתו מזרעו\"\u0004 (ויקרא כ, ד), ו\"מזרעו\" כולל גם את אלה, ואם כן נפתרה אחת משאלותיו של רב אשי.","ושואלים: \u0003ה\u0004\u0003תנא פתח\u0004 את דרשתו \u0003ב\"כי מזרעו\" וסליק\u0004 \u0005[וגמר]\u0006 בדרשה מן הכתוב \u0003\"בתתו מזרעו\",\u0004 ומפני מה הביא ראיה משני פסוקים שונים?!","ומסבירים: \u0003דרשה אחרינא הוא\u0004 \u0005[אחרת היא]\u0006 שנאמרה על הפסוק השני, ונשמטה מן הברייתא. וכך יש להשלים: ממה שנאמר \u0003\"זרעו\"\u0004 הייתי אומר ש\u0003אין לי אלא זרע כשר,\u0004 כלומר, צאצאיו שנולדו לו מאשה הנשואה לו כדין, ואולם \u0003זרע פסול\u0004 כגון ממזרים שלו \u0003מנין\u0004 שחייב עליהם? \u0003תלמוד לומר: \"בתתו מזרעו\"\u0004 לומר כל שהוא מזרעו חייב עליו.","\u0003אמר רב יהודה: אינו חייב עד שיעבירנו דרך העברה.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 דרך העברה? \u0003אמר אביי: שרגא דליבני במיצעי\u0004 \u0005[שורת לבנים באמצע],\u0006 \u0003נורא מהאי גיסא ונורא מהאי גיסא\u0004 \u0005[אש מצד זה ואש מצד זה],\u0006 ודרך העברה באש היא שמעבירו בהליכה על גבי שורת הלבנים בין שתי המדורות.","\u0003רבא אמר: כמשוורתא דפוריא\u0004 \u0005[כמו הקפיצות של פורים],\u0006 שנהגו להדליק מדורה בתוך גומה וילדים היו משתעשעים בפורים בקפיצה מעל המדורה, וכאשר מעביר את בנו בתוך האש באופן זה הוא הנקרא דרך העברה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא,\u0004 ששנינו: \u0003אינו חייב עד שיעבירנו דרך עברה. העבירה ברגל\u0004 — \u0003פטור.\u0004 הרי שדרך העברה זו בקפיצה היא ולא בהליכה, ושלא כדברי אביי.","\u0003ו\u0004עוד שנינו באותה ברייתא: \u0003אינו חייב אלא על יוצאי יריכו.\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — העביר את \u0003בנו\u0004 או \u0003בתו\u0004 — \u0003חייב,\u0004 העביר את \u0003אביו ואמו אחיו ואחותו\u0004 שאינם מזרעו — \u0003פטור. העביר עצמו\u0004 למולך — \u0003פטור, ור' אלעזר בר' שמעון מחייב\u0004 כשמעביר עצמו.","\u0003אחד\u0004 המעביר \u0003למולך ואחד לשאר עבודה זרה\u0004 — \u0003חייב. ר' אלעזר בר' שמעון אומר: למולך\u0004 — \u0003חייב, שלא למולך\u0004 — \u0003פטור.\u0004","\u0003אמר עולא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר בר' שמעון\u0004 המחשב את מעביר עצמו: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא ימצא בך\u0004 מעביר בנו ובתו באש\u0003\"\u0004 (דברים יח, י), והוא דורש: \u0003\"בך\"\u0004 — \u0003בעצמך,\u0004 שאף הוא בכלל האיסור.","ושואלים: \u0003ורבנן לא דרשי\u0004 \u0005[ו\u0006כי \u0005חכמים אינם דורשים]\u0006 \u0003\"בך\"\u0004 במובן של בעצמך? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אבידתו\u0004 שלו \u0003ואבידת אביו\u0004 שמצאן יחד וצריך לטרוח ולהשיבן — אבידתו \u0003שלו קודמת. ואמרינן\u0004 \u0005[ואמרנו]\u0006 כשעסקנו באותה משנה: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003ואמר רב יהודה: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"אפס כי לא יהיה בך אביון\"\u0004 (דברים טו, ד) — \u0003שלו קודמת לשל כל אדם.\u0004 ולכאורה הראיה היא ממה שנאמר \"לא יהיה בך\", בך — בעצמך, שאתה עצמך צריך לדאוג שלא תהיה אביון, ומכאן שחכמים דורשים \"בך\"!","ודוחים: \u0003והתם\u0004 \u0005[ושם]\u0006 הלימוד הוא \u0003מ\u0004מה שנאמר \u0003\"אפס\",\u0004 שהוא ביטוי של צמצום והגבלה, לומר כי עליו לדאוג שלא יהא אביון, ולהתחיל ממנו עצמו.","\u0003אמר ר' יוסי בר' חנינא: שלש כריתות\u0004 שנאמרו \u0003בעבודה זרה,\u0004 שנאמרו פעמיים במולך (\"ואני אתן את פני באיש ההוא והכרתי אותו מקרב עמו\". ויקרא כ, ג. \"ושמתי אני את פני באיש ההוא ובמשפחתו והכרתי אותו\". ויקרא כ, פסוק ה), ופעם במגדף (\"את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה\". במדבר טו, ל), \u0003למה?\u0004","— \u0003אחת ל\u0004מי שעובדה \u0003כדרכה, ואחת לשלא כדרכה, ואחת למולך.\u0004","\u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מולך עבודה זרה היא\u0004 כשאר עבודות זרות, \u0003כרת\u0004 מיוחד \u0003במולך למה לי?\u0004 ומשיבים: \u0003למעביר בנו שלא כדרכה,\u0004 שלשיטה זו המעביר בנו באש לכל עבודה זרה אף שאינו כדרך עבודתה, כיון שהתורה אסרה מעשה זה — חייב.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מגדף\u0004 שנאמר בתורה \u0003עבודה זרה היא\u0004 ואינו איסור מיוחד, אם כן \u0003כרת\u0004 מיוחד \u0003במגדף למה לי?\u0004","ומשיבים: \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין זה. שיש צורך בכרת אחד לכריתות האדם על ידי מותו בעולם הזה, ופסוק שני לכרת בעולם הבא שתכרת נפשו ולא תזכה לחיי נצח. נאמר שם \"כי דבר ה' בזה ואת מצותו הפר \u0003הכרת תכרת\u0004 הנפש ההיא עוונה בה\" (במדבר טו, לא), \u0003\"הכרת\"\u0004 — משמעו שנכרת האדם ומת בקיצור ימים \u0003בעולם הזה, \"תכרת\"\u0004 — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003אמר לו ר' ישמעאל: והלא כבר נאמר\u0004 במגדף \u0003\"ונכרתה\u0004 הנפש ההיא מקרב עמה\u0003\"\u0004 (במדבר טו, ל), ולשיטתך שדורשים כל מלה \u0003וכי שלשה עולמים יש? אלא: \"ונכרתה\"\u0004 — כוונתו \u0003בעולם הזה, \"הכרת\"\u0004 — \u0003לעולם הבא, \"תכרת\"\u0004 — אינו בא להוסיף דבר, אלא \u0003דברה תורה כלשון בני אדם\u0004 שכפילות הלשון כגון \"הכרת תכרת\" הוא חלק מן הסגנון המקראי ואין ללמוד ממנו."],["בין אלה החייבים סקילה נמנים המכשפים. ומפרטים: \u0003בעל אוב\u0004 — \u0003זה\u0004 הקרוי \u0003פיתום,\u0004 והוא שקולו של המת נשמע כ\u0003מדבר משחיו, וידעוני\u0004 — \u0003זה ה\u0004מעלה את המת ו\u0003מדבר\u0004 המת \u0003בפיו. הרי אלו\u0004 בעל האוב והידעוני \u0003בסקילה, והנשאל בהם באזהרה\u0004 שעבר על מצות לא תעשה.","ושואלים: \u0003מאי שנא הכא דקתני\u0004 \u0005[במה שונה כאן ששנה]\u0006 \u0003בעל אוב וידעוני, ומאי שנא גבי\u0004 \u0005[ובמה שונה אצל,\u0006 בענין\u0005]\u0006 \u0003כריתות דקתני\u0004 \u0005[ששנה]\u0006 \u0003בעל אוב, ושייריה\u0004 \u0005[ושייר]\u0006 ולא מנה את ה\u0003ידעוני?\u0004","\u0003ר' יוחנן אמר:\u0004 שלא נמנה הידעוני לעצמו בתוך מנין חייבי הכריתות \u0003הואיל ושניהן בלאו אחד נאמרו,\u0004 וכיון ששניהם כלולים באיסור אחד אין מקום לחייב אדם על היותו גם בעל אוב וגם ידעוני, והרי רשימה זו בכריתות נאמרה כדי לחייב בקרבן חטאת מי ששגג בעבירה המחייבת כרת אם נעשתה במזיד.","\u0003ריש לקיש אמר: ידעוני\u0004 לא נמנה ברשימת הכריתות \u0003לפי שאין בו מעשה,\u0004 ואינו אלא מדבר בפיו, ועל לאו שאין בו מעשה אין מביאים קרבן חטאת.","ושואלים: \u0003ור' יוחנן\u0004 לפי טעמו, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003בעל אוב דנקט\u0004 \u0005[שתפס],\u0006 מה טעם בחר התנא בדוגמה זו ולא מנה ידעוני? ומשיבים: \u0003משום\u0004 ש\u0003פתח ביה קרא\u0004 \u0005[בו הכתוב],\u0006 תפס כדוגמה מה שנזכר ראשונה בכתוב ולא ידעוני הנזכר אחריו.","ושואלים: \u0003וריש לקיש, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן? אמר רב פפא:\u0004 סבור ריש לקיש שאין לומר שהעובר על שניהם כאחד נתחייב רק בחטאת אחת משום שמקורם באיסור אחד, כיון שבפסוק \u0003חלוקין הן ב\u0004ענין \u0003מיתה\u0004 ושניהם מומתים, ואילו היה ידעוני לאו שיש בו מעשה אכן היה העובר על שניהם כאחד חייב שתי חטאות.","\u0003ור' יוחנן\u0004 סבר: \u0003חלוקה דלאו\u0004 \u0005[של\u0006 איסור \u0005\"לא תעשה\"]\u0006 \u0003שמה חלוקה\u0004 ומחייבת את העבריין להביא חטאת לחוד, חלוקה של \u0003מיתה לא שמה חלוקה\u0004 לענין שגגה וקרבן חטאת.","ועוד שואלים: \u0003ור' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כריש לקיש\u0004 שידעוני לא נמנה משום שאין בו מעשה? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ר' יוחנן כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 שבמסכת \u0003כריתות\u0004 כשיטת \u0003ר' עקיבא היא\u0004 כולה, ש\u0003אמר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003מעשה\u0004 כדי להתחייב, שאדם מתחייב גם על עבירה שאין בה מעשה בפועל.","\u0003וריש לקיש\u0004 סבור: \u0003נהי\u0004 \u0005[אמנם]\u0006 ש\u0003לא בעי\u0004 \u0005[צריך,\u0006 מצריך\u0005]\u0006 \u0003ר' עקיבא\u0004 שיהיה \u0003מעשה רבה\u0004 \u0005[גדול]\u0006 שיש בו פעולה ניכרת ובולטת, ואולם \u0003מעשה זוטא\u0004 \u0005[קטן]\u0006 לפחות \u0003בעי\u0004 \u0005[\u0006הוא \u0005צריך,\u0006 מצריך\u0005],\u0006 וידעוני אין בו מעשה כלל וגם ר' עקיבא לא יחייב בו.","ושואלים: \u0003מגדף\u0004 האומר דברים בלבד \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מעשה איכא\u0004 \u0005[יש\u0006 בו\u0005]?\u0006 והלא ר' עקיבא מחייב במגדף, ומשמע שאין הוא דורש כלל שיהיה מעשה על מנת להתחייב! ומשיבים: \u0003עקימת שפתיו\u0004 שהוא עושה בשעת הדיבור \u0003הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003מעשה.\u0004","ושואלים: \u0003בעל אוב מאי\u0004 \u0005[מה]\u0006 \u0003מעשה איכא\u0004 \u0005[יש\u0006 בו\u0005]?\u0006 ומשיבים: \u0003הקשת זרועותיו\u0004 זו בזו כדי להשמיע קול \u0003הוי\u0004 \u0005[הריהו]\u0006 נחשבת \u0003מעשה.\u0004","ושואלים: \u0003ו\u0004כי דבר זה נכון \u0003אפילו ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הדורשים מעשה ממש? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אינו חייב\u0004 בעבודה זרה \u0003אלא על דבר שיש בו מעשה, כגון זיבוח קיטור וניסוך והשתחואה.\u0004","\u0003ואמר ריש לקיש\u0004 עצמו: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה \u0003השתחואה\u0004 בתוך אלה? — \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003מעשה\u0004 גמור, ודי במעשה כלשהו, \u0003ור' יוחנן אמר: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שאותה ברייתא כשיטת \u0005חכמים\u0006 היא\u0005],\u0006 אלא \u0003כפיפת קומתו ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003הוי\u0004 \u0005[הריהי]\u0006 נחשבת \u0003מעשה.\u0004","ומעתה, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ל\u0004שיטתו של \u0003ריש לקיש כפיפת קומתו ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא הוי\u0004 \u0005[אינה]\u0006 נחשבת \u0003מעשה,\u0004 ופעולה ניכרת פחות, כגון \u0003הקשת זרועותיו\u0004 של \u0003בעל אוב הוי\u0004 \u0005[הריהו]\u0006 נחשבת \u0003מעשה?!\u0004","ומשיבים: ריש לקיש מודה שלדעת חכמים אין זה נחשב מעשה, ואולם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ריש לקיש נמי\u0004 \u0005[גם כן]\u0006 הרי זה \u0003ל\u0004שיטת \u0003ר' עקיבא, אבל ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — אכן זה \u0003לא\u0004 נחשב מעשה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחכמים סבורים שבעל אוב אין בו מעשה, היו צריכים לומר במסכת כריתות (ב, א) לא רק \"יצא מגדף (מכלל חייבי חטאות, ונידון בכרת) שאינו עושה מעשה\", אלא \u0003\"יצא מגדף ובעל אוב\u0004 שאינו עושה מעשה \u0003\"\u0004\u0003מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005]!\u0006","\u0003אלא אמר עולא:\u0004 מעשה בעל אוב שחייבים עליו לדעת חכמים הוא \u0003במקטר\u0004 קטורת \u0003לשד\u0004 כדי שיוכל להעלות את המת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אם \u0003מקטר לשד\u0004 — הרי \u0003עובד עבודה זרה הוא,\u0004 ומתחייב מטעם זה שהרי אין הבדל מה הוא עובד. \u0003אלא אמר רבא: במקטר לחבר,\u0004 שאיננו מקטר לשד בדרך פולחן ועבודה אלא מקטר בדרך כשפים, להביא את השדים למקום אחד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: המקטר לחבר\u0004 הרי \u0003חובר חבר הוא,\u0004 ונאמר בתורה כלאו מיוחד (\"וחובר חבר\". דברים יח, יא), ואין בו אלא איסור \"לא תעשה\"!","אמר לו רבא: \u0003אין\u0004 \u0005[כן],\u0006 באמת אף זה חובר חבר הוא, אלא \u0003התורה אמרה: חובר זה\u0004 של שדים יהא דינו \u0003בסקילה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בביאור איסור \u0003\"\u0004ו\u0003חבר חבר\"\u0004 — \u0003אחד חבר גדול,\u0004 שמחבר על ידי כשפים חיות גדולות למקום אחד, \u0003ואחד חבר קטן,\u0004 שמחבר בכשפים חיות קטנות למקום אחד, \u0003ואפילו\u0004 המחבר למקום אחד \u0003נחשים ועקרבים.\u0004","\u0003אמר אביי: הלכך, האי מאן דצמיד זיבורא ועקרבא\u0004 \u0005[לכן, מי שמצמיד\u0006 בכשפים \u0005צרעה ועקרב]\u0006 שיזיקו זה לזה, \u0003אף על גב דקא מיכוין\u0004 \u0005[אף על פי שמתכוון]\u0006 ש\u0003לא ליזקו\u0004 \u0005[יזיקו\u0006 לו\u0005]\u0006 בכל זאת \u0003אסור. ו\u0004שואלים: לגוף אותן סברות שאמרנו","\u0003ר' יוחנן, מאי שנא\u0004 \u0005[במה שונה]\u0006 ש\u0003כפיפת קומתו\u0004 שבהשתחוואה \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003הוי\u0004 \u0005[הריהי]\u0006 נחשבת \u0003מעשה, ועקימת שפתיו\u0004 שבמגדף \u0003לא הוי\u0004 \u0005[אינה]\u0006 נחשבת \u0003מעשה?\u0004","\u0003אמר רבא: שאני\u0004 \u0005[שונה]\u0006 \u0003מגדף, הואיל וישנו\u0004 גם \u0003בלב,\u0004 כלומר, העבירה שבגידוף אינה תלויה רק בצד המעשה, במה שאדם אומר בפיו, אלא בעיקר תלוי בכוונת הלב של המגדף אם מתכוון הוא באמת לגדף, ואם אמר דברים בלא כוונה — אין זה קרוי גידוף. ומשום כך אין חייבים חטאת על מעשה זה, לפי שאין עיקרו אלא בלב."],["\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא\u0004 ממה ששנינו: \u0003יצאו עדים זוממין\u0004 מכלל מביאי קרבן חטאת לפי \u0003שאין בהן מעשה.\u0004 ויש לשאול: \u0003ואמאי\u0004 \u0005[מדוע]\u0006 נאמר כן? והרי מה שעשו בדיבור היה, ועקימת שפתיהם תהא נחשבת מעשה, \u0003הא ליתנהו\u0004 \u0005[הרי אינם]\u0006 בין אלה שעבירתם היא \u0003בלב,\u0004 שהרי הם חייבים על מה שאמרו בפיהם, ולא על מה שהיה בלבם!","\u0003אמר רבא: שאני\u0004 \u0005[שונים]\u0006 \u0003עדים זוממין הואיל וישנו בקול,\u0004 כלומר, בעדות (ובעדים זוממים) עיקר הדבר שעושים הוא השמעת קול דבריהם, ואין חילוק אם עשו או לא עשו מעשה בשפתיים, וכיון שהדבר תלוי בקול, הרי קול אין בו ממש.","ושואלים: \u0003וקול ל\u0004שיטת \u0003ר' יוחנן,\u0004 שבה אנו דנים, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מעשה הוא? והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בבעיה: אם אדם, ברצותו למנוע מבהמה שתאכל בשעת דישתה, ולכך \u0003חסמה בקול,\u0004 שלא חסמה במכשיר אלא גער בה בכל פעם שרצתה לאכול. השאלה היא האם עבר בכך על \"לא תחסום שור בדישו\u0003\"\u0004 (דברים כה, ד). \u0003ו\u0004כן אם \u0003הנהיגה בקול\u0004 בצמד בהמות שהן כלאיים, האם עובר בכך משום \"לא תחרוש בשור ובחמור יחדו\u0003\"\u0004 (דברים כב, י). \u0003ר' יוחנן אמר: חייב,\u0004 שלדעתו העושה בקולו כעושה מעשה בגופו, \u0003וריש לקיש אמר: פטור.\u0004","והסברנו כי \u0003ר' יוחנן אמר חייב,\u0004 משום ש\u0003עקימת פיו\u0004 בדיבורו \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003מעשה. ריש לקיש אמר פטור,\u0004 שלדעתו \u0003עקימת פיו לא הוי\u0004 \u0005[אינה]\u0006 \u0003מעשה.\u0004 והרי שלדעת ר' יוחנן דבר הנעשה על ידי קול נחשב כמעשה!","\u0003אלא אמר רבא:\u0004 יש לתרץ באופן אחר, \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003עדים זוממין הואיל וישנן בראיה,\u0004 כלומר, העדות תלויה לא רק בדברי העדים אלא גם בראיה שמעידים שראו, וכיון שראיה אין בה מעשה הרי שמעיקר מהותה אין העדות נחשבת מעשה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בעל אוב\u0004 — \u0003זה\u0004 הגורם שישמע קול \u0003ה\u0004מת \u0003מדבר בין הפרקים\u0004 אברי גופו, או \u0003מבין אצילי ידיו\u0004 (מבית השחי). \u0003ידעוני\u0004 — \u0003זה המניח עצם\u0004 של חיה הקרויה \u0003\"ידוע\" בפיו, והוא מדבר מאליו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה שנאמר: \u0003\"והיה כאוב מארץ קולך\"\u0004 (ישעיה כט, ד), \u0003מאי לאו דמשתעי כי אורחיה\u0004 \u0005[האם לא\u0006 הכוונה באוב \u0005ש\u0006המת \u0005מדבר כדרכו]\u0006 מן הקבר? ודוחים: \u0003לא, דסליק ויתיב\u0004 \u0005[שעולה\u0006 המת על ידי הכישוף \u0005ויושב]\u0006 \u0003בין הפרקים\u0004 של בעל האוב \u0003ומשתעי\u0004 \u0005[ומדבר].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר בדברי האשה בעלת האוב: \u0003\"ותאמר האשה אל שאול אלהים ראיתי עלים מן הארץ\"\u0004 (שמואל א' כח, יג), \u0003מאי לאו דמשתעי כי אורחיה\u0004 \u0005[האם לא\u0006 מדובר שם \u0005ש\u0006המת \u0005מדבר כדרכו]?\u0006 ודוחים: \u0003לא, דיתיב\u0004 \u0005[שיושב]\u0006 \u0003בין הפרקים\u0004 של בעל האוב \u0003ומשתעי\u0004 \u0005[ומדבר].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בעל אוב\u0004 כולל \u0003אחד המעלה\u0004 ומושיב את המת \u0003בזכורו\u0004 (על זכרותו) שהוא מין כישוף, \u0003ואחד הנשאל בגולגולת\u0004 של המת. ו\u0003מה\u0004 ההבדל \u0003בין זה לזה? מעלה בזכורו\u0004 — \u0003אינו עולה\u0004 המת \u0003כדרכו,\u0004 אלא נראה הפוך \u0003ואינו עולה ב\u0004יום ה\u0003שבת.\u0004 ואילו \u0003נשאל בגולגולת\u0004 — המת \u0003עולה כדרכו ועולה בשבת.\u0004","על לשון הדברים תוהים: כיצד אפשר לומר \u0003עולה?! להיכא סליק\u0004 \u0005[להיכן\u0006 הוא \u0005עולה]?\u0006 \u0003הא קמיה מנח\u0004 \u0005[הרי\u0006 הגולגולת \u0005לפניו\u0006 היא \u0005מונחת]!\u0006 \u0003אלא אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 \u0003עונה כדרכו ועונה בשבת.\u0004","כיון שהוזכר הדבר בענין המת שאינו עולה בשבת, מספרים: \u0003אף שאלה זו שאל טורנוסרופוס הרשע\u0004 נציב רומא \u0003את ר' עקיבא. אמר לו: ומה יום מיומים,\u0004 כלומר, במה מיוחד יום השבת משאר הימים? \u0003אמר לו\u0004 ר' עקיבא: \u0003ומה גבר מגוברין\u0004 \u0005[איש מאנשים]?\u0006 כלומר, במה מכובד אתה מאחרים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דמרי צבי\u0004 \u0005[שאדוני רצה\u0006 בכך\u0005].\u0006 אמר לו ר' עקיבא: \u0003שבת נמי דמרי צבי\u0004 \u0005[גם כן שהאדון רצה\u0006 בכך\u0005]\u0006 וקידש את היום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 טורנוסרופוס: \u0003הכי קאמינא\u0004 \u0005[כך אומר אני]\u0006 \u0003לך,\u0004 זו היא עיקר שאלתי: \u0003מי יימר דהאידנא שבתא\u0004 \u0005[מי יאמר שעכשיו שבת],\u0006 שמא יום אחר בשבוע הוא שבת? \u0003אמר לו: נהר סבטיון יוכיח\u0004 שהוא שובת ביום השבת דווקא, \u0003בעל אוב יוכיח\u0004 שאינו עולה ביום השבת, \u0003קברו של אביו\u0004 של טורנוסרופוס \u0003יוכיח, שאין מעלה עשן בשבת\u0004 אף שמעלה עשן כל השבוע שכן הוא נידון בגיהנום. \u0003אמר לו\u0004 טורנוסרופוס: על ידי כך \u0003ביזיתו\u0004 לאבי, \u0003ביישתו\u0004 ברבים, \u0003וקיללתו\u0004 שאמרת שוודאי נידון בגיהנום.","ושואלים: \u0003שואל אוב היינו\u0004 \u0005[הרי זה]\u0006 לכאורה \u0003\"ודרש אל המתים\"!\u0004","ומסבירים: \u0003דורש למתים\u0004 ענין אחר הוא, \u0003כדתניא\u0004 \u0005[\u0006ו\u0005כפי ששנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר: \u0003\"ודרש אל המתים\"\u0004 (דברים יח, יא) — \u0003זה המרעיב עצמו והולך ולן בבית הקברות כדי שתשרה עליו רוח טומאה,\u0004 ויוכל להקשיב למה שאומרים המתים.","\u0003וכשהיה ר' עקיבא מגיע למקרא זה היה בוכה\u0004 ואומר: \u0003ומה המרעיב עצמו כדי שתשרה עליו רוח טומאה\u0004 — \u0003שורה עליו רוח טומאה\u0004 והדבר מועיל, \u0003המרעיב עצמו כדי שתשרה עליו רוח טהרה\u0004 — \u0003על אחת כמה וכמה\u0004 שרוח טהרה היתה צריכה לשרות עליו. \u0003אבל מה אעשה שעונותינו גרמו לנו\u0004 שאיננו זוכים לרוח קדושה וטהורה, \u0003שנאמר: \"כי אם עונתיכם היו מבדלים בינכם לבין אלהיכם\u0004 וחטאותיכם הסתירו פנים מכם משמוע","\u0003\"\u0004(ישעיה נט, ב). \u0003אמר רבא: אי בעו צדיקי, ברו עלמא\u0004 \u0005[אם היו הצדיקים רוצים,\u0006 היו \u0005בוראים עולם],\u0006 \u0003שנאמר: \"כי\u0004 אם \u0003עונתיכם היו מבדלים ביניכם לבין אלהיכם\u0004","\u0003\"\u0004(ישעיה נט, ב). כלומר, צדיק שאין בו עוונות אין הבדל בינו ובין ה', וכשם שה' בורא עולם אף צדיק יכול לברוא עולם. ואכן מסופר: \u0003רבא ברא גברא\u0004 \u0005[אדם,\u0006 גולם\u0005]\u0006 בשימוש כוחות של קדושה. \u0003שדריה לקמיה\u0004 \u0005[שלח אותו לפני]\u0006 \u0003ר' זירא. הוה קא משתעי בהדיה\u0004 \u0005[היה מדבר איתו]\u0006 ר' זירא, \u0003ולא הוה קא מהדר ליה\u0004 \u0005[היה עונה לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מן חבריא את\u0004 \u0005[מן החבורה אתה],\u0006 כלומר, נבראת על ידי מבני החבורה, אחד החכמים, \u0003הדר לעפריך\u0004 \u0005[חזור לעפרך].\u0006","ועוד מסופר: \u0003רב חנינא ורב אושעיא הוו יתבי\u0004 \u0005[היו יושבים]\u0006 \u0003כל מעלי שבתא ועסקי\u0004 \u0005[ערב שבת ועוסקים]\u0006 \u0003בספר יצירה, ומיברו להו עיגלא תילתא, ואכלי ליה\u0004 \u0005[והיה נברא להם עגל משולש, ואוכלים אותו]\u0006 לכבוד השבת. דברים אלה מסופרים על מנת לחזק את הענין שאמרנו שהצדיקים יכלו לברוא עולם אם היו רוצים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מהו \u0003מעונן\u0004 הנזכר בתורה (\"לא ימצא בך... מעונן\". דברים יח, י)? \u0003ר' שמעון אומר: זה המעביר שבעה מיני זכור\u0004 (זרע) \u0003על העין\u0004 כדי לעשות כשפים. \u0003וחכמים אומרים:\u0004 מעונן \u0003זה האוחז את העינים\u0004 כאילו עושה כשפים. \u0003ר' עקיבא אומר: זה המחשב עתים ושעות\u0004 (\"מעונן\" מלשון עונות), \u0003ואומר: היום\u0004 מזלו \u0003יפה לצאת\u0004 לדרך, \u0003למחר יפה ליקח\u0004 (לקנות) בהצלחה. או אומר \u0003לימודי\u0004 (רגילים) \u0003ערבי שביעיות חיטין\u0004 להיות \u0003יפות,\u0004 כלומר, שבערב שנת השמיטה יבול החיטים הוא מוצלח, \u0003עיקורי קטניות מהיות רעות,\u0004 כלומר, כאשר עוקרים קטניות ממקומן ואין קוצצים אותן, אינן נעשות רעות ואינן נרקבות, וכיוצא בזה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנחש\u0004 האמור בתורה (דברים יח, י) \u0003זה\u0004 הסומך על סימנים של ניחוש, כגון \u0003האומר:\u0004 אם \u0003פתו נפלה מפיו\u0004 — סימן רע הוא, ואם \u0003מקלו נפלה מידו\u0004 — סימן רע, וכן אם \u0003בנו קורא לו מאחריו\u0004 סימן הוא שצריך לחזור מדרכו, \u0003עורב קורא לו,\u0004 או ש\u0003צבי הפסיקו בדרך, נחש מימינו ושועל משמאלו,\u0004 וסומך על אלה שהם סימנים רעים, ומפסיק לעשות את שהוא עושה."],["או האומר: \u0003אל תתחיל בי\u0004 לגבות את הצדקה שאהיה ראשון לנותנים, או אל תקח ממני כי \u0003שחרית הוא\u0004 וסימן רע להתחיל את היום בהפסד, או \u0003ראש חודש הוא,\u0004 וסימן רע להתחיל את החודש בהפסד, \u0003מוצאי שבת הוא\u0004 ואיני רוצה להתחיל את השבוע בהפסד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"לא תנחשו ולא תעוננו\"\u0004 (ויקרא יט, כו), הכוונה ל\u0003כגון אלו המנחשים\u0004 ומוצאים הוראות לעצמם לפי מה שקורה \u0003בחולדה בעופות ובדגים.\u0004","ועוד מחייבי סקילה: \u0003המחלל את השבת בדבר שחייבין על זדונו\u0004 (עשייתו בזדון) ללא עדים או ללא התראה \u0003כרת, ועל שגגתו\u0004 (עשייתו בשוגג) קרבן \u0003חטאת.\u0004","ומעירים: \u0003מכלל\u0004 הדברים במשנה לומד אתה \u0003דאיכא מידי\u0004 \u0005[שיש דבר]\u0006 האסור מן התורה ש\u0003חילול שבת הוי\u0004 \u0005[הוא],\u0006 \u0003ואין חייבין לא על שגגתו חטאת ולא על זדונו כרת.\u0004 שאם לא כן לא היה צריך לפרט במשנה שסקילה חייב דווקא העובר על דבר שזדונו כרת ושגגתו חטאת.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה מלאכה שיש בה חילול שבת ואין עונשה חמור כל כך? ומשיבים: \u0003תחומין\u0004 — יציאה מתחום שבת, שהוא אלפיים אמה מחוץ למקום שהוא מצוי בה, \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' עקיבא\u0004 הסבור שתחומין אינם תקנת חכמים אלא מן התורה הם, אבל אין נענשים עליהם בסקילה. או \u0003הבערה\u0004 של אש, \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יוסי\u0004 שלדעתו יצא איסור זה מכללו, וחייבים עליו רק ב\"לא תעשה\", ואין בו סקילה.","ועוד מן הנסקלים: \u0003המקלל אביו ואמו אינו חייב עד שיקללם בשם\u0004 ה' ממש. ואם \u0003קללם בכנוי\u0004 שאינו שם מפורש — \u0003ר' מאיר מחייב, וחכמים פוטרין.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה הנזכרים כאן? ומשיבים: \u0003ר' מנחם בר' יוסי הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' מנחם בר' יוסי אומר,\u0004 נאמר: \u0003\"\u0004ונוקב שם ה' מות יומת רגום ירגמו בו כל העדה כגר כאזרח \u0003בנקבו שם יומת\"\u0004 (ויקרא כד, טז), \u0003מה תלמוד לומר: \"שם\"\u0004 פעם שניה, הנראית כחזרה בלבד? — \u0003לימד על מקלל אביו ואמו שאינו חייב עד שיקללם בשם\u0004 דווקא, ואם קללם בכינוי — פטור.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 באותו ענין: נאמר \"כי איש איש אשר יקלל את אביו ואת אמו מות יומת אביו ואמו קלל דמיו בו\u0003\"\u0004 (ויקרא כ, ט), נאמר \u0003\"איש\", מה תלמוד לומר: \"איש איש\"\u0004 פעמיים? — \u0003לרבות בת\u0004 או \u0003טומטום ואנדרוגינוס\u0004 שאינם זכרים ממש, שאף הם בכלל האיסור.","\u0003\"אשר יקלל את אביו ואת אמו\"\u0004 — \u0003אין לי אלא\u0004 שקילל \u0003אביו ואמו\u0004 יחד, ואולם אם קלל את \u0003אביו שלא\u0004 קילל \u0003אמו, אמו שלא אביו, מניין?\u0004 — \u0003תלמוד לומר: \"אביו ואמו קלל דמיו בו\"\u0004 שמחזרה זו למדים אנו: או \u0003אביו קילל,\u0004 או \u0003אמו קילל,\u0004 אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר:\u0004 אין צורך בלימוד זה, אלא כאשר מוזכרים שני דברים יחד במקרא \u0003משמע שניהן כאחד ומשמע\u0004 גם כל \u0003אחד\u0004 מהם \u0003בפני עצמו, עד שיפרוט לך הכתוב \"יחדו\"\u0004 ורק אז הכוונה כשהם יחד.","נאמר שם \u0003\"מות יומת\"\u0004 ועונשו \u0003בסקילה. אתה אומר\u0004 שעונשו \u0003בסקילה, או אינו אלא באחת מכל מיתות\u0004 אחרות \u0003האמורות בתורה?\u0004 — \u0003נאמר כאן \"דמיו בו\" ונאמר להלן \"\u0004ואיש או אשה כי יהיה בהם אוב או ידעוני מות יומתו באבן ירגמו אותם \u0003דמיהם בם\"\u0004 (ויקרא כ, כז), \u0003מה להלן\u0004 \"דמיהם בם\" הוא עונש \u0003סקילה, אף כאן בסקילה.\u0004","ושואלים: \u0003עונש\u0004 למקלל \u0003שמענו, אזהרה\u0004 שאסור לקלל \u0003מניין?\u0004 — \u0003תלמוד לומר: \"אלהים לא תקלל\u0004 ונשיא בעמך לא תאור\u0003\"\u0004 (שמות כב, כז). \u0003אם היה אביו דיין\u0004 — \u0003הרי הוא בכלל\u0004 \u0003\"אלהים לא תקלל\",\u0004 שהרי נאסר לכל אדם לקלל את הדיין. \u0003ואם היה אביו נשיא\u0004 (מלך, או ראש העם) — \u0003הרי הוא בכלל \"ונשיא בעמך לא תאר\".\u0004","אם \u0003אינו לא דיין ולא נשיא, מניין\u0004 שמוזהר על קללתו? — \u0003אמרת: הרי אתה דן בנין אב משניהן\u0004 בדרך זו: \u0003לא ראי\u0004 (אינו דומה, אינו נראה) \u0003נשיא כראי דיין,\u0004 שאינם שווים זה לזה בדברים רבים. \u0003ולא ראי דיין כראי נשיא.\u0004 כיצד?","— \u0003לא ראי דיין כראי נשיא, שהרי דיין אתה מצווה על הוראתו,\u0004 שאתה חייב לציית לדברי תורה שהוא מורה לך, \u0003כראי נשיא שאי\u0004 (אין) \u0003אתה מצווה על הוראתו. ו\u0004כן, \u0003לא ראי נשיא כראי דיין, שהנשיא אתה מצווה על המראתו,\u0004 שאסור לך להמרות את פיו של המלך כשפוקד לעשות דבר מה, \u0003כראי דיין שאי אתה מצווה על המראתו.\u0004","\u0003הצד השוה שבהם שהן בעמ\u0004 \u0003ך,\u0004 שהם בני עם ישראל \u0003ואתה מוזהר על קללתן, אף אני אביא\u0004 את הדין של \u0003אביך ש\u0004הוא \u0003בעמך, ו\u0004לפיכך \u0003אתה מוזהר על קללתו.\u0004","ודוחים: \u0003מה להצד השוה שבהן\u0004 שאינו רק בזה שהם בעמך, אלא צד אחר של יחוד בשניהם: \u0003שכן גדולתן גרמה להן\u0004 להתייחד משאר העם, ושמא האיסור רק בגדולים שבישראל!","\u0003תלמוד לומר: \"לא תקלל חרש\u0004 ולפני עור לא תתן מכשול\u0003\"\u0004 (ויקרא יט, יד), הרי אף \u0003באומללים שבעמך הכתוב מדבר.\u0004 נמצא שיש איסור מיוחד לקלל אף אנשים מסכנים, ומכאן נלמד לכל אדם.","ולכאורה אפשר לטעון: \u0003מה לחרש, שכן חרישתו גרמה לו\u0004 לאסור על קללתו כשם שאסור להטעות עוור, ושמא דווקא מטעם זה אסור!","על כן אומרים: \u0003נשיא ודיין יוכיחו,\u0004 שאסור לקללם אף שאינם אומללים שבעם. ואם תאמר \u0003מה לנשיא ודיין שכן גדולתן גרמה להן,\u0004 אם כן \u0003חרש יוכיח\u0004 שאינו משום גדולה, ולמרות זאת אסור לקללו!","\u0003וחזר הדין,\u0004 כלומר, השיקול פונה ומשתנה מצד לצד, שאם מצד אחד יש סתירה, הרי סתירה זו נפרכת מצד אחר, ולהיפך. ואפשר איפוא לסכם: \u0003לא ראי זה כראי זה, ולא ראי זה כראי זה, הצד השוה שבהן: שהן בעמך ואתה מוזהר על קללתן, אף אני אביא אביך ש\u0004הוא \u0003בעמך, ואתה מוזהר על קללתו.\u0004","ודוחים: \u0003מה לצד השוה שבהן שכן משונין,\u0004 כלומר, יש בהם צד משותף אחר: שאינם מן האנשים הרגילים, והם מיוחדים בדבר מה (\"משונים\") משאר העם, אבל סתם אדם מישראל שמא אין איסור לקללו!","\u0003אלא\u0004 עלינו לחזור בנו מן ההוכחה הקודמת ולומר \u0003אם כן נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003או אלהים וחרש או נשיא וחרש,\u0004 והיינו למדים משני אלה לכל המיוחדים שבעם, אם כן \u0003\"אלהים\"\u0004 (איסור מיוחד על דיינים) \u0003למה לי\u0004 שהוא בוודאי מיותר! אלא \u0003אם אינו ענין לגופו\u0004 לאסור קללת הדיין, הנלמדת בבנין אב — \u0003תנהו ענין לאביו.\u0004","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003\"אלהים\"\u0004 הכתוב במקרא זה \u0003חול\u0004 הוא, ומשמעו דיין. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003קודש\u0004 הוא וכוונתו לקדוש ברוך הוא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 כיצד ניתן ללמוד?","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"אלהים\"\u0004 הכתוב כאן \u0003חול\u0004 הוא, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: \"אלהים\"\u0004 — \u0003קודש. ותניא\u0004 \u0005[ושנוייה\u0006 ברייתא אחרת\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר: אזהרה למברך\u0004 (כלומר, בלשון נקיה, למקלל) \u0003את השם מניין?\u0004 — \u0003תלמוד לומר: \"אלהים לא תקלל\".\u0004 ואם כן יש משמעות אחרת לאותם כתובים!","ומשיבים: \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003\"אלהים\" חול\u0004 הוא — \u0003גמר\u0004 \u0005[לומד]\u0006 \u0003קודש מחול, למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003\"אלהים\" קודש\u0004 — \u0003גמרינן\u0004 \u0005[לומדים אנו]\u0006 \u0003חול מקודש.\u0004","ותוהים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003\"אלהים\" חול\u0004 הוא — כאן \u0003גמר\u0004 \u0005[למד]\u0006 \u0003קודש מחול\u0004 בקל וחומר פשוט. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003\"אלהים\" קודש\u0004 הוא, כיצד \u0003גמר\u0004 \u0005[למד]\u0006 \u0003חול מקודש?! דילמא\u0004 \u0005[שמא]\u0006 על קללת אלהים במשמעות \u0003קודש אזהר\u0004 \u0005[הזהיר]\u0006 ואולם במשמעות \u0003חול לא אזהר\u0004 \u0005[הזהיר]!\u0006","ומשיבים: \u0003אם כן\u0004 הוא שעל אלהים בלשון חול לא הזהיר, \u0003לכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 באותו מקום \u0003\"לא תקל\",\u0004 ונלמד שאסור לבזות ולקלל את הקודש."],["\u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"לא תקלל\"\u0004 שהוא לשון כפולה? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003תרתי\u0004 \u0005[שני\u0006 דברים\u0005],\u0006 שיש איסור קללת גבוה ויש איסור קללת דיין.","ובפרטי דין חייבי סקילה: \u0003הבא על נערה המאורסה\u0004 — \u0003אינו חייב\u0004 סקילה \u0003עד שתהא נערה\u0004 בגיל הנערות דווקא ולא קטנה ולא בוגרת, ושתהא \u0003בתולה, מאורסה\u0004 בלבד ולא נשואה עדיין, \u0003והיא בבית אביה\u0004 שעדיין לא הגיעה לבית הבעל. אם \u0003באו עליה שנים\u0004 (שני אנשים), \u0003הראשון\u0004 נידון \u0003בסקילה\u0004 כדין הבא על נערה בתולה המאורסה, \u0003והשני בחנק\u0004 כדין הבא על שאר אשת איש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"נערה\"\u0004 שאמרו \u0003ולא בוגרת,\u0004 שכל שהיא למעלה מגיל שתים עשרה וחצי בערך אינה קרויה עוד \"נערה\". \u0003\"בתולה\"\u0004 משמע \u0003ולא בעולה, \"מאורסה\"\u0004 — \u0003ולא נשואה, \"בבית אביה\"\u0004 — \u0003פרט ל\u0004זו \u0003שמסר האב לשלוחי הבעל\u0004 והם מביאים אותה כבר לבית בעלה, שאף שלא הגיעה עדיין לשם נחשבת היא מבחינת ההלכה אשת איש.","\u0003אמר רב יהודה אמר רב:\u0004 משנתנו \u0003זו דברי ר' מאיר,\u0004 האומר שדין נערה המאורסה חל על נערה בגיל המוגדר בין קטנות ובגרות, \u0003אבל חכמים אומרים: נערה המאורסה\u0004 הוא גבול גיל עליון ו\u0003אפילו קטנה במשמע.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ממאי דמתניתין\u0004 \u0005[מנין\u0006 ידוע \u0005שמשנתנו]\u0006 כשיטת \u0003ר' מאיר היא, ו\u0004מה שנאמר \"נערה\" בא \u0003למעוטי\u0004 \u0005[למעט,\u0006 להוציא\u0005]\u0006 \u0003קטנה נמי\u0004 \u0005[גם כן]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 משנתנו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, ו\u0004נערה שאמרו הוא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בוגרת ותו לא\u0004 \u0005[ולא עוד],\u0006 והבא על קטנה יהיה חייב סקילה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003האי\u0004 \u0005[זה\u0006 הביטוי\u0005]\u0006 שבמשנה: \u0003\"אינו חייב עד שתהא נערה בתולה מאורסה\"\u0004 אינו נוח לפירוש זה, כי אילו היתה הכוונה דווקא נערה ולא בוגרת, \u0003\"אינו חייב אלא על נערה בתולה מאורסה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 כי לשון \"שתהא\" פירושו: שתגדל ותגיע לגיל זה, ומאחר ולא אמר כן אלא כפי ששנינו \u0003ותו לא מידי\u0004 \u0005[ועוד אין\u0006 לומר \u0005דבר],\u0006 וברור שכך יש לפרש.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' יעקב בר אדא מרב: בא על הקטנה מאורסה, ל\u0004שיטת \u0003ר' מאיר מהו?\u0004 האם \u0003לגמרי ממעיט ליה\u0004 \u0005[ממעט אותו]\u0006 מעונש ואינו נענש כלל, \u0003או מסקילה\u0004 בלבד \u0003ממעיט ליה\u0004 \u0005[ממעט אותו],\u0006 אבל נענש כבא על שאר אשת איש בחנק? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005]\u0006 כי \u0003מסקילה\u0004 בלבד \u0003ממעט ליה\u0004 \u0005[אותו],\u0006 אבל מכל מקום הוא נענש בחנק.","הקשה לו ר' יעקב בר אדא: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \"כי ימצא איש שוכב עם אשה בעולת בעל \u0003ומתו גם שניהם\u0004 האיש השוכב עם האשה והאשה\" (דברים כב, כב), ומשמעו — \u0003עד שיהו שניהן שוין.\u0004 ואם כן, הבא על הקטנה, כיון שהיא אינה נענשת (שהרי אינה בת דעת ובת עונשין) כיצד נעניש אותו? \u0003שתיק\u0004 \u0005[שתק]\u0006 \u0003רב\u0004 ולא ענה לו.","\u0003אמר שמואל: מאי טעמא שתיק\u0004 \u0005[מה טעם שתק]\u0006 \u0003רב?\u0004 והלא היה בידו להשיב לו תשובה מספקת! \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]:\u0006 הרי כבר נאמר שם \u0003\"\u0004ואם בשדה ימצא האיש את הנערה המאורשה והחזיק בה האיש ושכב עמה \u0003ומת האיש אשר שכב עמה לבדו\"\u0004 (דברים כב, כה), הרי שיש מקרה שרק צד אחד בעריות נהרג, ולא שניהם. ויהיה כן גם דין הבועל את הקטנה.","ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בענין זה, נאמר: \u0003\"ומתו גם שניהם\"\u0004 — \u0003עד שיהו שניהן שוין\u0004 באותו עונש, אלו \u0003דברי ר' יאשיה. ר' יונתן אומר:\u0004 כבר נאמר \u0003\"ומת האיש אשר שכב עמה לבדו\",\u0004 משמע שיכול להיות שרק הוא יומת ולא היא.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יונתן\u0005],\u0006 הסבור שיתכן שיומת צד אחד בלבד, \u0003ההיא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 \u0003\"ומתו גם שניהם\" מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו]?\u0006 \u0003אמר רבא: למעוטי\u0004 \u0005[למעט]\u0006 \u0003מעשה חידודים,\u0004 כאשר בא עליה בכל מקום שאינו מקום ערוה, שכיון שאין שניהם שווים בהנאה אין זו קרויה ביאה, ופטור עליה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יאשיה\u0005],\u0006 כיצד לומד הוא הלכה זו? שהרי מקור הדין נדרש על ידו לענין אחר. ומשיבים: לדעתו \u0003מעשה חידודים לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא\u0004 ואין זו קרויה כלל ביאה אלא פריצות בלבד, ואין כלל צורך במקור מפורש כדי למעט מעשה זה ממיתה.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יאשיה\u0005],\u0006 \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 שנאמר בו \u0003\"\u0004ומת האיש אשר שכב עמה \u0003לבדו\" מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו]?\u0006 שהרי לדעתו נידונים למוות רק כששניהם שווים לכך!","ומסבירים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003באו עליה,\u0004 על נערה המאורסה, \u0003עשרה בני אדם ועדיין היא בתולה,\u0004 שבאו עליה כולם שלא כדרכה ונשארה בתולה — חייבים \u0003כולם בסקילה,\u0004 שהרי כולם באו על נערה בתולה. \u0003רבי אומר: הראשון\u0004 מהם נידון \u0003בסקילה, וכולן,\u0004 כל השאר, נידונים \u0003בחנק.\u0004 והוא מדייק מן הכתוב \"ומת האיש אשר שכב עמה לבדו\" — איש אחד בלבד נידון על עבירה זו בסקילה ולא עשרה אנשים, וכל השאר נידונים רק בחנק כדין הבא על אשת איש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 על הנאמר \u0003\"ובת איש כהן כי תחל לזנות\u0004 את אביה היא מחללת באש תשרף\u0003\"\u0004 (ויקרא כא, ט), \u0003רבי אומר: תחילה, וכן הוא אומר: \"ומת האיש אשר שכב עמה לבדו\"\u0004 (דברים כב, כה).","ותוהים על משפטו הסתום של רבי: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה הקשר בין הדברים? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע: רבי כ\u0004שיטת \u0003ר' ישמעאל סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 שרק בת כהן \u0003ארוסה\u0004 שזנתה \u0003יצאה לשריפה, ולא נשואה,\u0004 שנשואה נידונה כשאר נשים. \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין: \u0003אם תחילת ביאה בזנות\u0004 שזוהי ביאה ראשונה לה, שלא נבעלה לאיש — הרי היא נידונה \u0003בשריפה, אידך\u0004 \u0005[\u0006בכל מקרה \u0005אחר]\u0006 כשכבר היתה נשואה, ואין זו ביאה ראשונה לה — נידונה \u0003בחנק.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"וכן\",\u0004 מה שייך לכאן דין \"ומת האיש לבדו\"? ומשיבים: הכוונה היא לומר דשהדין כאן הוא \u0003כי התם\u0004 \u0005[כמו שם],\u0006 \u0003מה התם\u0004 \u0005[שם]\u0006 בנערה המאורסה \u0003בתחילת ביאה\u0004 (בביאה ראשונה) \u0003קמשתעי קרא\u0004 \u0005[מדבר הכתוב],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בתחילת ביאה קמשתעי קרא\u0004 \u0005[מדבר הכתוב].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ביבי בר אביי: מר\u0004 \u0005[מורנו]\u0006 \u0003לא הכי\u0004 \u0005[כך]\u0006 \u0003אמר.\u0004 ומעירים: \u0003ומנו\u0004 \u0005[ומיהו]\u0006 מורה זה? — \u0003רב יוסף.\u0004","והוא פירש: \u0003רבי כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר:\u0004 בת כהן ש\u0003נשאת לאחד מן הפסולין\u0004 כגון לממזר ונאפה תחתיו — \u0003מיתתה בחנק\u0004 ולא בשריפה.","\u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את דברי רבי: \u0003אם תחילת אחלתה\u0004 \u0005[חילולה]\u0006 \u0003בזנות\u0004 — היא נידונה \u0003בשריפה, ואידך\u0004 \u0005[ו\u0006במקרה \u0005אחר]\u0006 שכבר נתחללה על ידי עצם נישואיה לפסול לה — נידונה \u0003בחנק.\u0004 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 של החלק הנוסף בדברי רבי \u0003\"וכן\"?\u0004"],["\u0003סימנא בעלמא\u0004 \u0005[סימן בלבד],\u0006 ואין פסוק זה שייך להלכה זו, ולא הובא אלא לסימן שמדובר בתחילת חילול.","\u0003המסית\u0004 לעבוד עבודה זרה שמנינו בין הנסקלים \u0003זה הדיוט\u0004 (סתם אדם) ולא נביא שהסית, \u0003והמסית את ההדיוט\u0004 ולא את הרבים. ומה עניינו של מסית? — \u0003אמר: \"יש יראה\u0004 (עבודה זרה) \u0003במקום פלוני, כך אוכלת, כך שותה, כך מטיבה\u0004 לעובדיה, \u0003כך מריעה\u0004 לאלה שאינם עובדיה","\u0003\".\u0004 ועקרון בדין המסית: \u0003כל חייבי מיתות שבתורה אין מכמינין\u0004 (מחביאים) \u0003עליהם\u0004 מתחילה עדים לתופשם ולהענישם \u0003חוץ מ\u0004עבירה \u0003זו,\u0004 שאם אין עדים המעידים עליו דואגים להמציא עדים לדבר.","\u0003אמר לשנים\u0004 דברי הסתה הרי \u0003הן עדיו,\u0004 ואינו צריך התראה קודם לעבירה, \u0003ומביאין אותו לבית דין וסוקלין אותו. אמר\u0004 דברי הסתה \u0003לאחד\u0004 בלבד והרי אחד אינו יכול להעיד, ה\u0003הוא\u0004 ששמע את ההסתה \u0003אומר\u0004 למסית: \u0003\"יש לי חבירים רוצים בכך,\u0004 אמור את הדבר בפניהם\u0003\",\u0004 וזאת כדי שימצאו עוד עדים.","\u0003אם היה\u0004 המסית \u0003ערום ואינו יכול לדבר בפניהם\u0004 — \u0003מכמינין\u0004 (מחביאים) \u0003לו עדים אחורי הגדר\u0004 בפעם אחרת כדי שלא יראה אותם המסית, \u0003והוא,\u0004 האיש שהוסת קודם, \u0003אומר לו\u0004 למסית: \u0003\"אמור מה שאמרת\u0004 כשהיינו לבדנו \u0003ביחוד\"! והלה אומר לו\u0004 מה שאמר בהצעה לעבוד עבודה זרה זו. \u0003והוא\u0004 הניסת \u0003אומר לו: \"היאך נניח את אלהינו שבשמים ונלך ונעבוד עצים ואבנים\"? אם חוזר בו\u0004 המסית ומתחרט — \u0003הרי זה מוטב, ואם אמר \"כך היא חובתנו\u0004 לעבוד עבודה זרה, \u0003כך יפה לנו\", העומדין מאחורי הגדר מביאין אותו לבית דין וסוקלין אותו.\u0004","ובכלל המסיתים \u0003האומר \"אעבוד\u0004 עבודה זרה \u0003\",\u0004 או שאמר \u0003\"אלך ואעבוד\",\u0004 או \u0003\"נלך ונעבוד\",\u0004 או \u0003\"אזבח\u0004 לעבודה זרה\", או \u0003\"אלך ואזבח\",\u0004 או \u0003\"נלך ונזבח\",\u0004 או \u0003\"אקטיר\",\u0004 או \u0003\"אלך ואקטיר\",\u0004 או \u0003\"נלך ונקטיר\",\u0004 או \u0003\"אנסך\",\u0004 או \u0003\"אלך ואנסך\",\u0004 או \u0003\"נלך וננסך\",\u0004 או \u0003\"אשתחוה\",\u0004 או \u0003\"אלך ואשתחוה\",\u0004 או \u0003\"נלך ונשתחוה\".\u0004","שנינו: \u0003המסית זה הדיוט,\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שהוא \u0003הדיוט, הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003נביא\u0004 אינו נידון בסקילה, אלא דינו \u0003בחנק.\u0004 ושנינו עוד: \u0003והמסית את ההדיוט.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שמסית את ה\u0003יחיד, הא\u0004 \u0005[הרי]\u0006 אם היה מסית את ה\u0003רבים\u0004 — דינו \u0003בחנק,\u0004 לפיכך","\u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נביא שהדיח\u0004 לעבודה זרה דינו \u0003בסקילה, ר' שמעון אומר: בחנק.\u0004 אף \u0003מדיחי עיר הנדחת\u0004 דינם \u0003בסקילה, ר' שמעון אומר: בחנק.\u0004 ונראה לכאורה כי משנתנו כשיטת ר' שמעון.","אולם אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]\u0006 שהיא המשנה הבאה, כי הסדר בגמרא כאן: \u0003המדיח זה האומר \"נלך ונעבוד עבודה זרה\". ואמר רב יהודה אמר רב\u0004 בגמרא לקמן: \u0003מדיחי עיר הנדחת שנו\u0004 כאן. \u0003אתאן לרבנן\u0004 \u0005[הגענו\u0006 איפוא \u0005ל\u0006שיטת \u0005חכמים]\u0006 הסבורים שאף המדיחים את הרבים דינם בסקילה! והגענו למסקנה התמוהה כי משנה זו, \u0003רישא\u0004 \u0005[תחילתה]\u0006 כשיטת \u0003ר' שמעון, וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","\u0003רבינא אמר: כולה\u0004 כל המשנה כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 \u0003ו\u0004בסגנון \u0003\"לא זו אף זו\" קתני\u0004 \u0005[שנה]\u0006 במשנה, שקודם שנה את הדבר הפשוט, ואחר כך הוסיף דבר חמור מזה. וכך יש לפרש: לא זו בלבד שהמסית את ההדיוט נידון בסקילה, אלא אף זו — שהמדיח עיר הנידחת נידון בסקילה.","\u0003רב פפא אמר: כי קתני\u0004 \u0005[כאשר שנה]\u0006 ש\u0003מסית זה הדיוט,\u0004 לא להבדילו מנביא, אלא \u0003ל\u0004ענין \u0003הכמנה.\u0004 כלומר, כל מסית הוא כהדיוט שהוא קל ומזולזל ומשום כך מכמינים לו עדים, אך לא נלמד מכאן שדווקא המסית אדם בודד דינו בסקילה, והנביא או זה המסית רבים בחנק.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ושאר כל חייבי מיתות שבתורה אין מכמינין עליהן\u0004 עדים \u0003חוץ מזו\u0004 של מסית.","\u0003כיצד עושין לו? מדליקין לו את הנר בבית\u0004 (בחדר) \u0003הפנימי, ומושיבין לו עדים בבית החיצון\u0004 באפילה, \u0003כדי שיהו הן רואין אותו ושומעין את קולו, והוא\u0004 המסית \u0003אינו רואה אותן\u0004 שכן הוא באור והם באפילה. \u0003והלה\u0004 הניסת \u0003אומר לו: \"אמור מה שאמרת לי ביחוד\"! והוא אומר לו. והלה\u0004 (הניסת) \u0003אומר לו: \"היאך נניח את אלהינו שבשמים ונעבוד עבודה זרה\"? אם חוזר בו\u0004 המסית — \u0003מוטב, ואם אמר: \"כך היא חובתנו וכך יפה לנו\"\u0004 — \u0003העדים ששומעין מבחוץ מביאין אותו לבית דין, וסוקלין אותו.\u0004","\u0003וכן עשו ל\u0004מסית אחד ושמו \u0003בן סטדא\u0004 מן העיר \u0003לוד, ותלאוהו בערב הפסח.\u0004","ושואלים: וכי אותו אדם היה \u0003בן סטדא?\u0004 והלא ידוע כי \u0003בן פנדירא הוא,\u0004 שאביו היה קרוי פנדירא. \u0003אמר רב חסדא:\u0004 אפשר לומר כי שם \u0003בעל\u0004 אמו היה \u0003סטדא\u0004 ונקרא על שמו כפי שחשבו הכל שזהו אביו, ואילו \u0003בועל\u0004 שבעל את אמו והוליד ממזר זה היה שמו \u0003פנדירא,\u0004 ואם כן הוא גם בן סטדא וגם בן פנדירא. את הסבר זה דוחים: איך יתכן הדבר? כי ידוע ש\u0003בעל\u0004 אמו של אותו אדם \u0003פפוס בן יהודה הוא!\u0004 ומסכמים: \u0003אלא אמו\u0004 היא שהיתה קרויה \u0003סטדא.\u0004 ומקשים: והלא ידוע כי \u0003אמו מרים מגדלא נשיא הואי\u0004 \u0005[הקולעת שיער נשים היתה]!\u0006 ומשיבים: \"סטדא\" אינו שם פרטי אלא כינוי, \u0003כדאמרי\u0004 \u0005[כמו שאומרים\u0006 הבריות\u0005]\u0006 \u0003ב\u0004עיר \u0003פומבדיתא\u0004 על אשה זונה: \u0003\"סטת דא\"\u0004 \u0005[\"סטתה זו\"]\u0006 \u0003מבעלה\u0004 ונתקצר ל\"סטדא\".","\u0003המדיח זה האומר\u0004 לרבים \u0003\"נלך ונעבוד עבודה זרה\".\u0004","\u0003המכשף\u0004 חייב אף הוא סקילה, והגדרתו: \u0003העושה מעשה\u0004 ממש של כשפים — \u0003חייב, ולא האוחז את העינים,\u0004 שמראה כאילו עשה, שאין זה בגדר כשפים. \u0003ר' עקיבא אומר משום\u0004 (בשם) \u0003ר' יהושע:\u0004 כגון \u0003שנים לוקטין קשואין\u0004 בכשפים, \u0003אחד לוקט\u0004 והוא \u0003פטור, ואחד לוקט\u0004 והוא \u0003חייב.\u0004 כיצד? — \u0003העושה מעשה,\u0004 שלקט באמת את הקישואים בכישוף — \u0003חייב, האוחז את העינים\u0004 — \u0003פטור.\u0004","על מה ששנינו במשנה כאן \"המדיח\", \u0003אמר רב יהודה אמר רב: מדיחי עיר הנדחת שנו כאן,\u0004 ולא חילק בדין בינם ובין מסית, אלא שהמסית הוא המסית יחידים, ומדיח הוא המדיח לרבים דווקא.","שנינו במשנה ש\u0003המכשף זה העושה מעשה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"מכשפה\u0004 לא תחיה\u0003\"\u0004 (שמות כב, יז), אין הכוונה למכשפה דווקא אלא \u0003אחד האיש ואחד האשה\u0004 בכלל האסורים בכישוף. \u0003אם כן מה תלמוד לומר: \"מכשפה\"\u0004 בלשון נקבה? \u0003מפני שרוב נשים מצויות בכשפים.\u0004","\u0003מיתתן במה,\u0004 באיזו מיתה? \u0003ר' יוסי הגלילי אומר, נאמר כאן: \"מכשפה לא תחיה\", ונאמר להלן\u0004 בכיבוש שבע אומות: \u0003\"לא תחיה כל נשמה\"\u0004 (דברים כ, טז), \u0003מה להלן\u0004 במלחמה מיתתם \u0003בסייף\u0004 (ראה במדבר כא, כד), \u0003אף כאן בסייף.\u0004","\u0003ר' עקיבא אומר: נאמר כאן \"מכשפה לא תחיה\", ונאמר להלן\u0004 בדין המתפרצים לעלות על הר סיני \u0003\"\u0004לא תגע בו יד כי סקול יסקל או ירה יירה \u0003אם בהמה אם איש לא יחיה\"\u0004 (שמות יט, יג), \u0003מה להלן\u0004 \"לא יחיה\" הוא \u0003בסקילה, אף כאן\u0004 \"לא תחיה\" הוא \u0003בסקילה.\u0004","\u0003אמר לו ר' יוסי\u0004 הגלילי: \u0003אני דנתי\u0004 ולמדתי גזירה שווה \u0003\"לא תחיה\" מ\"לא תחיה\"\u0004 שהמילים שוות לגמרי, \u0003ואתה דנת \"לא תחיה\" מ\"לא יחיה\"!\u0004","\u0003אמר לו ר' עקיבא: אני דנתי\u0004 דין האמור ב\u0003ישראל מ\u0004דין \u0003ישראל, שריבה בהן הכתוב מיתות הרבה,\u0004 ואם מצאנו שפירוש \"לא תחיה\" לגבי ישראל הוא בסקילה, יש לכך משמעות מיוחדת, \u0003ואתה דנת ישראל מגוים, שלא ריבה בהן הכתוב, אלא\u0004"],["\u0003מיתה אחת\u0004 בלבד, ואין ללמוד מכאן, שהרי כל מיתה של בני נח היא בסייף.","\u0003בן עזאי אומר: נאמר \"מכשפה לא תחיה\"\u0004 (שמות כב, יז), \u0003ונאמר\u0004 בסמוך \u0003\"כל שכב עם בהמה מות יומת\"\u0004 (שמות כב, יח), \u0003סמכו ענין לו,\u0004 אף שאין קשר ביניהם, ללמד: \u0003מה שוכב עם בהמה בסקילה\u0004 כאמור במקום אחר, \u0003אף מכשף בסקילה.\u0004","\u0003אמר לו ר' יהודה: וכי מפני שסמכו ענין לו\u0004 ואין שום ראיה אחרת \u0003נוציא לזה בסקילה? אלא\u0004 ראיה אחרת יש: \u0003אוב וידעוני בכלל מכשפים היו,\u0004 שהרי אף הם עושים בכשפים, \u0003ולמה יצאו\u0004 מן הכלל להיכתב לחוד? — \u0003להקיש עליהן\u0004 (להשוות להם) \u0003ולומר לך: מה אוב וידעוני בסקילה אף\u0004 כל \u0003מכשף בסקילה.\u0004","ושואלים: \u0003ל\u0004שיטת \u0003ר' יהודה נמי\u0004 \u0005[גם כן],\u0006 \u0003ליהוו\u0004 \u0005[שיהיו]\u0006 \u0003אוב וידעוני\u0004 כ\u0003שני כתובים הבאים כאחד\u0004 שבאו שניהם ללמד הלכה דומה, \u0003ו\u0004לפי הכלל: \u0003כל שני כתובין הבאין כאחד אין מלמדין!\u0004 שאם יש כתוב אחד שנאמרה בו הלכה מסויימת אפשר לעשותו דוגמה לכל הדינים הדומים לו. ואולם אם באים שני כתובים לומר אותה הלכה עצמה כאחד, משמע ששניהם מקרים מיוחדים ואין ללמוד מהם הלכה כללית.","\u0003אמר ר' זכריה: עדא אמרה\u0004 \u0005[זאת אומרת],\u0006 \u0003קסבר\u0004 \u0005[סבר]\u0006 \u0003ר' יהודה: שני כתובין הבאין כאחד מלמדין,\u0004 ולמדים מהם לכל ענין.","\u0003אמר ר' יוחנן: למה נקרא שמן \"כשפים\"?\u0004 הרי זה כעין נוטריקון: \u0003שמכחישין פמליא של מעלה,\u0004 שנראים כסותרים את חוקיו של הקדוש ברוך הוא.","נאמר \u0003\"\u0004אתה הראת לדעת כי ה' הוא האלהים \u0003אין עוד מלבדו\"\u0004 (דברים ד, לה). \u0003אמר ר' חנינא: אפילו לדבר כשפים,\u0004 שאינו מועיל כנגד מי שדבוק בה'.","מסופר: \u0003ההיא איתתא דהות קא מהדרא למשקל עפרא מתותי כרעיה\u0004 \u0005[אשה אחת שהיתה מחזרת לקחת עפר מתחת רגליו]\u0006 של \u0003ר' חנינא\u0004 כדי לעשות לו כשפים ולהזיקו. \u0003אמר לה: אי מסתייעת זילי עבידי\u0004 \u0005[אם תצליחי לכי\u0006 ו\u0005עשי]\u0006 ואיני חושש לכך, שכן \u0003\"אין עוד מלבדו\" כתיב\u0004 \u0005[נאמר].\u0006","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: למה נקרא שמן \"כשפים\"? שמכחישין פמליא של מעלה,\u0004 הרי שראוי להיזהר מהם! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ר' חנינא דנפיש זכותיה\u0004 \u0005[שמרובה זכותו],\u0006 וצדיק שכמותו ודאי אין הכשפים שולטים בו.","\u0003אמר ר' אייבו בר נגרי אמר ר' חייא בר אבא: \"בלטיהם\"\u0004 האמור בחרטומי מצרים (שמות ז, כב) — \u0003אלו מעשה שדים\u0004 שאינם נראים, ונעשים בסתר (\"בלט\"). \u0003\"בלהטיהם\"\u0004 (שמות ז, יא) — \u0003אלו מעשה כשפים, וכן הוא אומר: \"ואת להט החרב המתהפכת\"\u0004 (בראשית ג, כד), שמשמעו שמתהפכת מעצמה ולא על ידי אחרים, והוא כענין הכשפים שאינם על ידי מסייעים, אלא המכשפים בעצמם עושים.","\u0003אמר אביי: דקפיד אמנא\u0004 \u0005[\u0006זה \u0005שמקפיד על כלי\u0006 מסויים\u0005]\u0006 שאינו יכול לעשות כשפיו אלא בכלי מסויים — זה עושה מעשה \u0003שד, דלא קפיד אמנא\u0004 \u0005[שאינו מקפיד על כלי]\u0006 אלא יכול לעשות דברי פלא ללא כלי מסויים — זה מעשה \u0003כשפים.\u0004","\u0003אמר אביי: הלכות כשפים כהלכות שבת,\u0004 שאף בהם יש שלוש דרגות: \u0003יש מהן בסקילה\u0004 שחייב סקילה עליהן, \u0003ויש מהן\u0004 שהוא \u0003פטור\u0004 מעונש בידי אדם \u0003אבל אסור\u0004 מדברי חכמים, \u0003ויש מהן\u0004 ש\u0003מותר\u0004 לעשות \u0003לכתחלה.\u0004","כיצד? \u0003העושה מעשה\u0004 של כשפים ממש — חייב מיתה \u0003בסקילה, האוחז את העינים\u0004 — \u0003פטור\u0004 מעונש, \u0003אבל אסור\u0004 לו לעשות כן. מהו ה\u0003מותר לכתחלה?\u0004 — \u0003כ\u0004מו שהיה ב\u0003רב חנינא ורב אושעיא: כל מעלי שבתא הוו עסקי\u0004 \u0005[כל ערב שבת היו עוסקים]\u0006 \u0003בהלכות יצירה, ומיברי להו עיגלא תילתא ואכלי ליה\u0004 \u0005[והיה נברא להם עגל משולש, והיו אוכלים אותו].\u0006","\u0003אמר רב אשי: חזינא ליה לאבוה\u0004 \u0005[ראיתי אותו את אביו]\u0006 של \u0003קרנא דנפיץ ושדי כריכי דשיראי מנחיריה\u0004 \u0005[ש\u0006היה \u0005מוחט\u0006 את חוטמו \u0005והיה משליך גלילים של משי מנחיריו]\u0006 על ידי אחיזת עינים.","כיון שדנו במעשי כשפים ובחרטומי מצרים, מבארים עוד: על הנאמר \u0003\"ויאמרו החרטמם אל פרעה אצבע אלהים הוא\"\u0004 (שמות ח, טו), \u0003אמר ר' אליעזר: מיכן\u0004 ראיה \u0003שאין השד יכול לבראות בריה פחות מכשעורה,\u0004 ולכן לא יכלו לעשות דבר הדומה למכת כינים, ואף הבינו שאין זה מעשה כשפים אלא מידי שמים.","\u0003רב פפא אמר\u0004 בלשון שבועה: \u0003האלהים! אפילו כגמלא נמי לא מצי ברי\u0004 \u0005[כ\u0006גודל של \u0005גמל גם כן אינם יכולים לברוא]\u0006 ואין הם בוראים מאומה, אלא \u0003האי\u0004 \u0005[\u0006את \u0005אלה]\u0006 בעלי חיים גדולים — \u0003מיכניף ליה\u0004 \u0005[\u0006יכולים הם \u0005לאסוף אותם\u0006 ולהביא ממקום למקום\u0005],\u0006 \u0003והאי\u0004 \u0005[ו\u0006את \u0005אלה]\u0006 בעלי חיים קטנים — \u0003לא מיכניף ליה\u0004 \u0005[אינם יכולים לאסוף].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לר' חייא: לדידי חזי לי ההוא טייעא דשקליה לספסירא וגיידיה לגמלא\u0004 \u0005[אני עצמי ראיתי ערבי אחד שלקח סייף וחתך את הגמל]\u0006 \u0003וטרף ליה בטבלא\u0004 \u0005[ו\u0006אחר כך \u0005הקיש לו בתוף]\u0006 \u0003וקם\u0004 הגמל לתחיה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003לבתר הכי\u0004 \u0005[אחר כך]\u0006 \u0003דם ופרתא\u0004 \u0005[ופרש]\u0006 \u0003מי הואי\u0004 \u0005[האם היה\u0006 שם\u0005],\u0006 ממה שזב מן הגמל כשנחתך? \u0003אלא\u0004 כיון שלא היה הרי זה מוכיח כי \u0003ההיא אחיזת עינים הוה\u0004 \u0005[היתה]\u0006 ולא כשפים.","מסופר: \u0003זעירי איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לאלכסנדריא של מצרים, זבן חמרא\u0004 \u0005[קנה חמור].\u0006 \u0003כי מטא לאשקוייה מיא פשר, וקם גמלא דוסקניתא\u0004 \u0005[כאשר הגיע להשקותו מים הפשיר\u0006 הקסם ונתגלה שאינו חמור, \u0005ונעשה דף של גשר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 המוכרים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003זעירי\u0004 שאדם גדול \u0003את\u0004 \u0005[אתה]\u0006 \u0003לא הוה מהדרינן\u0004 \u0005[היינו מחזירים]\u0006 \u0003לך\u0004 דמי החמור, \u0003מי איכא דזבין מידי הכא ולא בדיק ליה אמיא\u0004 \u0005[האם יש מי שקונה כאן,\u0006 במקום כשפים, \u0005ואינו בודק אותו במים]?\u0006 אלא הכל בודקים כדי לדעת אם מכושף הדבר הנמכר, ואם לא בדק ונמצא קסם — הפסיד.","מסופר: \u0003ינאי איקלע לההוא אושפיזא\u0004 \u0005[נזדמן לפונדק אחד],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אשקין מיא\u0004 \u0005[השקוני מים]!\u0006 \u0003קריבו שתיתא\u0004 \u0005[הביאו\u0006 לו \u0005קמח מעורב מים].\u0006 \u0003חזא דקא מרחשן שפוותה\u0004 \u0005[ראה שמרחשות שפתיה]\u0006 של בעלת האכסניא, \u0003שדא פורתא מיניה הוו עקרבי\u0004 \u0005[השליך מעט ממנו,\u0006 מהמשקה, לארץ ו\u0005נעשו\u0006 ממנו \u0005עקרבים]\u0006 והבין שכשפים בדבר. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא שתאי מדידכו, אתון נמי שתו מדידי\u0004 \u0005[אני שתיתי משלכם, שתו גם אתם משלי]\u0006 ואף הוא עשה כעין כשפים. \u0003אשקייה, הואי חמרא\u0004 \u0005[השקה אותה, נעשתה חמור],\u0006 \u0003רכבה, סליק לשוקא\u0004 \u0005[רכב עליה\u0006 ו\u0005הלך לשוק].\u0006 \u0003אתא\u0004 \u0005[באה]\u0006 \u0003חברתה פשרה לה\u0004 \u0005[התירה אותה\u0006 מן הכשפים\u0005],\u0006 \u0003חזייה דרכיב וקאי אאיתתא בשוקא\u0004 \u0005[ראוהו ש\u0006הוא \u0005רוכב על אשה בשוק].\u0006","בענין מכות מצרים נאמר: \u0003\"ותעל הצפרדע ותכס את ארץ מצרים\"\u0004 (שמות ח, ב), \u0003אמר ר' אלעזר: צפרדע אחת היתה\u0004 בתחילה, \u0003השריצה ומלאה כל ארץ מצרים\u0004 צפרדעים.","ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים,\u0006 שנחלקו בדבר\u0005],\u0006 \u0003ר' עקיבא אומר: צפרדע אחת היתה ומלאה\u0004 את \u0003כל ארץ מצרים. אמר לו ר' אלעזר בן עזריה: עקיבא, מה לך אצל הגדה?\u0004 אין זה התחום שאתה מצטיין בו, \u0003כלה מדברותיך ולך אצל נגעים\u0004 (דיני צרעת) \u0003ואהלות\u0004 (דיני אהל המת), שהם מההלכות החמורות בתורה ואתה גדול בהן. ולענין פירוש לשון הכתוב, כך יש להבין: \u0003צפרדע אחת היתה, שרקה להם והם באו\u0004 כולן אחריה.","\u0003אמר ר' עקיבא\u0004 בשם ר' יהושע גדרי הלכות כשפים, ונטיעת קישואים על ידי כישוף."],["ושואלים: \u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 \u0003ר' עקיבא מר' יהושע גמיר לה\u0004 \u0005[למד אותה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשחלה ר' אליעזר נכנסו ר' עקיבא וחביריו לבקרו. הוא יושב בקינוף\u0004 (בתוך כילה) \u0003שלו, והן יושבין בטרקלין שלו\u0004 שלא ידעו אם יוכל לקבלם, מפני חוליו. \u0003ואותו היום ערב שבת היה, ונכנס הורקנוס בנו לחלוץ תפליו,\u0004 שהרי אין מניחים תפילין בשבת, \u0003גער בו\u0004 אביו \u0003ויצא בנזיפה. אמר להן\u0004 הורקנוס \u0003לחביריו\u0004 של אביו: \u0003כמדומה אני שדעתו של אבא נטרפה\u0004 ונתבלבלה, שגוער בי ללא טעם. שמע זאת אביו ר' אליעזר, \u0003אמר להן: דעתו\u0004 של הבן \u0003ודעת אמו נטרפה, היאך מניחין איסור סקילה,\u0004 כלומר, לדאוג לענייני שבת שיש בהם איסור סקילה כהדלקת הנר והכנת החמין, \u0003ועוסקין באיסור שבות\u0004 של הנחת תפילין בשבת, שאינה אלא מדברי חכמים?","","\u0003כיון שראו חכמים\u0004 מתוך דברים אלה \u0003שדעתו מיושבת עליו, נכנסו וישבו לפניו מרחוק ארבע אמות\u0004 שהרי מנודה היה, ואסור לשבת בתוך ארבע אמות של מנודה. \u0003אמר להם: למה באתם? אמרו לו: ללמוד תורה באנו,\u0004 שלא רצו לומר שבאו לבקרו בגלל מחלתו האחרונה. \u0003אמר להם: ועד עכשיו למה לא באתם? אמרו לו: לא היה לנו פנאי. אמר להן: תמיה אני אם ימותו מיתת עצמן\u0004 כדרך הטבע, אלא ימותו ביסורים על ידי הרומאים. \u0003אמר לו ר' עקיבא: שלי,\u0004 דרך מיתתי, \u0003מהו? אמר לו:\u0004 מיתתך \u0003שלך\u0004 תהא \u0003קשה משלהן,\u0004 שהרי אתה היית כתלמיד מובהק לי, ולא באת ללמוד.","","\u0003נטל\u0004 ר' אליעזר \u0003שתי זרועותיו והניחן על לבו, אמר: אוי לכם שתי זרועותיי שהן כשתי ספרי תורה שנגללין\u0004 עכשיו, ושוב לא יתגלו. \u0003הרבה תורה למדתי, והרבה תורה לימדתי. הרבה תורה למדתי ולא חסרתי מרבותי,\u0004 כלומר, לא קיבלתי מחכמתם \u0003אפילו ככלב המלקק מן הים, הרבה תורה לימדתי ולא חסרוני\u0004 (קיבלו ממני) \u0003תלמידי אלא כמכחול בשפופרת\u0004 המוציא רק מעט מאוד מן הצבע.","\u0003ולא עוד אלא שאני שונה שלש מאות הלכות בבהרת עזה\u0004 בדיני צרעת, \u0003ולא היה אדם ששואלני בהן דבר מעולם,\u0004 שלא מצא לו תלמיד היכול להגיע לסוף דעתו בדברים אלה. \u0003ולא עוד אלא שאני שונה שלש מאות הלכות, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003שלשת אלפים הלכות בנטיעת קשואין,\u0004 על ידי כשפים, \u0003ולא היה אדם שואלני בהן\u0004 \u0003דבר מעולם, חוץ מעקיבא בן יוסף.\u0004","וכך היה המעשה: \u0003פעם אחת אני והוא מהלכין היינו בדרך, אמר לי: רבי, למדני בנטיעת קשואין. אמרתי דבר אחד\u0004 של כשפים ו\u0003נתמלאה כל השדה קשואין. אמר לי: רבי, למדתני נטיעתן, למדני עקירתן! אמרתי דבר אחד, נתקבצו כולן למקום אחד.\u0004","אחר דברים אלה \u0003אמרו לו\u0004 חכמים בהלכה: \u0003הכדור\u0004 הממולא מבפנים בסמרטוטים ומבחוץ הריהו עשוי עור, \u0003ו\u0004כן \u0003האמוס\u0004 שהוא התבנית שעליה עושים את הנעל, ובתוכה סמרטוטים ומסביבה עור, \u0003ו\u0004כן \u0003הקמיע\u0004 שיש בו עור מבחוץ, \u0003וצרור המרגליות\u0004 העטוף בעור, \u0003ומשקולת קטנה\u0004 שעוטפים אותה בעור, \u0003מהו\u0004 דינם לענין טומאה? \u0003אמר להן: הן טמאין וטהרתן במה שהן,\u0004 כלומר, כשבאים לטהרם במקוה מיטהרים הם כמו שהם, ואין צורך לפתחם.","ועוד שאלו אותו: \u0003מנעל שעל גבי האמוס מהו\u0004 דינו? האם אומרים אנו שהוא כבר כלי גמור ואינו צריך לגמר מלאכה ולכן מוכשר לקבל טומאה, או לא? \u0003אמר להן: הוא טהור, ו\u0004במלה זו \u0003יצאה נשמתו בטהרה. עמד ר' יהושע על רגליו ואמר: הותר הנדר, הותר הנדר!\u0004 כלומר, הותר האיסור והנידוי שהוטל על ר' אליעזר.","בשעת הפטירה ממש לא היה שם ר' עקיבא, \u0003למוצאי שבת פגע\u0004 (פגש) \u0003בו ר' עקיבא\u0004 בלוויה בלכתו \u0003מן קיסרי ללוד, היה\u0004 ר' עקיבא \u0003מכה בבשרו\u0004 מרוב צער וחרטה \u0003עד שדמו שותת לארץ. פתח עליו\u0004 בדברי הספד \u0003בשורה\u0004 של המנחמים, \u0003ואמר: \"אבי אבי רכב ישראל ופרשיו\"\u0004 (מלכים ב' ב, יב), \u0003הרבה מעות\u0004 (כסף) \u0003יש לי ואין לי שולחני להרצותן,\u0004 כלומר, הרבה שאלות יש לי ולאחר מותך אין לי מי שיוכל לפתור אותן, ומסיפור זה למדנו לענייננו:","\u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מר' אליעזר גמרה\u0004 \u0005[למדה]\u0006 להלכות נטיעת קישואים ולא מר' יהושע! ומשיבים: \u0003גמרה\u0004 \u0005[למדה]\u0006 \u0003מר' אליעזר ולא סברה\u0004 \u0005[הבינה],\u0006 \u0003הדר גמרה\u0004 \u0005[אחר כך למד]\u0006 ענין זה \u0003מר' יהושע ואסברה ניהליה\u0004 \u0005[והסביר לו אותה].\u0006","ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה\u0006 ר' אליעזר \u0005כך]\u0006 מעשה של כשפים? \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 ש\u0003העושה מעשה\u0004 של כשפים \u0003חייב!\u0004 ומשיבים: \u0003להתלמד שאני\u0004 \u0005[שונה]\u0006 ומותר, שאם רוצה אדם ללמוד דבר ולא להשתמש בו אלא כדי לדעת אותו — מותר לו. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"לא תלמד לעשות\u0004 כתועבות הגויים ההם. לא ימצא בך... קוסם קסמים מעונן ומנחש ומכשף\u0003\"\u0004 (דברים יח, ט—י), והכוונה: \u0003לעשות אי אתה למד, אבל אתה למד\u0004 כדי \u0003להבין\u0004 את הדבר בעצמך \u0003ולהורות\u0004",""],["\u0003בן סורר ומורה,\u0004 שהוא מן הנסקלים, \u0003מאימתי נעשה בן סורר ומורה\u0004 להתחייב סקילה —","\u0003משיביא שתי שערות,\u0004 שהן סימני בגרות מינית שמאז נחשב גדול, \u0003ועד שיקיף זקן\u0004 בשערות, והכוונה לזקן \u0003התחתון,\u0004 למקום הערוה, \u0003ולא העליון\u0004 (זקן ממש), \u0003אלא שדברו חכמים בלשון נקיה.\u0004 וראיה לקביעה זו — ממה \u0003שנאמר\u0004 \u0003\"כי יהיה לאיש בן\u0004 סורר ומורה\u0003\"\u0004 (דברים כא, יח), וממשמעות כתוב זה למדו: \u0003בן\u0004 — \u0003ולא בת, בן\u0004 — \u0003ולא איש\u0004 מבוגר. \u0003קטן פטור\u0004 מעונש סורר ומורה מפני \u0003שלא בא\u0004 עדיין \u0003לכלל מצות.\u0004","על האמור במשנה שואלים: \u0003קטן מנלן\u0004 \u0005[מניין\u0006 \u0005לנו]\u0006 ש\u0003פטור\u0004 מדין בן סורר ומורה? על שאלה זו תוהים: מה משמע \u0003מנלן\u0004 \u0005[מניין\u0006 \u0005לנו]?!\u0006 הלא \u0003כדקתני טעמא\u0004 \u0005[כפי ששנינו\u0006 את \u0005הטעם\u0006\u0005]\u0006 במשנתנו: \u0003שלא בא לכלל מצות! ותו\u0004 \u0005[ועוד\u0006\u0005]:\u0006 \u0003היכא אשכחן\u0004 \u0005[היכן מצאנו]\u0006 ש\u0003ענש הכתוב\u0004 קטן בכל דבר, \u0003דהכא ליבעי קרא למיפטריה\u0004 \u0005[\u0006\u0005שכאן יצטרכו כתוב\u0006 מיוחד \u0005לפטור אותו\u0006\u0005]?!\u0006","ומסבירים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנחנו כך אמרנו\u0006\u0005],\u0006 כך יש להבין את השאלה: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003בן סורר ומורה על חטאו נהרג?\u0004 הלא כפי שמוסבר להלן \u0003על שם סופו נהרג.\u0004 שאמרה התורה שכיון שמתחיל בדרך רעה זו כעת, ודאי יגיע לדברים גרועים יותר בעתיד, ומוטב שימות זכאי ואל ימות חייב. \u0003וכיון\u0004 ש\u0003על שם סופו\u0004 הוא \u0003נהרג,\u0004 יתכן לומר כי \u0003אפילו קטן נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 יידון כבן סורר ומורה! \u0003ועוד\u0004: אם נדייק היטב בלשון המקרא המיעוט \u0003\"בן\" ולא איש\u0004 — \u0003קטן משמע,\u0004 שהרי אינו עדיין איש (שמשמעו — גדול)!","\u0003אמר רב יהודה אמר רב:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכי יהיה לאיש בן\",\u0004 ואנו רואים זאת כביטוי אחד הבא לומר: \u0003בן הסמוך לגבורתו של איש,\u0004 כלומר, בן הסמוך למלוא בגרותו הוא הנידון כבן סורר ומורה, ולא הקטן.","שנינו במשנה שהזמן בו הוא נידון כבן סורר ומורה הוא \u0003עד שיקיף זקן התחתון. תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: עד שיקיף עטרה,\u0004 שיקיף שיער סביב אבר המין. \u0003כי אתא\u0004 \u0005[כאשר בא\u0006\u0005]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 כהסבר לדברי ר' חייא: \u0003הקפת גיד\u0004 (האבר) בשיער שנינו, \u0003ולא הקפת ביצים\u0004 בשיער, שהקפת אברי המין כולם זמנה מאוחר יותר.","\u0003אמר רב חסדא: קטן שהוליד,\u0004 אם אירע דבר זה — \u0003אין בנו נעשה בן סורר ומורה, שנאמר: \"כי יהיה לאיש בן\"\u0004 (דברים כא, יח) \u0003\"לאיש\"\u0004 מבוגר \u0003בן, ולא לבן בן.\u0004 ומקשים: הלא \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה\u0006\u0005]\u0006 \u0003מיבעי ליה\u0004 \u0005[נחוץ לו\u0006\u0005]\u0006 \u0003ל\u0004מה ש\u0003רב יהודה אמר\u0004 בשם \u0003רב,\u0004 להוכיח שקטן אינו נידון כבן סורר ומורה! ומשיבים: כתוב זה בא ללמד שני עניינים. ש\u0003אם כן\u0004 שהיתה הכוונה רק לענין גיל, לדבר אחד, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 בלשון \u0003\"כי יהיה בן לאיש\" מאי\u0004 \u0005[מה\u0006\u0005]\u0006 טעם בשינוי הסדר המקובל וכתיבתו בלשון \u0003\"כי יהיה לאיש בן\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 לכדברי \u0003רב חסדא\u0004 הוא בא.","ושואלים: אם כן \u0003אימא כוליה להכי\u0004 \u0005[אמור\u0006 כל הפסוק \u0005כולו ל\u0006דבר \u0005זה]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמדנו, וכלל לא בא ללמד שאין קטן בכלל דין סורר ומורה! ומשיבים: אינו מסתבר, שכן \u0003אם כן נימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 בלשון \u0003\"בן איש\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לאיש בן\", שמע מינה תרתי\u0004 \u0005[למד ממנה שני\u0006 דברים\u0005].\u0006","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה\u0006\u0005]\u0006 דעה זו, על שיטת \u0003רבה.\u0004 ש\u0003אמר רבה\u0004 אגב הדינים העוסקים באדם המשיב גזילה אחר שנתבע להחזיר את שגזל והכחיש שגזל ונשבע לשקר: \u0003קטן אינו מוליד, שנאמר: \"\u0004ו\u0003אם אין לאיש גאל\u0004 להשיב האשם אליו\u0003\"\u0004 (במדבר ה, ח), ויש לשאול: \u0003וכי יש לך אדם בישראל שאין לו גואל?\u0004 והרי זכות הירושה מגעת דרך האבות עד ליעקב אבינו, ואם מישראל הוא — ודאי שיש לו קרוב!","\u0003אלא, בגזל הגר הכתוב מדבר,\u0004 שכיון שנתגייר ניתקו קשריו עם משפחתו הקודמת, ואם לא הוליד ילדים ביהדותו — הריהו אדם שאין לו קרובים כלל,"],["\u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה\u0006\u0005]:\u0006 \u0003\"איש\",\u0004 ללמד: \u0003איש\u0004 גר \u0003אתה צריך לחזור עליו\u0004 ולבדוק אחריו \u0003אם יש לו גואלין,\u0004 בנים שנולדו לו לאחר שהתגייר, \u0003ואם לאו\u0004 \u0005[לא],\u0006 ואולם גר \u0003קטן\u0004 — \u0003אי\u0004 (אין) \u0003אתה צריך לחזור עליו,\u0004 כי \u0003בידוע שאין לו גואלין,\u0004 לפי שקטן אינו מוליד.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא לענין שפחה חרופה: נאמר \"ואיש כי ישכב את אשה שכבת זרע והיא שפחה נחרפת לאיש\" (ויקרא יט, כ), וממה שאמר הכתוב \u0003\"איש\" אין לי,\u0004 איני למד \u0003אלא איש\u0004 שהוא גדול, ואולם \u0003בן תשע שנים ויום אחד שראוי לביאה מניין\u0004 שאף הוא בכלל זה? — \u0003תלמוד לומר: \"ואיש\"\u0004 שהוא\"ו באה לרבות לענין זה אף את הקטן בן תשע שנים שכבר בגיל כזה יכול הוא לבעול ביאה גמורה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 מכאן אין ראיה, שאמנם \u0003יש לו\u0004 שכבת זרע \u0003ו\u0004אולם \u0003אינו מוליד, כתבואה שלא הביאה שליש דמי,\u0004 שנקצרה לפני שהגיעה לשליש בישולה, שאף שנראית כתבואה גמורה, אם זורעים אותה אינה מצמחת.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה תנא\u0004 \u0005[שנו]:\u0006 נאמר \u0003\"וכי יזד איש\"\u0004 (שמות כא, יד), ומלשון זה של מזיד למדים בדרך אגב כי \u0003איש מזיד ומזריע\u0004 (מבשיל זרעו) \u0003ואין קטן מזיד ומזריע,\u0004 ואף שיכול לבוא על אשה אינו יכול להוליד! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: מאי\u0004 \u0005[מה]\u0006 \u0003משמע,\u0004 כיצד מובן \u0003דהאי\u0004 \u0005[שזה]\u0006 לשון \u0003\"מזיד\" לישנא דבשולי\u0004 \u0005[לשון של בישול]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויזד יעקב נזיד\"\u0004 (בראשית כה, כט), שמשמעו — בישול תבשיל.","לגוף הענין שואלים: \u0003והא תנא דבי\u0004 \u0005[והרי שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 לדרוש את הדברים בדין סורר ומורה: מה שנאמר \u0003\"בן\",\u0004 הרי זה בא ללמד: \u0003ולא אב,\u0004 שאם לבן הסורר היה בן אינו נידון כסורר ומורה,","\u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה\u0006\u0005]?\u0006 \u0003אילימא דאיעבר בתר דאייתי\u0004 \u0005[אם תאמר שהתעברה\u0006 אשתו \u0005אחרי שהביא]\u0006 \u0003שתי שערות, ואוליד מקמי דלקיף\u0004 \u0005[והוליד לפני שהקיף]\u0006 \u0003זקן\u0004 \u0003מי איכא\u0004 \u0005[האם יש]\u0006 \u0003שהות כולי האי\u0004 \u0005[כל כך\u0006\u0005]\u0006 להוליד? \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003אמר ר' כרוספדאי:\u0004 \u0003כל ימיו של בן סורר ומורה\u0004 שבהם אפשר לדונו ולחייבו \u0003אינן אלא שלשה חדשים בלבד\u0004 שזהו הזמן העובר בין הבאת שתי שערות להקפת זקן. ולא יתכן שבפרק זמן זה נולד לסורר ומורה בן. \u0003אלא לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 הכוונה \u0003דאיעבר מקמי דלייתי\u0004 \u0005[שהתעברה\u0006 אשתו \u0005לפני שהביא]\u0006 \u0003שתי שערות ואוליד מקמיה דלקיף\u0004 \u0005[והולידה לפני שהקיף]\u0006 \u0003זקן,\u0004 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן\u0006\u0005]\u0006 כי \u0003קטן מוליד!\u0004","ודוחים: \u0003לא, לעולם\u0004 תפרש \u0003דאיעבר בתר דאייתי\u0004 \u0005[שהתעברה\u0006 אשתו \u0005אחר שהביא]\u0006 \u0003שתי שערות, ואוליד בתר דאקיף\u0004 \u0005[והוליד אחר שהקיף]\u0006 \u0003זקן,\u0004 \u0003ודקא קשיא\u0004 \u0005[ומה שקשה]\u0006 מדברי \u0003ר' כרוספדאי\u0004 האומר כי דין סורר ומורה חל רק בשלושה חדשים יש לפרשו כך : \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל\u0006\u0005]\u0006 כי הכוונה היא שמהמלה \"בן\" למדים כי דין זה הוא דווקא ב\u0003בן ולא\u0004 בזה \u0003הראוי לקרותו אב,\u0004 שלאו דווקא באותם חדשים יוולד לו בן, אלא שתהא אשתו בהריון ויהא ראוי לקרותו אב.","\u0003גופא\u0004 \u0005[לגוף\u0006 אותה הלכה\u0005]\u0006 שהזכרנו, \u0003אמר ר' כרוספדאי אמר ר' שבתי: כל ימיו של בן סורר ומורה אינן אלא שלשה חדשים בלבד.\u0004 ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 \u0003משיביא שתי שערות ועד שיקיף זקן\u0004 משמע שזוהי הגדרת הדברים, ואין הדבר תלוי בזמן! ומשיבים: \u0003הקיף זקן\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003לא מלו\u0004 (מלאו) \u0003שלשה חדשים\u0004 הריהו פטור, וכן אם \u0003מלו שלשה חדשים אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003לא הקיף\u0004 —","פטור. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' יעקב מנהר פקוד קמיה\u0004 \u0005[לפני]\u0006 \u0003רבינא ויתיב וקאמר משמיה\u0004 \u0005[והיה יושב ואומר משמו\u0006\u0005]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 \u0003שמע מינה\u0004 \u0005[למד ממנו\u0006\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' כרוספדאי\u0004 ש\u0003אמר\u0004 בשם \u0003ר' שבתי:\u0004 זו \u0003ה\u0004\u0003יולדת לשבעה\u0004 חודשים — \u0003אין עוברה ניכר לשליש ימיה\u0004 (שני חודשים ושליש), כשם שהיולדת כרגיל, לתשעה, מכירים שהיא מעוברת לשלושה חודשים שהם שליש ימי הריונה.","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006\u0005]\u0006 שאף זו היולדת לשבעה \u0003עוברה ניכר לשליש ימיה, למה לי שלשה\u0004 חדשים בין זמן גדלות לסוף זמן סורר ומורה? הלא בשליש משבעה חדשים, שהוא \u0003בתרי ותילתא, סגיא\u0004 \u0005[בשני\u0006 חדשים \u0005ושליש, די\u0006\u0005].\u0006 שאם בא על אשה משהגדיל, יכול העובר להיות ניכר אף בתוך זמן זה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא לר' יעקב: \u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 כי אף זו היולדת לשבעה \u0003עוברה ניכר לשליש ימיה,\u0004 ומה שלא קבעו הלכה כן, הטעם הוא משום הכלל הנקוט בידינו כי \u0003זיל בתר רובא\u0004 \u0005[לך אחר הרוב\u0006\u0005]\u0006 ורוב נשים יולדות לתשעה, ועוברן ניכר בשלושה.","\u0003אמרוה\u0004 למשא ומתן זה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לזה שהביאה לפניו: \u0003ובדיני נפשות מי אזלינן בתר רובא\u0004 \u0005[האם הולכים אנו אחר הרוב\u0006\u0005],\u0006 ואין בודקים כל מקרה לגופו? והלא \u0003התורה אמרה: \"ושפטו העדה... והצילו העדה\"\u0004 (במדבר לה, כד–כה), ומכאן שחייב בית הדין להשתדל למצוא כל צד זכות שיש לנאשם \u0003ואת אמרת זיל בתר רובא\u0004 \u0005[ואתה אומר לך אחר הרוב\u0006\u0005]?!\u0006 והרי אם יש אפשרות שתוך חודשיים ושליש יהא ראוי לאבהות אם כן יפטרוהו כבר אז מעונש!","\u0003אהדרוה קמיה\u0004 \u0005[החזירוה\u0006 לתשובה זו \u0005לפני]\u0006 \u0003רבינא\u0004 \u0003אמר להו\u0004 \u0005[להם],\u0006 למביאי השמועה: \u0003ו\u0004כי \u0003בדיני נפשות לא אזלינן בתר רובא\u0004 \u0005[אין אנו הולכים אחר הרוב\u0006\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בפירוש: \u0003אחד\u0004 העדים \u0003אומר\u0004 שהמאורע היה \u0003בשנים בחדש ואחד אומר\u0004 שהמאורע היה \u0003בשלשה\u0004 בחודש — \u0003עדותן קיימת,\u0004 שאנו אומרים \u0003שזה יודע בעיבורו של חדש\u0004 ויודע שעיברו את החודש הקודם ולפיכך היה הוא בן שלושים יום, ובשל כך החודש שאחריו, אותו חודש בו אירע המאורע, נכנס באיחור יום, ולכך אכן היה זה רק ביום שני בחודש, \u0003וזה אינו יודע\u0004 בעיבורו של חודש, וסבור שהחודש הקודם היה רק בן עשרים ותשעה ימים, ויום זה הוא איפוא כבר שלישי בחודש הוא.","\u0003ואי סלקא דעתך לא אמרינן זיל בתר רובא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר כי \u0005אין אנו אומרים לך אחר הרוב\u0006\u0005]\u0006 בדיני נפשות, \u0003נימא\u0004 \u0005[נאמר]\u0006 כי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003דוקא\u0004 (בדיוק) \u0003קא מסהדי\u0004 \u0005[הם מעידים]\u0006 כפי שאמרו \u0003ואכחושי\u0004 \u0005[ולהכחיש]\u0006 \u0003הוא דקא מכחשי אהדדי\u0004 \u0005[שהם מכחישים זה את זה\u0006\u0005]\u0006 ועל ידי כך ייפטר הנאשם! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003זיל בתר רובא\u0004 \u0005[לך אחר הרוב],\u0006 \u0003ורובא דאינשי עבדי דטעו בעיבורא דירחא\u0004 \u0005[ורוב האנשים עשויים שיטעו בעיבור החודש\u0006\u0005]!\u0006","\u0003אמר ר' ירמיה מדפתי: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו\u0006\u0005]\u0006 הוכחה אחרת שאף בדיני נפשות הולכים אחר הרוב. כיצד, ששנינו: ילדה \u0003בת שלש שנים ויום אחד מתקדשת\u0004 גם על ידי \u0003ביאה\u0004 שכן היא נחשבת מגיל זה כראוייה לביאה. \u0003ואם\u0004 אחר שמת בעלה בלא בנים ונזקקה לייבום \u0003בא עליה יבם\u0004 (אחי בעלה) — \u0003קנאה\u0004 להיות אשתו, כדין יבם הבא על יבמתו, \u0003וחייבין עליה,\u0004 על ביאתה, \u0003משום אשת איש,\u0004 אם היה כזו.","\u0003ו\u0004אם היתה נדה — \u0003מטמאה את בועלה\u0004 כבא על הנדה \u0003לטמא משכב התחתון כעליון,\u0004 שכל מצע ששוכב עליו (\"התחתון\") גם אם אינו נוגע בו, נעשה טמא כבגדו של זב (\"עליון\"). ואם בא על קטנה פחות מבת שלוש דינו רק כנוגע בנדה שמטמא רק במגע לא במשכב. ואם \u0003נישאת לכהן\u0004 — \u0003אוכלת בתרומה\u0004 כאשת כהן לכל דבר. ואם היתה בת כהן ו\u0003בא עליה אחד מן הפסולין,\u0004 כגון כותי, חלל, נתין, או ממזר — \u0003פסלה מן הכהונה. ואם בא עליה אחד מכל העריות האמורות בתורה מומתין\u0004 הם \u0003עליה,\u0004 שהרי ביאתה ביאה, \u0003והיא\u0004 עצמה \u0003פטורה\u0004 שהרי אינה בת עונשים."],["\u0003ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 אומר אתה שיתחייב הבא עליה בכל ענשים אלה? \u0003אימא\u0004 \u0005[אמור\u0006 שמא\u0005]\u0006 \u0003איילונית היא\u0004 שאינה ראויה להוליד כלל, \u0003ואדעתא דהכי\u0004 \u0005[ועל דעת כן]\u0006 \u0003לא קדיש\u0004 \u0005[קידש\u0006\u0005],\u0006 ונמצא שקידושין אלה בטלים משום שהיו קידושי טעות, ואם בא עליה אחר — אינו חייב מיתה. \u0003אלא לאו, דאמרינן\u0004 \u0005[האם לא, שאומרים אנו]:\u0006 \u0003זיל בתר רובא\u0004 \u0005[לך אחר רוב\u0006\u0005]\u0006 \u0003ורוב נשים לאו\u0004 \u0005[לא]\u0006 \u0003איילונית נינהו\u0004 \u0005[הן\u0006\u0005],\u0006 ומשום כך מניחים שקידושין אלה היו קידושי ודאי. הרי שאף בנפשות הולכים אחר הרוב!","ודוחים: \u0003לא,\u0004 מכאן אין להביא ראיה, שכן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חייב עליה\" דקתני\u0004 \u0005[ששנינו\u0006\u0005]\u0006 — כוונתו: שחייב להביא \u0003קרבן\u0004 אם שגג בכך אבל אין ממיתים על ידי חזקה בלבד.","ומקשים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003\"מומתין על ידה\" קתני\u0004 \u0005[שנינו\u0006\u0005]!\u0006 ומשיבים: מדובר כאן ש\u0003בא עליה אביה\u0004 או אחד משאר קרוביה, שאין האיסור תלוי בנישואין, אבל אם בא מישהו שאינו מקרוביה לא יתחייב מיתה.","ושואלים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003\"אם בא עליה אחד מכל העריות\" קתני\u0004 \u0005[שנינו\u0006\u0005],\u0006 ומשמע אפילו עריות התלויות בקשר נישואין! \u0003אלא\u0004 אפשר לדחות ולומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים\u0006\u0005]\u0006 — ש\u0003קבלה עילויה\u0004 \u0005[על עצמו\u0006\u0005],\u0006 שהמקדש אמר שהוא מקדש אותה קידושין גמורים גם על דעת שתימצא איילונית, ולפיכך מתחייב בועלה מיתה גם אם אינו מקרוביה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המסוללת\u0004 (עושה מעשה פריצות) \u0003בבנה קטן, והערה בה\u0004 (עשה בה תחילת ביאה) — \u0003בית שמאי אומרים\u0004 שעל ידי כך \u0003פסלה מן הכהונה, ובית הלל מכשירין,\u0004 שלדעתם קטן אינו יכול להגיע לביאה.","\u0003אמר ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר נחמני אמר רב חסדא, ואמרי לה\u0004 \u0005[ויש אומרים\u0006\u0005]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חסדא אמר זעירי: הכל מודים ב\u0004ילד \u0003בן תשע שנים ויום אחד שביאתו ביאה\u0004 לפסול ולהמית עליו (אף שהוא עצמו אינו בר עונשים). ילד \u0003פחות מבן שמנה\u0004 לכל הדעות — \u0003אין ביאתו ביאה. לא נחלקו אלא ב\u0004ילד \u0003בן שמנה.\u0004 ש\u0003בית שמאי סברי\u0004 \u0005[סוברים\u0006\u0005]:\u0006 \u0003גמרינן\u0004 \u0005[לומדים אנו\u0006\u0005]\u0006 \u0003מדורות הראשונים,\u0004 שאפשר להוכיח שהולידו בגיל זה, \u0003ובית הלל סברי\u0004 \u0005[סוברים\u0006\u0005]:\u0006 \u0003לא גמרינן\u0004 \u0005[אין אנו לומדים\u0006\u0005]\u0006 \u0003מדורות הראשונים.\u0004","ושואלים: \u0003ודורות הראשונים מנלן דאוליד\u0004 \u0005[מניין לנו שהולידו\u0006\u0005]\u0006 בגיל זה? \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006שום \u0005שנאמר\u0006\u0005]:\u0006 \u0003\"הלוא זאת בת־שבע בת אליעם אשת אוריה ה. חתי\"\u0004 (שמואל ב' יא, ג) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואליעם בן אחיתפל הגלני\"\u0004 (שם כג, לד), הרי שבת שבע היתה נכדתו של אחיתופל. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 כשנולד שלמה: \u0003\"וישלח ביד נתן הנביא ויקרא את שמו ידידיה בעבור ה' \" \u0004(שמואל ב' יב, כה)","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי לשנתים ימים ויהיו גזזים לאבשלום\"\u0004 (שמואל ב' יג, כג), ואז נהרג אמנון (ראה שמואל ב' כג–כט), שהיה זה שנתים לפחות אחרי הולדת שלמה, \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 אחר כך: \u0003\"ואבשלום ברח וילך גשורה ויהי שם שלש שנים\"\u0004 (שמואל ב' יב, לח) הרי חמש שנים מהולדת שלמה, \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 אחר כך:","\u0003\"וישב אבשלום בירושל ם שנתים ימים ופני המלך לא ראה\"\u0004 (שמואל ב' יד, כח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי מקץ ארבעים שנה ויאמר אבשלום אל המלך אלכה נא ואשלמה את נדרי אשר נדרתי לה' בחברון\"\u0004 (שמואל ב' טו ז), וזו היתה תחילת מרידתו, ואז היה שלמה לפחות בן שבע. ובאמצע המרידה נאמר \u0003\"ואחיתפל ראה כי לא נעשתה עצתו ויחבש את החמור ויקם וילך אל ביתו אל עירו ויצו אל ביתו ויחנק\"\u0004 (שמואל ב' יז, כג)","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אנשי דמים ומרמה לא יחצו ימיהם\"\u0004 (תהלים נה, כד) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 כי דבר זה נאמר לגבי אנשים מסויימים; \u0003כל שנותיו של דואג אינן אלא שלשים וארבע,\u0004 שלא הגיע לחצי ימיו \u0003ושל אחיתפל אינן אלא שלשים ושלש.\u0004 ומעתה נחשב \u0003כמה הויא להו\u0004 \u0005[היו להן\u0006\u0005]\u0006 שנותיו — \u0003תלתין ותלת\u0004 \u0005[שלושים ושלוש\u0006\u0005]\u0006 \u0003דל\u0004 \u0005[הוצא]\u0006 מהן \u0003שבע\u0004 שנים \u0003דהוה\u0004 \u0005[שהיה]\u0006 אז כבר \u0003שלמה,\u0004 \u0003פש להו עשרים ושית\u0004 \u0005[נשארו להם עשרים ושש\u0006 שנה\u0005],\u0006 שהיה אחיתופל בן עשרים ושש כשנולד שלמה. \u0003דל תרתי שני לתלתא עבורי\u0004 \u0005[הוצא שתי שנים לשלושה עיבורים\u0006\u0005]\u0006 שיש לחשב שלוש פעמים תשעה חדשי עיבור לאליעם בן אחיתופל, לבת שבע בת אליעם, ולשלמה בנה של בתשבע, \u0003אשתכח\u0004 \u0005[נמצא\u0006\u0005]\u0006 שנולדו שלושה דורות בעשרים וארבע שנים ו\u0003כל חד וחד בתמני אוליד\u0004 \u0005[וכל אחד ואחד\u0006 מהם \u0005בן שמונה הוליד\u0006\u0005],\u0006 הרי שבדורות ראשונים הולידו בני שמונה!","ודוחים: \u0003ממאי\u0004 \u0005[ממה\u0006\u0005]\u0006 מוכיח אתה דבר זה? \u0003דלמא תרוייהו\u0004 \u0005[שמא שניהם],\u0006 גם אחיתופל וגם בנו, \u0003ב\u0004היותם בני \u0003תשע אוליד\u0004 \u0005[הולידו\u0006\u0005],\u0006 \u0003ובת שבע אולידא בשית\u0004 \u0005[ילדה ב\u0006גיל \u0005שש\u0006\u0005]\u0006 \u0003משום דאיתתא בריא\u0004 \u0005[כי האשה בריאה\u0006 יותר\u0005]\u0006 \u0003תדע\u0004 שהאשה מולידה בגיל מוקדם יותר, \u0003דהא הוי\u0004 \u0005[שהרי היה]\u0006 \u0003לה ולד מעיקרא\u0004 \u0005[מתחילה,\u0006 קודם לכן\u0005]\u0006 שנולד לה מדוד, ומת לפני שנולד שלמה (ראה שמואל ב' יא, כז), ואם כן אין להוכיח מכאן כלל.","\u0003אלא מהכא\u0004 \u0005[מכאן\u0006\u0005]\u0006 תוכיח: נאמר \u0003\"\u0004ו\u0003אלה תולדת תרח תרח הוליד את אברם את נחור ואת הרן\"\u0004 (בראשית יא, כז), \u0003ואברהם גדול מנחור שנה\u0004 אחת לפחות \u0003ונחור גדול מהרן שנה\u0004 אחת, \u0003נמצא אברהם גדול שתי שנים מהרן. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויקח אברם ונחור להם נשים\u0004 שם אשת אברם שרי ושם אשת נחור מלכה בת הרן אבי מלכה ואבי יסכה\u0003\"\u0004 (בראשית יא, כט)","\u0003ואמר ר' יצחק: יסכה זו שרה, ולמה נקרא שמה \"יסכה\"\u0004 — \u0003שסוכה\u0004 (צופה) \u0003ברוח הקדש, והיינו דכתיב\u0004 \u0005[וזהו שנאמר\u0006\u0005]:\u0006 \u0003\"כל אשר תאמר אליך שרה שמע בקלה\"\u0004 (בראשית כא, יב), שאף היא היתה נביאה וצפתה ברוח הקודש. \u0003דבר אחר: \"יסכה\"\u0004 היא כינוי לשרה מפני \u0003שהכל סכים (\u0004צופים) \u0003ביופיה. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויפל אברהם על פניו ויצחק ויאמר בלבו\u0004 הלבן מאה שנה יוולד ואם שרה הבת תשעים שנה תלד\u0003\"\u0004 (בראשית יז, יז), נמצא: \u0003כמה קשיש\u0004 \u0005[זקן]\u0006 \u0003אברהם משרה\u0004 — \u0003עשר שנין\u0004 \u0005[שנים\u0006\u0005],\u0006 \u0003וקשיש מאבוה\u0004 \u0005[וזקן מאביה]\u0006 של שרה (הרן) \u0003תרתין שנין\u0004 \u0005[שתי שנים\u0006\u0005]\u0006 \u0003אשתכח כי אולדה\u0004 \u0005[נמצא\u0006 ש\u0005כאשר הוליד]\u0006 \u0003הרן לשרה בתמני אולידה\u0004 \u0005[ב\u0006היותו \u0005בן שמונה הולידה\u0006\u0005]!\u0006","ודוחים: \u0003ממאי\u0004 \u0005[ממה],\u0006 מהיכן לומד אתה דבר זה? \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003אברהם זוטא דאחוה הוה\u0004 \u0005[קטן באחיו היה\u0006\u0005]\u0006 ולא גדול שבהם, ומה שנמנה ראשון אינו ראיה כי \u0003דרך חכמתן קא חשיב להו\u0004 \u0005[מנה אותם\u0006\u0005]\u0006 ולכן נמנה אברהם בראש.","\u0003תדע\u0004 לך ראיה לדבר: \u0003דקא חשיב להו קרא\u0004 \u0005[שמנה אותם הכתוב]\u0006 את סדר הבנים בכמה מקומות \u0003דרך חכמתן, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"ויהי נח בן חמש מאות שנה ויולד נח את שם את חם ואת יפת\"\u0004 (בראשית ה, לב) אם כן לפי רשימה זו \u0003שם\u0004 היה \u0003גדול מחם שנה\u0004 אחת \u0003וחם גדול מיפת שנה, נמצא שם גדול מיפת שתי שנים. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ונח בן שש מאות שנה והמבול היה מים על הארץ\"\u0004 (בראשית ז, ו) \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]:\u0006 \u0003\"ואלה תולדת שם שם בן מאת שנה ויולד את ארפכשד שנתים אחר המבול\"\u0004 (בראשית יא, י), ואם שם גדול האחים היה כיצד היה \u0003בן מאה שנה?\u0004 הלא לכל הפחות \u0003בר מאה ותרתין שנין הוה\u0004 \u0005[בן מאה ושתי שנים היה\u0006\u0005],\u0006 שהרי נח היה בן חמש מאות כשנולד לו בנו השלישי ובשנת שש מאות לחייו אירע המבול,","\u0003אלא\u0004 ודאי \u0003דרך חכמתן קא חשיב להו\u0004 \u0005[מנה אותם\u0006\u0005]\u0006 ומבחינת הגיל היה שם הקטן ונולד בשנת חמש מאות ושתיים לחיי נח והוליד את בנו מאה שנה אחרי כן, כלומר, שנתיים אחר המבול, \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 בבני תרח אפשר לומר כי \u0003דרך חכמתן קא חשיב להו\u0004 \u0005[מנה אותם\u0006\u0005].\u0006","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי אותה את השמועה\u0006 הזו \u0005לפני]\u0006 \u0003רב זביד מנהרדעא,\u0004 ומששמע אותה \u0003אמר לי: אתון מהכא מתניתו ואנן מהכא מתנינן לה\u0004 \u0005[אתם מכאן אתם שונים\u0006 לומדים, דבר זה, ששם לא היה בכורו של נח, \u0005ואנחנו מכאן שונים\u0006 לומדים \u0005אותו\u0006\u0005],\u0006 שנאמר: \u0003\"ולשם ילד גם הוא אבי כל בני עבר אחי יפת הגדול\"\u0004 (בראשית י, כא), ומשמע ש\u0003יפת\u0004 ולא שם \u0003הגדול שבאחיו הוה\u0004 \u0005[היה]\u0006, ואם כן לא הוכחנו גם מאברהם, כי אכן ראינו שהמקרא מונה לפרקים לפי סדר חכמה.","\u0003אלא מנלן\u0004 \u0005[מניין לנו\u0006\u0005]\u0006 שבדורות הראשונים הולידו בני שמונה? — \u0003מהכא\u0004 \u0005[מכאן\u0006\u0005]\u0006 שנאמר: \u0003\"ובצלאל בן אורי בן חור למטה יהודה\u0004 עשה את כל אשר צוה ה' את משה\u0003\"\u0004 (שמות לח, כב), \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]:\u0006 \u0003\"ותמת עזובה ויקח לו כלב את אפרת ותלד לו את חור.\u0004 וחור הוליד את אורי ואורי הוליד את בצלאל\u0003\"\u0004 (דברי הימים א' ב, יט–כ), \u0003וכי עבד\u0004 \u0005[וכאשר עשה\u0006\u0005]\u0006 \u0003בצלאל משכן בר כמה הוי\u0004 \u0005[בן כמה היה]\u0006 — לכל הפחות \u0003בר תליסר\u0004 \u0005[בן שלוש עשרה\u0006\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ויבואו כל החכמים העושים את כל מלאכת הקודש \u0003איש איש ממלאכתו אשר המה עשים\"\u0004 (שמות לו, ד) ואין קרוי \"איש\" פחות מבן שלוש עשרה. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003שנה ראשונה\u0004 ליציאת מצרים \u0003עשה משה משכן.\u0004 בשנה ה\u0003שניה הקים\u0004 את ה\u0003משכן ושלח\u0004 את ה\u0003מרגלים.\u0004","\u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 שאמר כלב שהיה אבי סבו של בצלאל, ליהושע: \u0003\"בן ארבעים שנה אנכי בשלח משה עבד ה'\u0004 אותי מקדש ברנע לרגל את הארץ\u0003\"\u0004 (יהושע יד, ז), והוסיף לומר: \u0003\"ועתה הנה אנכי היום בן חמש ושמנים שנה\"\u0004 (שם י), \u0003כמה\u0004 שנים \u0003הויא להו\u0004 \u0005[היו לו]\u0006 בזמן שנשלח כלב עם המרגלים — בן \u0003ארבעין\u0004 \u0005[ארבעים],\u0006 \u0003דל ארביסר\u0004 \u0005[הוצא ארבע עשרה\u0006 שנה\u0005]\u0006 שהיה \u0003בצלאל\u0004 בן נכדו כשנשלח כלב לרגל את הארץ לפחות בן ארבע עשרה (שהרי אירע הדבר שנה לאחר הקמת המשכן), \u0003פשא להו\u0004 \u0005[נשאר להם\u0006\u0005]\u0006 \u0003עשרים ושית\u0004 \u0005[ושש\u0006\u0005]\u0006 שנים, \u0003דל תרתי שני דתלתא עיבורי\u0004 \u0005[הוצא\u0006 מכאן \u0005שתי שנים של שלושה עיבורים\u0006\u0005]\u0006 של חור בן כלב, אורי בן חור ובצלאל בן אורי, \u0003אשתכח דכל חד וחד בתמני אוליד\u0004 \u0005[נמצא שכל אחד ואחד בן שמונה הוליד\u0006\u0005],\u0006 שהרי לפי זה נולדו חור, אורי ובצלאל בתוך עשרים וארבע שנים אלה.","שנינו במשנה שדין בן סורר ומורה ב\u0003בן\u0004 דווקא \u0003ולא\u0004 ב\u0003בת.\u0004 ועוד בדין זה \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' שמעון: בדין הוא,\u0004 כלומר, מצד סברה אפשר לומר \u0003שתהא בת ראויה להיות כבן סורר ומורה\u0004 ולהיענש כמותו אם חטאה במה שחטא הוא,"],["כיון \u0003שהכל מצויין אצלה בעבירה\u0004 (בזנות), וסופה להיות חוטאת ומחטיאה את הרבים, \u0003אלא גזירת הכתוב היא\u0004 שאמרה התורה \u0003\"בן\",\u0004 ומזה משמע: \u0003ולא בת.\u0004","\u0003מאימתי חייב\u0004 בן סורר ומורה? — \u0003משיאכל\u0004 שיעור של \u0003תרטימר בשר וישתה חצי לוג יין האיטלקי. ר' יוסי אומר:\u0004 השיעור הוא \u0003מנה בשר ולוג יין.\u0004","ואולם אם \u0003אכל\u0004 דברים אלה \u0003בחבורת מצוה\u0004 או \u0003אכל ב\u0004חגיגת \u0003עיבור החדש,\u0004 או \u0003אכל מעשר שני בירושלים\u0004 שבכל אלה יש צד מצוה, ולהיפך, אם \u0003אכל נבילות וטריפות שקצים ורמשים,\u0004 או \u0003אכל טבל\u0004 (תבואה שלא הופרשו ממנה תרומות ומעשרות), או \u0003מעשר ראשון שלא נטלה\u0004 ממנו \u0003תרומתו, ומעשר שני\u0004 מחוץ לירושלים \u0003והקדש שלא נפדו\u0004 שבכל אלה יש צד עבירה, הרי במקרים כאלה אינו נעשה סורר ומורה, ובדרך הכללה:","\u0003אכל דבר שהוא מצוה ודבר שהוא עבירה,\u0004 או \u0003אכל כל מאכל\u0004 שבעולם \u0003ולא אכל בשר, שתה כל משקה ולא שתה יין\u0004 — \u0003אינו נעשה\u0004 בכך \u0003בן סורר ומורה, עד שיאכל בשר\u0004 דווקא \u0003וישתה יין\u0004 דווקא, \u0003שנאמר: \"\u0004בננו זה... \u0003זולל וסבא\"\u0004 (דברים כא, כ) ואינו קרוי \"זולל וסובא\" אלא באכילת בשר ושתיית יין דווקא. \u0003ואף על פי שאין ראיה לדבר\u0004 שזהו \"זולל וסובא\" האמור בתורה יש \u0003זכר לדבר\u0004 ממקום אחר, \u0003שנאמר: \"אל תהי בסבאי יין בזללי בשר למו\"\u0004 (משלי כג, כ).","\u0003אמר ר' זירא: \"תרטימר\" זה\u0004 שהוזכר במשנה \u0003איני יודע מהו\u0004 שיעורו, \u0003אלא מתוך שכפל ר' יוסי\u0004 בשיעור \u0003יין,\u0004 שסתם משנה אומרת חצי לוג ור' יוסי אומר לוג, מן הסתם \u0003נמצא כופל אף בבשר, ונמצא\u0004 ששיעור \u0003תרטימר\u0004 הוא משקל \u0003חצי מנה.\u0004","\u0003אמר רב חנן בר מולדה אמר רב הונא: אינו חייב עד שיקח בשר בזול ויאכל, יין בזול וישתה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זולל וסבא\",\u0004 כלומר, זולל זול.","\u0003ואמר רב חנן בר מולדה אמר רב הונא: אינו חייב עד שיאכל בשר חי\u0004 שאינו מבושל ועד ש\u0003ישתה יין חי\u0004 שאינו מזוג. ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא\u0006\u0005]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה ורב יוסף דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם\u0006\u0005]:\u0006 \u0003אכל בשר חי ושתה יין חי\u0004 — \u0003אינו נעשה בן סורר ומורה! אמר רבינא:\u0004 יש לישב את שתי השמועות: מה שאמרו \u0003יין חי,\u0004 כוונתו — \u0003מזיג\u0004 \u0005[מזוג ]\u0006 \u0003ולא מזיג\u0004 \u0005[מזוג]\u0006 כראוי, \u0003בשר חי\u0004 — \u0003בשיל\u0004 \u0005[מבושל]\u0006 \u0003ולא בשיל\u0004 \u0005[מבושל\u0006\u0005],\u0006 \u0003כבשר כיבא דאכלי גנבי\u0004 \u0005[כבשר צלי שאוכלים גנבים\u0006\u0005],\u0006 שאינם מספיקים לבשלו כראוי.","\u0003רבה ורב יוסף דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם\u0006\u0005]:\u0006 \u0003אכל\u0004 הבן הסורר והמורה \u0003בשר מליח\u0004 מאד, \u0003ושתה יין מגיתו,\u0004 כלומר, יין שלא הושלמה תסיסתו אלא יצא זה עתה מן הגת — \u0003אין נעשה בן סורר ומורה.\u0004 ובענין אחר \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 \u0003ערב תשעה באב,\u0004 בסעודה המפסקת, \u0003לא יאכל אדם שני תבשילין\u0004 יחד, \u0003ולא יאכל בשר\u0004 כלל \u0003ולא ישתה יין. ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 על כך: \u0003אבל אוכל הוא בשר מליח\u0004 שאינו קרוי בשר \u0003ושותה יין מגתו\u0004 קודם תסיסתו.","ושאלו: \u0003בשר מליח\u0004 \u0003עד כמה\u0004 קרוי הוא כן? \u0003אמר ר' חנינא בר כהנא: כל זמן שהוא\u0004 מלוח כדרך שמולחים את קרבן ה\u0003שלמים.\u0004 וקרבן שלמים נאכל לשני ימים ולילה, הרי שבשר מלוח הוא ביום השלישי.","\u0003ויין מגיתו עד כמה?\u0004 — \u0003כל זמן שהוא תוסס\u0004 עדיין. \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יין תוסס אין בו משום גילוי,\u0004 שאין חוששים שמא שתה ממנו נחש והטיל בו ארס, \u0003וכמה תסיסתו\u0004 — \u0003שלשה ימים.\u0004","לענין ערב תשעה באב היו לנו הגדרות מהו בשר מליח ויין מגיתו, \u0003הכא מאי\u0004 \u0005[כאן\u0006 בבן סורר ומורה \u0005מה\u0006\u0005]\u0006 קרוי \"בשר מליח\", ו\"יין מגיתו\"? ומשיבים: \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 בתשעה באב \u0003משום שמחה הוא\u0004 שאסור ו\u0003כל זמן שהוא כשלמים נמי אית ביה\u0004 \u0005[גם כן יש בו]\u0006 \u0003שמחה,\u0004 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בבן סורר ומורה — \u0003משום אימשוכי\u0004 \u0005[הימשכות]\u0006 \u0003הוא, ו\u0004על ידי פגם \u0003כל שהוא לא מימשיך\u0004 \u0005[נמשך\u0006\u0005],\u0006 שאם הבשר או היין אינם טעימים למדי, אין הדבר מוצא חן בעיניו, ואין חוששים שמא יבוא להמשך ולחטוא בכך. \u0003ויין\u0004 נקרא \"יין מגיתו\" לגבי העדר חשש ההמשכות אחריו \u0003עד ארבעים יום.\u0004","כיון שהוזכר ענין יין בהקשר זה, מדברים על יין בכלל. \u0003אמר רב חנן: לא נברא יין בעולם אלא לנחם אבלים,\u0004 לפכח צערם, \u0003ולשלם שכר לרשעים\u0004 שיהנו ממנו בעולם הזה, \u0003שנאמר: \"תנו שכר לאובד ויין למרי נפש\"\u0004 (משלי לא, ו), ה\"אובד\" הוא הרשע, ו\"מרי נפש\" הם האבלים.","\u0003אמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו\u0006 פירוש \u0005הנאמר\u0006\u0005]\u0006 \u0003\"אל תרא יין כי יתאדם\"\u0004 (שם כג, לא) — \u0003אל תרא יין שמאדים פניהם של רשעים בעולם הזה\u0004 בשעת שתיה \u0003ומלבין פניהם\u0004 (מביישם) \u0003לעולם הבא. רבא אמר,\u0004 כך יש לדרוש: \u0003\"אל תרא יין כי יתאדם\"\u0004 — \u0003אל תרא יין שאחריתו דם,\u0004 שהשותהו סופו שהוא הורג או נהרג על ידו.","\u0003רב כהנא רמי\u0004 \u0005[השליך,\u0006 הראה כעין סתירה\u0005],\u0006 בפסוק \"ונהרו אל טוב ה' על דגן ועל תירש ועל יצהר\" (ירמיה לא, יא), \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"תירש\" וקרינן\u0004 \u0005[וקוראים אנו\u0006\u0005]\u0006 ביין \u0003\"תירוש\"\u0004 וכך יש להסביר את שני האופנים: אם \u0003זכה\u0004 ושתהו כראוי — \u0003נעשה ראש, לא זכה\u0004 — \u0003נעשה רש.\u0004","\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה כעין סתירה\u0005]\u0006 בפסוק \"ויין ישמח לבב אנוש\" (תהלים קד, טו) \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ישמח\", וקרינן\u0004 \u0005[וקוראים אנו\u0006\u0005]\u0006 \u0003\"ישמח\".\u0004 וכך דורשים: אם \u0003זכה\u0004 אדם ושתהו כראוי — \u0003משמחו\u0004 היין, \u0003לא זכה\u0004 — \u0003משממהו,\u0004 כלומר, עושה אותו משוגע. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבא: חמרא וריחני פקחין\u0004 \u0005[יין\u0006","\u0003ו\u0004מיני \u0005בשמים עשו אותי פקח\u0006\u0005],\u0006 לומר שיש שתיית יין המועילה לבעליה. \u0003אמר רב עמרם בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בר אבא אמר ר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר\u0006\u0005]\u0006 \u0003\"למי אוי למי אבוי למי מדנים למי שיח למי פצעים חנם למי חכללות עינים. למאחרים על היין לבאים לחקר ממסך\"\u0004 (משלי כג, כט–ל). \u0003כי אתא\u0004 \u0005[כאשר בא\u0006\u0005]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל\u0006\u0005],\u0006 \u0003האי קרא, מאן דדריש ליה מרישיה לסיפיה\u0004 \u0005[פסוק זה, מי שדורש אותו מראשו לסופו]\u0006 — הרי הוא \u0003מדריש\u0004 \u0005[נדרש\u0006\u0005],\u0006 שיש לו מובן ומשמעות, \u0003ו\u0004מי שדורש אותו \u0003מסיפיה לרישיה\u0004 \u0005[מסופו לתחילתו]\u0006 — הרי הוא \u0003מדריש\u0004 \u0005[נדרש\u0006\u0005]\u0006 גם כן. שאפשר לומר שאוי ואבוי למי ששותה יין, וכן מסופו לראשו: מי הוא זה השותה יין — מי שיש לו צרות פצעים ומדנים.","\u0003דריש\u0004 \u0005[דרש]\u0006 \u0003עובר\u0004 אורח \u0003גלילאה\u0004 \u0005[מן הגליל\u0006\u0005]:\u0006 \u0003שלש עשרה ווי\"ן נאמרו ביין,\u0004 שנאמר: \u0003\"ויחל נח איש האדמה ויטע כרם. וישת מן היין וישכר ויתגל בתוך אהלה. וירא חם אבי כנען את ערות אביו ויגד לשני אחיו בחוץ. ויקח שם ויפת את השמלה וישימו על שכם שניהם וילכו אחרנית ויכסו את ערות אביהם ופניהם אחרנית\u0004 וערות אביהם לא ראו. \u0003וייקץ נח מיינו וידע את אשר עשה לו בנו הקטן\".\u0004 (בראשית ט, כ–כד) וכל אלה לשון \"וי\" = אוי ואבוי הם. כיון שהובא פסוק זה דנים מה עשה לו באמת בנו הקטן.","\u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: סרסו,\u0004 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003רבעו\u0004 במשכב זכור.","ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ש\u0003סרסו,\u0004 מביא ראיה זו: \u0003מתוך שקלקלו\u0004 לנח בבנו ה\u0003רביעי,\u0004 שרצה להוליד עוד בן ולא יכול, לכן \u0003קללו ב\u0004בנו ה\u0003רביעי,\u0004 שבני חם היו כוש ומצרים ופוט וכנען (שם י, ו), ומכולם נתקלל כנען (\"ארור כנען עבד עבדים יהיה לאחיו... ויהי כנען עבד למו\" וכו' שם ט, כה–כח). \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 ש\u0003רבעו, גמר\u0004 \u0005[למד\u0006\u0005]\u0006 בגזירה שווה מן המילים \u0003\"וירא\" \"וירא\"; כתיב הכא\u0004 \u0005[נאמר כאן ]\u0006 \u0003\"וירא חם אבי כנען את ערות אביו\", וכתיב התם\u0004 \u0005[ונאמר שם\u0006\u0005]\u0006 \u0003\"וירא אותה שכם בן חמור\u0004 החיוי נשיא הארץ ויקח אותה וישכב אותה ויענה\u0003\"\u0004 (שם לד, ב), מכאן ש\"ראיה\" זו ענין ביאה הוא.","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר\u0006\u0005]\u0006 ש\u0003סרסו, משום הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003קללו\u0004 \u0003ב\u0004בנו ה\u0003רביעי. אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006\u0005]\u0006 ש\u0003רבעו מאי שנא\u0004 \u0005[במה שונה\u0006\u0005]\u0006 שקללו בבנו ה\u0003רביעי? נלטייה בהדיא\u0004 \u0005[שיקלל אותו במישרין\u0006\u0005]!\u0006 ומשיבים: \u0003הא והא הואי\u0004 \u0005[זה וזה היה],\u0006 כלומר, לדעת הכל סרסו, ויש אומרים שגם רבעו.","באותו ענין נאמר: \u0003\"ויחל נח איש האדמה ויטע כרם\"\u0004 (שם ט, כ), וכביאור לענין \u0003אמר רב חסדא אמר רב עוקבא, ואמרי לה\u0004 \u0005[ויש אומרים\u0006\u0005]\u0006 שאמר זאת \u0003מר עוקבא אמר\u0004 (בשם) \u0003ר' זכאי: אמר לו הקדוש ברוך הוא לנח: נח, לא היה לך ללמד מאדם הראשון\u0004 (איש האדמה = שנוצר מאדמה (מהרש\"א), \u0003שלא גרם דלו\u0004 לגרושו מגן עדן \u0003אלא\u0004 ה\u0003יין?\u0004 ומעירים: דבר זה \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אותו אילן שאכל ממנו אדם הראשון גפן היה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא \u0005],\u0006 \u0003ר' מאיר אומר: אותו אילן שאכל אדם הראשון ממנו גפן היה\u0004"],["\u0003שאין לך דבר שמביא יללה\u0004 (בכיה) \u0003לאדם אלא יין\u0004 אפילו בזמן הזה, ומסתבר שהוא שגרם לכך מימות בראשית. \u0003ר' יהודה אומר:\u0004 עץ הדעת \u0003חטה היה,\u0004 וראיה לדבר — \u0003שאין התינוק יודע לקרוא אבא ואימא עד שיטעום טעם דגן,\u0004 ומשום כך קרוי הוא \"עץ הדעת\". \u0003ר' נחמיה אומר:\u0004 עץ הדעת \u0003תאנה היה,\u0004 ורמז לדבר — \u0003שבדבר שקלקלו בו נתקנו, שנאמר: \"ויתפרו עלה תאנה\"\u0004 (בראשית ג, ז).","ועוד בענין יין: על הנאמר \u0003\"דברי למואל מלך משא אשר יסרתו אמו\"\u0004 (משלי לא, א), \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מלמד\u0004 שכשראתה בת שבע ששלמה מרבה בשתיה \u0003כפאתו\u0004 (קשרה אותו) \u0003אמו על העמוד\u0004 להכותו. \u0003ואמרה לו: \"מה ברי ומה בר בטני ומה בר נדרי\"\u0004 (משלי לא ב). וכך מפרשים: \u0003\"מה ברי\"\u0004 (בני) — \u0003הכל יודעים שאביך ירא שמים הוה\u0004 \u0005[היה\u0006\u0005],\u0006 ו\u0003עכשיו\u0004 שרואים אותך חוטא \u0003יאמרו\u0004 הכל: \u0003אמו גרמה לו\u0004 שהוא רק בן אמו (ברי) לפי אופיו.","\u0003\"ומה בר בטני\"\u0004 — לומר: \u0003כל הנשים של בית אביך כיון שמתעברות שוב אינן רואות פני המלך, ואני דחקתי ונכנסתי\u0004 בזמן הריוני, \u0003כדי שיהא לי בן מזורז ומלובן,\u0004 שאמרו שבזמנים מסויימים בשעת ההריון יפה ביאה לולד ועושה אותו מוצלח יותר.","\u0003\"ומה בר נדרי\"\u0004 — ש\u0003כל נשים של בית אביך היו נודרות\u0004 בזמן הריונן ש\u0003יהא לי בן הגון למלכות, ואני\u0004 בניגוד להן \u0003נדרתי ואמרתי\u0004 ש\u0003יהא לי בן זריז וממולא בתורה והגון לנביאות.\u0004","עוד נאמר שם: \u0003\"אל למלכים למואל אל למלכים שתו יין\"\u0004 (משלי לא ד), וכוונת הדברים: \u0003\"אל למלכים\"\u0004 — \u0003אמרה לו: מה לך אצל מלכים\u0004 של אומות העולם \u0003ששותים יין ומשתכרים ואומרים: למה לנו אל\u0004 (\"למואל\")? \u0003\"ולרוזנים אי שכר\"\u0004 (משלי לא ד) — \u0003מי שכל רזי עולם גלויים לו\u0004 כשלמה \u0003ישתה יין וישתכר? איכא דאמרי\u0004 \u0005[יש אומרים\u0006\u0005]\u0006 שכך יש להבין: \u0003מי שכל רוזני עולם משכימין לפתחו ישתה יין וישתכר?\u0004","\u0003אמר ר' יצחק: מניין שחזר שלמה והודה לאמו\u0004 שהיא צודקת בתוכחתה? — \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"כי בער אנכי מאיש ולא בינת אדם לי\"\u0004 (שם ל, ב), וכוונת דבריו: \u0003\"כי בער אנכי מאיש\"\u0004 — \u0003מנח,\u0004 שחטא ביין והוא קרוי \"איש\" \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"ויחל נח איש האדמה\"\u0004 (בראשית ט, כ), \u0003\"ולא בינת אדם לי\"\u0004 — \u0003זה אדם הראשון\u0004 שאף הוא חטא ביין, כדעת ר' מאיר שעץ הדעת היה גפן.","שנינו במשנה שאם \u0003אכל\u0004 הבן בשר ושתה יין כדי שיעור המחייבו כדין בן סורר ומורה, ואולם היה זה \u0003בחבורת מצוה\u0004 — אינו מתחייב כבן סורר ומורה. \u0003אמר ר' אבהו: אינו חייב עד שיאכל בחבורה שכולה סריקין\u0004 (ריקנים), ומשמע שאם אכל בחברת אנשים הגונים, אף אם אכל כשיעור אינו נעשה בן סורר ומורה.","ושואלים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 שאם \u0003אכל בחבורת מצוה אינו נעשה בן סורר ומורה,\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שאכל בחבורת \u0003מצוה, הא לאו\u0004 \u0005[הרי\u0006 אם \u0005לא\u0006\u0005]\u0006 בחבורת \u0003מצוה\u0004 היתה סעודה זו, \u0003אף על גב דלאו\u0004 \u0005[אף על פי שלא]\u0006 כל בני החבורה \u0003כולה\u0004 אנשים \u0003סריקין\u0004 — חייב! ומשיבים: אין סתירה מהמשנה לדברי ר' אבהו, ובאמת מתחייב רק אם יאכל בחבורת ריקנים, ובמשנה \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שכל החבורה \u0003כולה\u0004 אנשים \u0003סריקין,\u0004 \u0003כיון\u0004 ש\u0003במצוה קא עסיק\u0004 \u0005[הוא עוסק]\u0006 — \u0003לא מימשיך\u0004 \u0005[אינו נמשך\u0006 בתאוותו\u0005].\u0006","עוד שנינו במשנה שאם \u0003אכל בעיבור החודש\u0004 — אינו בכלל בן סורר ומורה. ותוהים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003בשר ויין מסקו\u0004 \u0005[מעלים]\u0006 לעליית הגג שבה דנים בעיבור החודש? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין עולין לה\u0004 לעליה זו בעת עיבור החודש, \u0003אלא בפת דגן וקטנית בלבד!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה\u0006 עצמו \u0005השמיע לנו\u0006\u0005]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אין עולין לה\u0004 לעלייה זו \u0003אלא בפת וקטנית, ואיהו אסיק\u0004 \u0005[והוא העלה\u0006\u0005]\u0006 \u0003בשר ויין ואכל, כיון\u0004 ש\u0003במצוה קא עסיק\u0004 \u0005[הוא עוסק]\u0006 — \u0003לא מימשיך\u0004 \u0005[אינו נמשך\u0006 בתאוותו\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]\u0006 בענין זה: \u0003אין עולין\u0004 לעלייה בה עוסקים \u0003בעיבור החודש פחות מעשרה בני אדם, ואין עולין לה אלא בפת דגן וקטנית, ואין עולין לה אלא לאור עיבורו\u0004 (בלילה שבו צריך החודש להתעבר), \u0003ואין עולין לה ביום אלא בלילה.\u0004 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת ש\u0003אין עולין לה בלילה אלא ביום!\u0004 ומסבירים: \u0003כדאמר\u0004 \u0005[כפי שאמר\u0006\u0005]\u0006 \u0003ר' חייא בר אבא לבניה\u0004 \u0005[לבניו\u0006\u0005]:\u0006 \u0003אחריפו ועולו אחריפו ופוקו\u0004 \u0005[הקדימו והכנסו, הקדימו וצאו\u0006\u0005]\u0006 בזמן שאתם באים לדון בעיבור החודש. \u0003כי היכי דלישמעו בכו אינשי\u0004 \u0005[כדי שישמעו בכם בני אדם\u0006\u0005]\u0006 שאתם באים ויהא זה סימן להם שדנים בענין זה. ואם כן השעות הראויות לכך הן שעות השחר בין היום והלילה.","שנינו במשנה שאם \u0003אכל\u0004 הבן \u0003מעשר שני בירושלים\u0004 — אינו בכלל בן סורר ומורה. ומסבירים: \u0003כיון דכי אורחיה\u0004 \u0005[שכדרכו]\u0006 \u0003הוא קא אכיל ליה\u0004 \u0005[אוכל אותו]\u0006 שכך היא מצוותו, הריהו \u0003לא ממשיך\u0004 \u0005[נמשך אחריו\u0006\u0005].\u0006","עוד שנינו במשנה שאם \u0003אכל נבילות וטריפות שקצים ורמשים\u0004 אינו חייב. \u0003אמר רבא:\u0004 אם \u0003אכל\u0004 הבן \u0003בשר עוף,\u0004 אף אם אכל כשיעור — \u0003אינו נעשה\u0004 בכך \u0003בן סורר ומורה.\u0004","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 שאם \u0003אכל נבילות וטריפות שקצים ורמשים אינו נעשה בן סורר ומורה,\u0004 ודייק: \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם אכל \u0003טהורין\u0004 ואפילו בשר עוף \u0003נעשה בן סורר ומורה,\u0004 ובניגוד לדברי רבא! ומשיבים: \u0003כי תנן נמי מתניתין\u0004 \u0005[כאשר שנויה גם כן משנתנו],\u0006 הרי זה לענין \u0003להשלים\u0004 לשיעור הבשר, אבל עיקר אכילה צריכה להיות בבשר בהמה דווקא כפי שאמר רבא.","שנינו במשנה שאם \u0003אכל דבר שהוא מצוה ודבר עבירה\u0004 — אינו בכלל בן סורר ומורה. ומסבירים: כלל זה בענין \u0003דבר מצוה\u0004 בא להוסיף מצוות שמדברי חכמים כגון \u0003תנחומי אבלים. דבר עבירה\u0004 — כגון שאכל ב\u0003תענית ציבור.\u0004","ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומה הטעם]\u0006 שהעושה כן אינו קרוי זולל וסובא? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004בננו זה... \u0003איננו שמע בקלנו\"\u0004 (דברים כא, כ), ומשמע: \u0003בקולנו\u0004 אינו שומע, \u0003ולא\u0004 שאינו שומע גם \u0003בקולו של מקום\u0004 (הקדוש ברוך הוא). ואם עובר על דבר תורה הרי אינו שומע גם לקולו של מקום.","עוד שנינו במשנה שאם \u0003אכל כל מאכל ולא אכל בשר, שתה כל משקה ולא שתה יין\u0004 — אינו בכלל זולל וסובא. ומסבירים: מה ששנינו \u0003\"אכל כל מאכל ולא אכל בשר\"\u0004 הרי זה \u0003לאיתויי\u0004 \u0005[להביא\u0006\u0005]\u0006 \u0003דבילה קעילית\u0004 (תאנה מיובשת מן המקום קעילה) שהוא משביע כבשר אך אין חייבים עליו. \u0003שתה כל משקה ולא שתה יין, לאיתויי\u0004 \u0005[להביא\u0006\u0005]\u0006 \u0003דבש וחלב\u0004 שאף שהם משכרים מעט אין חייבים על שתייתם. ומנין שהם משכרים?","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003אכל דבילה קעילית\u0004 שהיא מתוקה מאוד ומשכרת, \u0003ושתה דבש וחלב, ונכנס למקדש\u0004"],["— \u0003חייב\u0004 משום כניסה למקדש כשהוא שתוי.","שנינו במשנה ש\u0003אינו נעשה בן סורר ומורה עד שיאכל בשר וישתה יין. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אכל כל מאכל ולא אכל בשר, שתה כל משקה ולא שתה יין\u0004 — \u0003אינו נעשה בן סורר ומורה, עד שיאכל בשר וישתה יין, שנאמר: \"זולל וסבא\",\u0004 ולשון \"זלילה\" ו\"סביאה\" שייכים באכילת בשר ושתיית יין.","\u0003ואף על פי שאין ראייה לדבר,\u0004 להלכה זו, הרי יש \u0003זכר לדבר, שנאמר: \"אל תהי בסבאי יין בזללי בשר למו\"\u0004 (משלי כג, כ), \u0003ואומר: \"כי סבא וזולל יורש וקרעים תלביש נומה\"\u0004 (שם כא), כלומר, אדם שזולל וסובא והשינה המרובה (בגלל האכילה והשתיה) תביאנו להיות לבוש, בסופו של דבר יהא עני ורש, ולבוש קרעים. מאותו פסוק דרש ו\u0003אמר\u0004 \u0003ר' זירא: כל הישן בבית המדרש תורתו נעשית לו קרעים קרעים\u0004 שאינו זוכר הלכה שלימה וגמורה, \u0003שנאמר: \"וקרעים תלביש נומה\".\u0004","\u0003גנב משל אביו ואכל ברשות אביו,\u0004 או גנב \u0003משל אחרים ואכל ברשות אחרים,\u0004 או גנב \u0003משל אחרים ואכל ברשות אביו\u0004 — \u0003אינו נעשה בן סורר ומורה עד שיגנוב\u0004 דבר \u0003משל אביו ויאכל ברשות אחרים. ר' יוסי בר' יהודה אומר:\u0004 אינו נעשה בן סורר ומורה \u0003עד שיגנוב מ\u0004רכוש \u0003של אביו\u0004 \u0003ומשל אמו\u0004 כאחד.","את הדינים במשנה מבארים: אם \u0003גנב משל אביו ואכל ברשות אביו\u0004 אינו נמשך כל כך אחר הדבר, כי \u0003אף על גב דשכיח ליה\u0004 \u0005[אף על פי שמצוי לו\u0006 וקל לגנוב\u0005]\u0006 משל הוריו, מכל מקום הריהו \u0003בעית\u0004 \u0005[מפחד\u0006\u0005],\u0006 שחושש שאביו יראהו אוכל מה שגנב.","\u0003משל אחרים ואכל ברשות אחרים\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שהוא \u0003לא בעית\u0004 \u0005[מפחד\u0006\u0005]\u0006 מהם, שהרי אינם יודעים ואינם משגיחים עליו, ואולם \u0003לא שכיח ליה\u0004 \u0005[מצוי לו\u0006\u0005]\u0006 שיגנוב בקלות, \u0003וכל שכן\u0004 אם גנב \u0003משל אחרים ואכל ברשות אביו,\u0004 שגם \u0003לא שכיח ליה\u0004 \u0005[מצוי לו],\u0006 \u0003ובעית\u0004 \u0005[ו\u0006גם \u0005מפחד\u0006 מאביו\u0005].\u0006","ואינו חייב \u0003עד שיגנוב משל אביו ויאכל ברשות אחרים,\u0004 שדבר זה גם \u0003שכיח ליה\u0004 \u0005[מצוי לו],\u0006 \u0003ו\u0004גם הוא \u0003לא בעית\u0004 \u0005[מפחד\u0006\u0005],\u0006 ועשוי להימשך אחר הדבר.","שנינו במשנה ש\u0003ר' יוסי בר' יהודה אומר\u0004 שאינו חייב כבן סורר ומורה \u0003עד שיגנוב משל אביו ומשל אמו,\u0004 ותוהים: \u0003אמו מנא\u0004 \u0005[מנין]\u0006 \u0003לה\u0004 רכוש עצמאי שיוכל הבן לגנוב משלה? והרי כלל הוא שכל \u0003מה שקנתה אשה קנה בעלה! אמר ר' יוסי בר' חנינא:\u0004 הכוונה היא שגנב \u0003מסעודה המוכנת לאביו ולאמו,\u0004 שבסעודה זו הרי האב מקנה לאמו את מה שהיא אוכלת.","על הסבר זה מקשים: \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003רב חנן בר מולדה אמר רב הונא: אינו חייב עד שיקנה בשר בזול ויאכל, יין בזול וישתה,\u0004 משמע שמתחייב רק כאשר גונב כסף ולא את הדבר עצמו! \u0003אלא אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 שגונב \u0003מדמי סעודה המוכנת לאביו ולאמו.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]\u0006 הסבר אחר: \u0003דאקני\u0004 \u0005[שהקנה]\u0006 \u0003לה\u0004 לאם רכוש זה אדם \u0003אחר\u0004 \u0003ואמר לה: \"על מנת שאין לבעליך רשות בהן\",\u0004 שבדרך זו אשה קונה רכוש לעצמה ואין לבעל רשות בו. ואם כן יש אפשרות שיגנוב מרכוש אמו.","\u0003היה אביו רוצה\u0004 שיומת \u0003ואמו אינה רוצה,\u0004 או \u0003אביו אינו רוצה ואמו רוצה\u0004 — \u0003אינו נעשה בן סורר ומורה עד שיהו שניהם רוצין. ר' יהודה אומר: אם לא היתה אמו ראויה לאביו\u0004 משום שיש חוסר התאמה ביניהם (כמבואר בגמרא) — \u0003אינו נעשה בן סורר ומורה.\u0004","על דברי ר' יהודה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינה ראויה\u0004 לאביו \u0003\"?\u0004 \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 שהיתה אמו לגבי אביו \u0003חייבי כריתות,\u0004 ואף שאין קידושין תופסים בהם, ובוודאי אם היתה אמו לגבי אביו \u0003חייבי מיתות בית דין\u0004 שקידושין תופסים בהם, ואולם גם אז \u0003סוף סוף אבוה\u0004 \u0005[אביו]\u0006 — \u0003אבוה נינהו\u0004 \u0005[אביו הוא],\u0006 \u0003ואמיה\u0004 \u0005[ואמו]\u0006 — \u0003אמיה נינהו\u0004 \u0005[אמו היא\u0006\u0005]\u0006 ומתקיימים בהם דברי הכתוב בענין בן סורר ומורה!","\u0003אלא\u0004 הכוונה \u0003\"בשוה לאביו\" קאמר\u0004 \u0005[אמר\u0006\u0005],\u0006 שצריך שתהא אמו שוה לאביו בכל דבר. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך\u0006\u0005],\u0006 \u0003ר' יהודה אומר: אם לא היתה אמו שוה לאביו בקול ובמראה ובקומה, אינו נעשה בן סורר ומורה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 כיצד מוכיח זאת ר' יהודה? — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"איננו שמע בקלנו\"\u0004 (דברים כא, כ), משמע שיש קול אחיד לשניהם, ו\u0003מ\u0004כיון שלענין \u0003קול בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003שוין,\u0004 אם כן לענין \u0003מראה וקומה נמי בעינן\u0004 \u0005[גם כן צריכים אנו]\u0006 שיהיו \u0003שוין.\u0004","ומעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו\u0006\u0005]\u0006 \u0003בן סורר ומורה לא היה ולא עתיד להיות,\u0004 שלמעשה לא יתכן שיתקיימו הדרישות הנחוצות כדי שיתממש דין זה, \u0003ולמה נכתב\u0004 בתורה? — כדי ל\u0003דרוש\u0004 ול\u0003קבל שכר\u0004 בלימוד זה, שהוא אחד מדברי תורה שיש להם ערך עיוני בלבד. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 — כשיטת \u0003ר' יהודה\u0004 הדורש שוויון גמור בין ההורים. והרי קשה מאד למצוא שיהיו הורים הדומים זה לזה עד כדי כך.","ודוחים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]\u0006 שאותה ברייתא כשיטת \u0003ר' שמעון היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון: וכי מפני שאכל זה תרטימר בשר ושתה חצי לוג יין האיטלקי, אביו ואמו מוציאין אותו לסקלו?\u0004 הלא אין הדבר אפשרי מבחינה נפשית! \u0003אלא לא היה ולא עתיד להיות, ולמה נכתב\u0004 בתורה — משום \u0003דרוש וקבל שכר. אמר ר' יונתן:\u0004 אין זה כך, אלא \u0003אני ראיתיו,\u0004 שהייתי במקום שנידון בו בן סורר ומורה \u0003ו\u0004אף \u0003ישבתי על קברו\u0004 לאחר שנידון והרגוהו.","כיוצא בזה שואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו]:\u0006 \u0003עיר הנדחת לא היתה ולא עתידה להיות, ולמה נכתבה?\u0004 — משום \u0003דרוש וקבל שכר. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — כשיטת \u0003ר' אליעזר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל עיר שיש בה אפילו מזוזה אחת\u0004 או שאר ספרי קודש — \u0003אינה נעשית עיר הנדחת.\u0004 וקשה לשער שתהיה עיר שלימה שאפילו מזוזה אחת אין בה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של ר' אליעזר שעיר כזו אינה נעשית עיר הנדחת? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואת כל שללה תקבץ אל תוך רחבה ושרפת באש\u0004 את העיר ואת כל שללה\u0003\"\u0004 (שם יג, יז) \u0003וכיון דאי איכא\u0004 \u0005[שאם יש\u0006\u0005]\u0006 \u0003מזוזה\u0004 שם \u0003לא אפשר\u0004 לשרוף הכל, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006\u0005]:\u0006 \u0003\"\u0004ונתצתם את מזבחותם... ואשריהם תשרפון באש... \u0003לא תעשון כן לה' אלהיכם\"\u0004 (שם יב, ג–ד), ומכאן למדו שאסור לשרוף דבר המקודש לה', ולכן עיר כזו שיש בה ואפילו מזוזה אחת אי אפשר לקיים בה דין עיר הנדחת. \u0003אמר ר' יונתן:\u0004 אינו כן, אלא \u0003אני ראיתיה\u0004 שדנוה \u0003וישבתי על תילה.\u0004","ועוד הערה דומה: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו\u0006\u0005]\u0006 \u0003בית המנוגע\u0004 בצרעת \u0003לא היה ולא עתיד להיות. ולמה נכתב\u0004 בתורה — משום \u0003דרוש וקבל שכר. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006\u0005]?\u0006 — כשיטת \u0003ר' אלעזר בר' שמעון. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אלעזר בר' שמעון אומר: לעולם אין הבית טמא\u0004 בנגע צרעת \u0003עד שיראה\u0004 הנגע בגודל \u0003שתי גריסין על שתי אבנים בשתי כתלים בקרן זוית\u0004 שביניהם \u0003ארכו כשני גריסין ורחבו כגריס.\u0004 וקשה לשער שיקרה בדיוק כך.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם ]\u0006 של \u0003ר' אלעזר בר' שמעון\u0004 שכך הוא דורש? — \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 בתורה \u0003\"קיר\", וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק גם \u0003\"קירת\"\u0004 (\"וראה את הנגע בקירות הבית שקערורות ירקרקות או אדמדמות ומראיהן שפל מן הקיר\". ויקרא יד, לז), \u0003איזהו קיר שהוא כקירות\u0004 — \u0003הוי אומר זה קרן זוית.\u0004","\u0003תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אליעזר בר' צדוק: מקום היה בתחום עזה והיו קורין אותו \"חורבתא סגירתא\"\u0004 \u0005[\"חורבה מצורעת\"],\u0006 כלומר, מקום שהיה בו בית המנוגע ומשמע שהיה במציאות בית מנוגע. \u0003אמר ר' שמעון איש כפר עכו: פעם אחת הלכתי לגליל וראיתי מקום שמציינין אותו\u0004 כמקום טמא \u0003ואמרו: אבנים מנוגעות\u0004 מבית המנוגע בנגע צרעת \u0003פינו לשם,\u0004 הרי שהיה במציאות בית המנוגע.","\u0003היה אחד מהם,\u0004 מן ההורים, \u0003גידם או חיגר או אלם או סומא או חרש\u0004 — בנם \u0003אינו נעשה בן סורר ומורה, שנאמר:\u0004 \"ותפשו בו אביו ואמו והוציאו אתו אל זקני עירו ואל שער מקומו\" (דברים כא, יט), \u0003\"ותפשו בו אביו ואמו\",\u0004 משמע — \u0003ולא גדמין,\u0004 שאינם יכולים לתפוס, \u0003\"והוציאו אתו\"\u0004 — \u0003ולא חגרין,\u0004 שאינם יכולים ללכת. ועוד נאמר: \"ואמרו אל זקני עירו בננו זה סורר ומורה איננו שומע בקולנו זולל וסובא\" (שם כ) \u0003\"ואמרו\"\u0004 — \u0003ולא אלמין, \"בננו זה\"\u0004 — \u0003ולא סומין,\u0004 שאינם יכולים להראות ולומר \"זה\", \u0003\"איננו שמע בקלנו\"\u0004 — \u0003ולא חרשין,\u0004 שאינם שומעים אם קיבל את דבריהם.","לאחר שמביאים אותו כך אל זקני העיר \u0003מתרין בו בפני שלשה ומלקין אותו\u0004 על שגנב. אם \u0003חזר וקלקל\u0004 (חטא) — \u0003נדון בעשרים ושלשה\u0004 דיינים, \u0003ואינו נסקל עד שיהו שם שלשה הראשונים\u0004 שלקה בפניהם, \u0003שנאמר: \"בננו זה\"\u0004 — \u0003זהו\u0004 הבן \u0003שלקה\u0004 כבר פעם אחת \u0003בפניכם.\u0004","ממשמעות דברי המשנה רוצים לדקדק: \u0003שמעת מינה\u0004 \u0005[לומד אתה ממנה\u0006\u0005],\u0006 ממשנתנו זו, כי \u0003בעינן קרא כדכתיב\u0004 \u0005[צריכים אנו\u0006 לקיים את דברי \u0005הכתוב כפי שנאמר\u0006\u0005]\u0006 בדיוק לשונו המצומצם, ולא כפי שאפשר להבין בדרך רחבה יותר שהרי כאן מקפידים על קיומה של כל מלה כאמור! ודוחים: אין מכאן ראיה, שכן \u0003שאני הכא\u0004 \u0005[שונה כאן\u0006\u0005]\u0006 שהוא מקרה מיוחד,"],["\u0003דכוליה קרא יתירא\u0004 \u0005[שכל הכתוב\u0006 הזה \u0005מיותר]\u0006 \u0003הוא,\u0004 שתיאור זה כיצד מוציאים אותו אביו ואמו אינו נחוץ לכאורה, ומשום כך אומרים אנו שבא להדגיש שיש לעשות את הדבר רק באופן זה ולא באופן אחר.","שנינו במשנה ש\u0003מתרין\u0004 בו \u0003בפני שלשה.\u0004 ושואלים: \u0003למה לי\u0004 שתהיה ההתראה בפני שלושה? \u0003בתרי סגיא\u0004 \u0005[בשני\u0006 עדים \u0005די]\u0006 כבשאר דינים! \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר\u0006\u0005],\u0006 כך יש להבין: \u0003מתרין בו בפני שנים ומלקין אותו בפני שלשה\u0004 שהם בית דין.","ושואלים: \u0003מלקות בבן סורר ומורה היכא כתיבא\u0004 \u0005[היכן כתוב\u0006\u0005]?\u0006 הרי לא נאמר הדבר במפורש בכתוב! ומשיבים: כפי שדרש \u0003ר' אבהו\u0004 לענין אחר, ש\u0003אמר ר' אבהו: למדנו\u0004 את משמעות \"ולקחו זקני העיר ההיא את האיש \u0003ויסרו\u0004 אותו\" (דברים כב, יח) האמור במוציא שם רע, \u0003מ\"ויסרו\u0004 אותו ולא ישמע אליהם\u0003\"\u0004 (שם כא, יח) האמור בבן סורר ומורה, \u0003\"ויסרו\"\u0004 זה למדים ממה שנאמר בו \u0003מ\"בן\"\u0004 האמור בפרשת בן סורר ומורה (\"כי יהיה לאיש בן סורר ומורה איננו שומע בקול אביו ואמו ויסרו אותו\". שם), \u0003ו\"בן\"\u0004 זה נלמד ומושווה \u0003מ\"בן\"\u0004 המוזכר במלקות, שנאמר \u0003\"והיה אם בן הכות הרשע\"\u0004 (שם כה, ב), ללמדנו ש\"ויסרו\" האמור בשני מקומות אלה משמעו עונש מלקות.","שנינו במשנה שאם \u0003חזר וקלקל\u0004 (חטא) — הריהו \u0003נידון בעשרים ושלשה\u0004 דיינים וחייבים להיות ביניהם שלושת הראשונים שנידון כבר בפניהם, שכן נאמר: \"בננו זה\". ומקשים: והרי \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו\u0006\u0005]\u0006 לענין אחר ללמדנו \u0003\"זה\"\u0004 — \u0003ולא\u0004 הורים \u0003סומין\u0004 שאינם יכולים להראות ולומר \"זה\" (לעיל סנהדרין עא, א)! ומשיבים: \u0003אם כן\u0004 שביטוי זה בא רק ללמדנו שצריכים להיות שם הדיינים הראשונים \u0003לכתוב\u0004 \u0005[שיכתוב\u0006 בתורה\u0005]\u0006 רק \"\u0003בננו הוא\", מאי\u0004 \u0005[מה\u0006 השוני\u0005]\u0006 באומרו \u0003\"בננו זה\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 ששלושת דייניו צריכים להיות בדינו השני, וגם ללמדנו שאם הוריו סומים אינו נעשה בן סורר ומורה.","\u0003ברח\u0004 בן סורר ומורה \u0003עד שלא נגמר דינו, ואחר כך,\u0004 לפני שתפסוהו, \u0003הקיף זקן התחתון\u0004 — \u0003פטור\u0004 ממיתה, שהרי משהקיף זקן התחתון שוב אינו נידון כבן סורר ומורה (ראה לעיל סנהדרין סח, ב). \u0003ו\u0004אולם \u0003אם משנגמר דינו ברח\u0004 מבית הדין \u0003ואחר כך\u0004 כשתפסוהו כבר \u0003הקיף זקן התחתון\u0004 — \u0003חייב,\u0004 שכיון שיצא כבר דינו למיתה, אין חוזרים ומזכים אותו.","בקשר לרעיון במשנתנו \u0003אמר ר' חנינא: בן נח שבירך\u0004 (קילל) \u0003את השם, ואחר כך נתגייר\u0004 — \u0003פטור\u0004 מעונש, \u0003הואיל ונשתנה דינו,\u0004 שעכשיו בהיותו ישראל נידון על אותה עבירה עצמה בפני עשרים ושלושה בהתראה ובפני עדים, וגם \u0003נשתנה מיתתו,\u0004 שמקודם היה נידון כבן נח בסייף, ועכשיו בסקילה.","ומציעים: \u0003נימא מסייעא ליה\u0004 \u0005[האם נאמר\u0006 ש\u0005מסייע לו\u0006\u0005]\u0006 מה ששנינו במשנתנו: \u0003ברח עד שלא נגמר דינו ואחר כך הקיף זקן התחתון\u0004 — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003הואיל ואישתני\u0004 \u0005[ונשתנה]\u0006 מעמדו — \u0003אישתני\u0004 \u0005[נשתנה\u0006 דינו\u0005]?!\u0006","ודוחים: \u0003לא, שאני הכא, דאי עבד השתא\u0004 \u0005[שונה כאן\u0006 בבן סורר, \u0005כי אם היה עושה עכשיו]\u0006 אותם מעשים, הרי \u0003לאו בר קטלא\u0004 \u0005[לא בן מוות\u0006\u0005]\u0006 \u0003הוא,\u0004 ולכן פטור. מה שאין כן בגוי שקילל את השם, שעבירה זו חייב עליה מיתה גם בהיותו ישראל.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לסתור ממה ששנינו במשתנו: \u0003אם משנגמר דינו ברח ואחר כך הקיף זקן התחתון\u0004 — \u0003חייב.\u0004 משמע שאף שנשתנה דינו, בכל זאת הורגים אותו! ודוחים: מכאן אין ראיה, \u0003נגמר דינו קאמרת\u0004 \u0005[אמרת\u0006\u0005],\u0006 \u0003נגמר דינו\u0004 בבחינת \u0003גברא קטילא\u0004 \u0005[אדם הרוג]\u0006 \u0003הוא,\u0004 ושוב אין נושאים ונותנים עוד בדינו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003בן נח שהכה\u0004 (הרג) \u0003את חבירו\u0004 הגוי, או ש\u0003בא על אשת חבירו\u0004 הגוי, \u0003ונתגייר\u0004 — \u0003פטור,\u0004 ואם \u0003עשה כן בישראל,\u0004 שהרג אדם מישראל או בא על אשת ישראל \u0003ונתגייר\u0004 — \u0003חייב. ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 תאמר כך? \u0003נימא\u0004 \u0005[נאמר\u0006\u0005]\u0006 \u0003הואיל ואישתני\u0004 \u0005[ונשתנה]\u0006 — \u0003אישתני\u0004 \u0005[נשתנה\u0006\u0005]\u0006 ואינו חייב מיתה עוד! אלא משמע שאין סוברים כך.","ודוחים: אין להשוות! כי \u0003דינו ומיתתו בעינן\u0004 \u0005[צריכים אנו\u0006\u0005],\u0006 שכדי שיבטל חיוב מיתה מעליו דרוש גם שינוי בדרך דינו וגם בדרך מיתתו, \u0003והאי\u0004 \u0005[וזה\u0006\u0005]\u0006 שהרג או שבא על אשת חבירו אמנם \u0003דינו אישתני\u0004 \u0005[השתנה\u0006\u0005],\u0006 שכן משנתגייר נידון בעשרים ושלושה דיינים בעדים ובהתראה, ואולם \u0003מיתתו לא אישתני\u0004 \u0005[נשתנתה\u0006\u0005],\u0006 שעדיין הוא נהרג באותה מיתה, ולכך אינו נפטר.","ומקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 לגבי \u0003רוצח\u0004 מובנת התשובה, שכן \u0003מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 כשהיה בן נח היה נידון ב\u0003סייף, והשתא\u0004 \u0005[ועכשיו\u0006\u0005]\u0006 שהוא ישראל נידון גם כן ב\u0003סייף,\u0004 ואין איפוא שינוי במיתתו. \u0003אלא\u0004 הבא על \u0003אשת איש,\u0004 הלא כשהיה \u0003מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 בן נח היה נידון ב\u0003סייף,\u0004 שאין עונשי בן נח אלא בסייף, \u0003והשתא\u0004 \u0005[ועכשיו\u0006\u0005]\u0006 שהוא ישראל הריהו נידון ב\u0003חנק!\u0004 ואם כן יש שינוי הן בדינו והן במיתתו ועל כל פנים נהרג.","ומשיבים: המקרה של אשת איש המוזכר כאן כוונתו שבא על \u0003נערה המאורסה, דאידי ואידי\u0004 \u0005[שזו וזו\u0006\u0005],\u0006 גם בהיותו בן נח וגם ישראל, הריהו נידון \u0003בסקילה,\u0004 ולפיכך נהרג.","ומקשים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003עשה כן בישראל דומיא\u0004 \u0005[בדומה\u0006\u0005]\u0006 לבא על \u0003אשת חבירו\u0004 הגוי \u0003קתני\u0004 \u0005[שנה\u0006\u0005],\u0006 שבשניהם מדובר באותו נושא עצמו, ודין נערה המאורסה אינו קיים כלל בבני נח אלא בישראל בלבד.","\u0003אלא\u0004 לא זה הטעם, ויש להסביר כך: \u0003קלה בחמורה מישך שייכא\u0004 \u0005[שייכת\u0006\u0005],\u0006 שאם מתחייב תחילה בהיותו בן נח במיתה חמורה, ואחר כך כישראל במיתה קלה — הרי המיתה הקלה כלולה בחמורה, ועדיין נשאר חייב בה. ואולם אם הוכבד דינו אחר כך — אומרים אנו שנפטר לגמרי.","ומקשים: \u0003הניחא לרבנן\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים\u0006\u0005]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים ]\u0006 שמיתת \u0003סייף חמור\u0004 ממיתת חנק, ולכן בן נח שבא על אשת חבירו, והיה דינו בסייף, ונתגייר, הוקל דינו והוא עכשיו בחנק — ונהרג. \u0003אלא\u0004 \u0003ל\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 ש\u0003חנק חמור\u0004 מסייף, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי לפי עקרון זה צריך היה להיפטר!","ומשיבים: \u0003ר' שמעון סבר לה\u0004 \u0005[סבור\u0006\u0005]\u0006 בענין זה \u0003כ\u0004שיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה\u0004 ש\u0003אמר: כל מיתה האמורה לבני נח\u0004 סתם \u0003אינה אלא חנק\u0004 ולא סייף, ואם כן הבא על אשת איש בגויותו לא הוחמרה מיתתו בגירותו, אלא עדיין הוא נידון באותה מיתה, ולפיכך נהרג.","ומקשים לשיטת ר' שמעון: \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין \u0003אשת איש, מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 שהיה בן נח חייב לשיטה זו \u0003חנק, והשתא\u0004 \u0005[ועכשיו\u0006\u0005]\u0006 כשבא לכלל ישראל חייב גם כן \u0003חנק. אלא רוצח,\u0004 הלא \u0003מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 כשהיה בן נח חייב לשיטה זו \u0003חנק,\u0004 שכן כאמור הוא סובר כתנא דבי מנשה שכל מיתת גוי בחנק, \u0003והשתא\u0004 \u0005[ועכשיו\u0006\u0005]\u0006 כישראל חייב \u0003סייף!\u0004 ומשיבים: מיתה \u0003קלה בחמורה מישך שייכא\u0004 \u0005[שייכת]\u0006 היא ונכללת בה, שהרי לדעת ר' שמעון חנק חמור מסייף, ולפיכך נהרג.","ומציעים: \u0003לימא מסייעא ליה\u0004 \u0005[האם לומר\u0006 ש\u0005מסייעת לו\u0006\u0005]\u0006 לר' חנינא ברייתא זו, ששנינו: \u0003סרחה\u0004 (חטאה) הנערה המאורסה בזנות והיה דינה סקילה \u0003ואחר כך\u0004 כשעמדה לדין \u0003בגרה\u0004 — \u0003תידון בחנק\u0004 כשאר ארוסה בוגרת שזינתה. \u0003בסקילה מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 דנים אותה? — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003הואיל ואישתני\u0004 \u0005[ונשתנתה]\u0006 מהותה — \u0003אישתני\u0004 \u0005[נשתנה]\u0006 דינה? \u0003וכל שכן הכא דאישתני\u0004 \u0005[כאן,\u0006 בגר, \u0005שנשתנה]\u0006 \u0003לגמרי\u0004 מגוי לישראל! ודוחים: אין להביא מכאן ראיה, שכן \u0003האמר ליה\u0004 \u0005[הרי אמר לו\u0006\u0005]\u0006 \u0003ר' יוחנן ל\u0004אותו \u0003תנא\u0004 ששנה ברייתא זו לפניו: תקן את הנוסח, ו\u0003תני\u0004 \u0005[שנה\u0006\u0005]:\u0006 \u0003תידון בסקילה\u0004 ולא בחנק, ואין איפוא להביא משם ראיה.","\u0003בן סורר ומורה נידון\u0004 במיתה לא מפני חומרת העבירה שעושה עכשיו, אלא \u0003על שם סופו,\u0004 שנער כזה יגדל ויהא רוצח ופושע, ומוטב ש\u0003ימות זכאי\u0004 לפני שגרם נזק רב, \u0003ואל ימות חייב, שמיתתן של רשעים\u0004 גם \u0003הנאה להן,\u0004 שהרי אינם חוטאים עוד, \u0003ו\u0004היא גם \u0003הנאה לעולם\u0004 כולו, שנפטר מן המזיק. \u0003ו\u0004להיפך, מיתתם של \u0003צדיקים רע להן,\u0004 שאין עושים עוד מצוות, \u0003ורע לעולם,\u0004 שחסר לו צדיק זה,","ואגב אומרים עוד בענין זה: שתיית \u0003יין ושינה, לרשעים\u0004 — \u0003הנאה להן והנאה לעולם,\u0004 שהרי בזמן שישנים וכאשר הם תחת השפעת היין, אינם מזיקים לאחרים. ולהיפך אצל ה\u0003צדיקים\u0004 גם השינה וגם היין הם \u0003רע להן ורע לעולם.\u0004","\u0003פיזור לרשעים\u0004 שאינם מצויים יחד — \u0003הנאה להן,\u0004 שאינם מגרים זה את זה לחטוא, \u0003והנאה לעולם.\u0004 פיזור \u0003לצדיקים\u0004 — \u0003רע להן ורע לעולם. כנוס לרשעים\u0004 — \u0003רע להן ורע לעולם, ולצדיקים\u0004 — \u0003הנאה להן והנאה לעולם. שקט לרשעים\u0004 — \u0003רע להן ורע לעולם. לצדיקים\u0004 — \u0003הנאה להן והנאה לעולם.\u0004"],["\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 המרחיבה יותר את דברי המשנה, \u0003ר' יוסי הגלילי אומר: וכי מפני שאכל זה\u0004 הנער \u0003תרטימר בשר ושתה חצי לוג יין האיטלקי אמרה תורה יצא לבית דין ליסקל?\u0004 וכי על דברים אלה יהא חייב מיתה? \u0003אלא הגיעה תורה לסוף דעתו של בן סורר ומורה,\u0004 כלומר, לתוצאה ההכרחית מן הדברים, שאם ממשיך בדרך זו \u0003סוף\u0004 דבר שהוא \u0003מגמר\u0004 (מכלה) את \u0003נכסי אביו ומבקש למודו\u0004 (הרגלו) לזלול ולסבוא כדרך שהיה רגיל, \u0003ואינו מוצא, ו\u0004אז \u0003יוצא לפרשת דרכים ומלסטם\u0004 (שודד) \u0003את הבריות\u0004 והורגם.","\u0003אמרה תורה:\u0004 מוטב ש\u0003ימות זכאי ואל ימות\u0004 לאחר זמן \u0003חייב. שמיתתן של רשעים\u0004 — \u0003הנאה להם והנאה לעולם, ו\u0004מיתה \u0003לצדיקים\u0004 — \u0003רע להם ורע לעולם. שינה ויין לרשעים\u0004 — \u0003הנאה להם והנאה לעולם, לצדיקים\u0004 — \u0003רע להם ורע לעולם. שקט לרשעים\u0004 — \u0003רע להן ורע לעולם. ולצדיקים\u0004 — \u0003הנאה להם והנאה לעולם. פיזור לרשעים\u0004 שאינם מצויים יחד — \u0003הנאה להן,\u0004 שאינם מגרים זה את זה לחטוא, \u0003והנאה לעולם.\u0004 \u0003ו\u0004פיזור \u0003לצדיקים\u0004 — \u0003רע להם ורע לעולם.\u0004","גנב \u0003הבא במחתרת\u0004 שנאמר בתורה שאין לו דמים, כלומר, מותר להורגו, אף הוא \u0003נידון על שם סופו.\u0004 שהרי אנו יודעים שאם ינסה בעל הבית להתנגד לו — יהרגנו. \u0003היה\u0004 הגנב \u0003בא במחתרת\u0004 ותוך כדי כך \u0003שבר את החבית, אם\u0004 הוא מקרה ש\u0003יש לו דמים\u0004 (שאסור להורגו), וכגון באב הבא במחתרת לגנוב מבנו, שבכגון זה אין הבן רשאי להרוג את אביו, שכן ברור הדבר שאף אם יתנגד הבן לא יהרגנו אביו, שהרי רחמי האב על הבן, הרי גנב זה \u0003חייב\u0004 לשלם דמי החבית. ו\u0003אם אין לו דמים,\u0004 וכגון בכל אדם אחר הבא במתחרת, הרי גם אם לא נהרג — \u0003פטור\u0004 מלשלם.","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הלכה זו של הבא ב\u0003מחתרת?\u0004 והסביר: \u0003חזקה\u0004 היא, \u0003אין אדם מעמיד עצמו\u0004 (מתאפק) \u0003על ממונו\u0004 שיגזלו ממנו, \u0003והאי\u0004 \u0005[ואותו\u0006\u0005]\u0006 הגנב במחתרת \u0003מימר\u0004 \u0005[אמור]\u0006 \u0003אמר\u0004 בלבו: \u0003אי אזילנא\u0004 \u0005[אם הולך אני]\u0006 והוא רואה אותי, הרי \u0003קאי לאפאי\u0004 \u0005[יעמוד כנגדי]\u0006 \u0003ולא שביק\u0004 \u0005[יניח]\u0006 \u0003לי,\u0004 \u0003ואי קאי לאפאי\u0004 \u0005[ואם יעמוד כנגדי]\u0006 — \u0003קטלינא ליה\u0004 \u0005[אהרוג אותו\u0006\u0005],\u0006 וכיון שהיתה דעתו מלכתחילה אף לרצוח, הרי \u0003התורה אמרה: אם בא\u0004 אדם \u0003להורגך\u0004 — \u0003השכם להורגו.\u0004","\u0003אמר רב: הבא במחתרת ונטל כלים ויצא\u0004 ונתפס רק אחר כך — \u0003פטור\u0004 מלהשיב את הכלים. \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 כי \u0003בדמים קננהו\u0004 \u0005[קנה אותם\u0006\u0005],\u0006 כי כיון שסיכן את עצמו למות בשעת הגניבה, שהרי מותר היה להרגו אז, אין ליטול ממנו מה שגנב, שהרי משום הסיכון החמור שהיה בו נפטר מכל עונש אחר, קל יותר. \u0003אמר רבא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו\u0006\u0005]\u0006 של \u0003רב\u0004 שפטר \u0003בששיבר\u0004 את הכלים, בשעת מעשה, \u0003דליתנהו\u0004 \u0005[שאינם],\u0006 שאין תובעים ממנו את דמיהם. \u0003אבל\u0004 אם \u0003נטל\u0004 את הכלים והם עדיין ברשותו — \u0003לא\u0004 ישארו בידו.","ומעירים: \u0003והאלהים!\u0004 (דרך שבועה), באמת \u0003אמר רב\u0004 דבריו \u0003אפילו\u0004 במקרה ש\u0003נטל,\u0004 כלומר, רב עצמו איננו מחלק בין שני המקרים, \u0003דהא\u0004 \u0005[שהרי\u0006\u0005]\u0006 במקרה כגון אב הגונב מן הבן ש\u0003יש לו דמים, ונאנסו,\u0004 כלומר, אם שבר את הכלים שלא ברצונו אלא באונס — \u0003חייב\u0004 להחזיר. \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהכלים \u0003ברשותיה קיימי\u0004 \u0005[ברשותו\u0006 של הגנב הם \u0005עומדים],\u0006 וחייב לשלם כל נזק שאירע בהם, \u0003הכא נמי ברשותיה קיימי\u0004 \u0005[כאן גם כן,\u0006 כשאין לו דמים, \u0005ברשותו\u0006 הם \u0005עומדים\u0006\u0005]\u0006 והם שלו.","ורבא מסביר: אף כי יש לכאורה ראיה, מכל מקום \u0003ולא היא,\u0004 אינו כן באמת, \u0003כי אוקמינא\u0004 \u0003רחמנא ברשותיה\u0004 \u0005[כאשר העמידה התורה\u0006 את הכלים \u0005ברשותו\u0006\u0005],\u0006 שהם נחשבים כשלו הרי זה \u0003לענין אונסין\u0004 שיהא חייב על כל נזק שיארע בהם. \u0003אבל לענין מקנא\u0004 \u0005[קנין]\u0006 — \u0003ברשותיה דמרייהו קיימי\u0004 \u0005[ברשות בעליהם\u0006 הם \u0005עומדים\u0006\u0005],\u0006 וראיה לכך: \u0003מידי דהוה\u0004 \u0005[כשם ש\u0006הדבר \u0005הוא]\u0006 ב\u0003שואל,\u0004 שאף שהשואל חייב לשלם גם נזקי אונסים שאירעו במה ששאל, בכל זאת אינם נעשים כרכושו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 אם \u0003בא במחתרת ושיבר את החבית\u0004 שהיתה שם, אם \u0003יש לו דמים,\u0004 שאי אפשר להורגו — \u0003חייב\u0004 בדמי החבית, אם \u0003אין לו דמים,\u0004 שאפשר להורגו — \u0003פטור.\u0004 ונדייק מן המשנה \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003שיבר, דכי\u0004 \u0005[שכאשר\u0006\u0005]\u0006 \u0003אין לו דמים פטור\u0004 מלשלם, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם \u0003נטל\u0004 — \u0003לא\u0004 ייפטר, וחייב לשלם, וקשה לרב!","ומתרצים: \u0003הוא הדין\u0004 ש\u0003אפילו\u0004 כאשר \u0003נטל\u0004 כלים \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 פטור מלשלם עליהם, \u0003והא דקא תני\u0004 \u0005[וזה ששנה\u0006\u0005]\u0006 בלשון \u0003\"שבר את החבית\", קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכך חידוש \u0003דכי\u0004 \u0005[שכאשר\u0006\u0005]\u0006 \u0003יש לו דמים, אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003שיבר\u0004 — \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003חייב,\u0004 אף שאין הכלים בעין.","על הסבר זה מקשים: מה החידוש בדבר? הלא דבר זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי גנב זה כשאר \u0003מזיק הוא\u0004 והמזיק משלם! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אפילו\u0004 אם שיבר \u0003שלא בכוונה,\u0004 גם כן חייב. ומקשים שוב: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006\u0005]\u0006 וחידש לנו בזה — ש\u0003אדם מועד לעולם,\u0004 וגם המזיק שלא בכוונה — חייב. אולם אף זה \u0003תנינא\u0004 \u0005[שנינו\u0006\u0005]\u0006 כבר במשנה: \u0003אדם מועד לעולם\u0004 וחייב לשלם, \u0003בין\u0004 שהזיק \u0003בשוגג בין במזיד בין באונס בין ברצון!\u0004 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לשיטת רב.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב ביבי בר אביי\u0004 על שיטת רבא מן המשנה: \u0003הגונב כיס בשבת\u0004 והוציאו לרשות הרבים — \u0003חייב\u0004 לשלם מה שגנב, אף שבתוך כך חילל את השבת, והיא עבירה שחייבים עליה מיתה. \u0003שהרי נתחייב בגניבה קודם שיבא לידי איסור שבת.\u0004 שכן הגנב הגביה את הכיס, ועל ידי כך נעשה כקניינו עוד לפני שיצא לרשות אחרת, ורק משיצא מרשות בעליו התחייב משום מוציא מרשות היחיד לרשות הרבים בשבת.","\u0003היה מגרר\u0004 את הכיס על הארץ \u0003ויוצא\u0004 עד שהוציאו בדרך זו מרשות בעליו לרשות הרבים — \u0003פטור\u0004 מלשלם דמי הכיס, \u0003שהרי איסור גניבה\u0004 חל עליו רק כאשר הוציא את החפץ מרשות בעליו שכן לא הגביהו, \u0003ואיסור סקילה\u0004 שנתחייב בו כאשר הוציאו מרשות היחיד לרשות הרבים \u0003באין כאחד,\u0004 ומי שנתחייב בדיני נפשות פטור מלשלם כסף שנתחייב באותו מעשה עצמו. ואם כן קשה הדבר לשיטת רבא, שאמר שאם מה שגנב נמצא בעין — חייב להחזיר. ומכאן משמע שאם עבר עבירה שחייבים עליה מיתה נפטר מכל תשלומים!","ומשיבים: \u0003והלכתא\u0004 \u0005[וההלכה\u0006\u0005]\u0006 היא שיש להסביר את המשנה ההיא כגון \u0003דשדנהו בנהרא\u0004 \u0005[שזרק\u0006 את הכיס \u0005בנהר\u0006\u0005]\u0006 שפטור מתשלומים אפילו כשהזיק ביודעים, שהרי אין החפצים בעין.","מסופר: \u0003רבא איגנבו ליה דיכרי במחתרתא\u0004 \u0005[נגנבו לו אילים במחתרת\u0006\u0005].\u0006 \u0003אהדרינהו ניהליה\u0004 \u0005[החזירום לו]\u0006 \u0003ולא קבלינהו\u0004 \u0005[קבלם\u0006\u0005].\u0006 \u0003אמר: הואיל ונפק מפומיה\u0004 \u0005[ויצא מפיו]\u0006 של \u0003רב\u0004 שהגנב קנאם בדמים שוב אין הוא רוצה לקחתם.","ועוד בנושא זה של הבא במחתרת, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 על הנאמר \"אם במחתרת ימצא הגנב והכה ומת \u0003אין לו דמים. אם זרחה השמש עליו\u0004 דמים לו\" (שמות כב, א–ב), יש לתמוה: \u0003וכי השמש עליו בלבד זרחה! אלא\u0004 יש להבינו כביטוי סמלי, שמשמעו: \u0003אם ברור לך הדבר כשמש, שאין לו שלום עמך,\u0004 אלא כוונתו של גנב זה להרגך — הקדם \u0003ו\u0004\u0003הרגהו\u0004 אתה, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאינך בטוח בכוונותיו — \u0003אל תהרגהו.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת\u0006\u0005]:\u0006 על הנאמר \u0003\"אם זרחה השמש עליו דמים לו\",\u0004 יש לתמוה: \u0003וכי השמש עליו בלבד זרחה! אלא\u0004 ללמד באופן זה: \u0003אם ברור לך כשמש שיש לו שלום עמך\u0004 — \u0003אל תהרגהו, ואם לאו\u0004 \u0005[לא],\u0006 שאינך בטוח בכוונותיו — \u0003הרגהו.\u0004 ומעירים: \u0003קשיא סתמא אסתמא\u0004 \u0005[קשה סתם\u0006 דין גנב שלא נתבררה כוונתו \u0005על סתם],\u0006 שמהברייתא הראשונה משמע שאם אינו יודע בבירור שכוונתו להורגו אסור להורגו, ומהשניה משמע שכל עוד אינו בטוח שכוונתו לשלום מותר להורגו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005],\u0006"],["\u0003כאן\u0004 ששנינו שאסור להרוג, הרי זה \u0003באב\u0004 הבא \u0003על הבן\u0004 במחתרת, שסתם אב מרובים רחמיו על הבן ואין בדעתו להרגו ולכן יש לו דמים, וידרשו דמיו מן ההורגו, אלא אם כן ברור לבן כשמש שהאב מתכוון להורגו. \u0003כאן\u0004 שמותר להרוג מספק הרי זה אפילו \u0003בבן\u0004 הבא \u0003על האב,\u0004 שאז, כל שאינו בטוח שבא בשלום — מותר להרגו.","\u0003אמר רב: כל\u0004 מי \u0003דאתי עלאי במחתרתא\u0004 \u0005[שיבא עלי במחתרת]\u0006 — \u0003קטילנא ליה\u0004 \u0005[הורג אני אותו],\u0006 שסתמו של דבר שבא להרוג, ואפילו הוא אדם המוכר לי, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מרב חנינא בר שילא\u0004 שאותו לא הייתי הורג. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמר רב כך ביחס אליו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא סומך עליו \u0003משום\u0004 ש\u0003צדיק הוא\u0004 — ואולם \u0003הא קאתי במחתרתא\u0004 \u0005[הרי\u0006 פה מדובר ש\u0005הוא בא במחתרת]\u0006 ומוכח איפוא שאינו צדיק! \u0003אלא\u0004 הטעם הוא \u0003משום דקים\u0004 \u0005[שמובטח]\u0006 \u0003לי בגוויה\u0004 \u0005[בו]\u0006 שהוא \u0003מרחם עלי כרחם אב על הבן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \u0003\"\u0004אם זרחה השמש עליו \u0003דמים לו\"\u0004 (שמות כב, ב): \u0003בין\u0004 שהיה הדבר \u0003בחול בין בשבת,\u0004 ואם \u0003\"אין לו דמים\"\u0004 — \u0003בין בחול בין בשבת.\u0004","ומבררים: \u0003בשלמא\u0004 \u0005[נניח],\u0006 מה שנאמר \u0003\"אין לו דמים\"\u0004 שהוא \u0003בין בחול בין בשבת איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר לאומרו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003מידי דהוה\u0004 \u0005[הדבר הריהו]\u0006 כמו ב\u0003הרוגי בית דין,\u0004 ש\u0003בשבת לא קטלינן\u0004 \u0005[הורגים אנו]\u0006 אותם, על כן \u0003קא משמע לן דקטלינן\u0004 \u0005[השמיע לנו\u0006 התנא \u0005שאנו הורגים]\u0006 את הבא במחתרת כהגנה עצמית אף בשבת. \u0003אלא\u0004 מה שאמר שבאופן ש\u0003\"דמים לו\"\u0004 דינו אחד \u0003בין בחול בין בשבת,\u0004 תמוה: הרי \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003ב\u0004יום \u0003חול לא קטלינן ליה\u0004 \u0005[הורגים אנו אותו],\u0006 \u0003בשבת מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינו נהרג?!","\u0003אמר רב ששת: לא נצרכא\u0004 הלכה זו שדמים לו אף בשבת \u0003אלא\u0004 למקרה שנפלה עליו מפולת בשבת, שחייבים \u0003לפקח עליו\u0004 (להסיר ממנו) \u0003את הגל\u0004 של האבנים שנפל עליו ולהצילו ממוות אף שיש בכך חילול שבת, ואין אומרים כי אמנם אסור להרגו בידים, אך גם אין חובה להשתדל בהצלתו.","על הנאמר \"אם במחתרת ימצא הגנב והכה ומת אין לו דמים\" (שמות כב, א), \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"והכה\"\u0004 בא ללמד \u0003בכל אדם\u0004 שתופסו, \u0003\"ומת\"\u0004 — שמיתתו \u0003בכל מיתה שאתה יכול להמיתו.\u0004 ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 למה שלמדו מהמלה \u0003\"והכה\"\u0004 שמיתתו \u0003בכל אדם, איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר לאומרו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003בעל הבית הוא דקים להו\u0004 \u0005[שבטוח בו]\u0006 הגנב, שלא יחשה על ממונו, שהרי \u0003אין אדם מעמיד עצמו על ממונו, אבל\u0004 לגבי \u0003אחר לא\u0004 בטוח הגנב שיעמיד עצמו על ממון בעל הבית, ואין הגנב בא בכוונת הריגה, ולכן אין האחר רשאי להורגו, שהרי לא נתכוון החותר להורגו, על כן","\u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגנב זה \u0003רודף הוא,\u0004 שדינו כשאר אדם הרודף אחר חבירו להמיתו שכל אדם רשאי להציל את הנרדף, \u0003ו\u0004לכן \u0003אפילו אחר נמי\u0004 \u0005[גם כן]\u0006 מותר להורגו, כדי להציל את בעל הבית. \u0003אלא\u0004 מה ששנינו שהמלה \u0003\"ומת\"\u0004 באה ללמד כי מיתתו \u0003בכל מיתה שאתה יכול להמיתו, למה לי\u0004 לומר כן?","והלא \u0003מ\u0004דין \u0003רצח נפקא\u0004 \u0005[יוצא,\u0006 נלמד הדבר\u0005]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"מות יומת המכה רצח הוא\"\u0004 (במדבר לה, כא) \u0003אין לי\u0004 ללמוד \u0003אלא\u0004 שממיתים אותו \u0003במיתה האמורה בו,\u0004 בסייף, \u0003ומנין שאם אי\u0004 (אין) \u0003אתה יכול\u0004 מאיזה שהוא טעם \u0003להמיתו במיתה הכתובה בו, שאתה רשאי להמיתו בכל מיתה שאתה יכול להמיתו?\u0004 \u0003תלמוד לומר: \"מות יומת\"\u0004 — \u0003מכל מקום,\u0004 ואם כן הרי שאף רוצח נהרג בכל מיתה! ומדוע צריך לשנות דין גנב כאן? נלמד מרוצח!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ברוצח ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 וגילה במפורש: \u0003\"מות יומת\",\u0004 ומשמע: מכל מקום.","ושואלים: \u0003וניגמר מיניה\u0004 \u0005[ונלמד מכאן]\u0006 לגבי כל שאר חייבי מיתה שבעולם, שמיתתם בכל דרך! ומשיבים: \u0003משום דהוה\u0004 \u0005[שהיה]\u0006 גם \u0003רוצח ו\u0004גם \u0003גואל הדם שני כתובין הבאין כאחד,\u0004 שבשניהם נאמר דין זה שמי שאי אפשר להמיתו במיתה הראויה לו ממיתים אותו בכל מיתה אחרת. \u0003וכל שני כתובין הבאין כאחד אין מלמדין\u0004 לענין אחר, אלא באו לעניינם בלבד. ולכן היה התנא צריך ללמדנו דין זה גם בבא במחתרת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממה שנאמר \"אם ב\u0003מחתרת\u0004 ימצא הגנב\" (שמות כב, א) \u0003אין לי\u0004 ללמוד \u0003אלא\u0004 שבא ב\u0003מחתרת\u0004 בלבד. ואולם אם בא דרך \u0003גגו\u0004 או דרך \u0003חצירו\u0004 או דרך \u0003קרפיפו\u0004 (חצר מגודרת המצוייה אחורי הבית, שמטילים בה גרוטאות) \u0003מנין\u0004 שהדין כמו כן? \u0003תלמוד לומר: \"ימצא הגנב\"\u0004 — \u0003מכל מקום,\u0004 בכל מקום שנמצא. \u0003אם כן מה תלמוד לומר \"מחתרת\"\u0004 — דיבר הכתוב במקרה המצוי, \u0003מפני שרוב גנבים מצויין במחתרת.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 ממה שנאמר בכתוב \u0003\"מחתרת\" אין לי\u0004 ללמוד \u0003אלא מחתרת\u0004 בלבד, ואולם אם בא דרך \u0003גגו חצירו וקרפיפו מנין\u0004 שהדין כמו כן? \u0003תלמוד לומר \"ימצא הגנב\"\u0004 — \u0003מכל מקום. אם כן מה תלמוד לומר \"מחתרת\"\u0004 — בא הדבר ללמדנו ש\u0003מחתרתו זו היא התראתו.\u0004 שגנב זה אין צורך להתרות בו קודם לכך, אלא כיון שבא במחתרת ממיתים אותו בלא צורך להזהירו, מה שאין כן בבא בדרך אחרת.","\u0003אמר רב הונא: קטן הרודף\u0004 אחר אדם אחר להורגו \u0003ניתן להצילו בנפשו.\u0004 כלומר, מותר להציל את הנרדף על ידי הריגת הקטן הרודף, ואין אומרים שכיון שאין הקטן בר דעת אינו בן עונשים. \u0003קסבר\u0004 \u0005[סבר]\u0006 רב הונא: \u0003רודף\u0004 בכלל \u0003אינו צריך התראה, לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה הרודף \u0003גדול,\u0004 מבוגר, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היה זה \u0003קטן,\u0004 שלענין זה עיקרו של דבר הוא להציל את הנרדף ממוות, ואין כאן מקום לדון אם הרודף חייב מיתה או לא.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב חסדא לרב הונא\u0004 ממה ששנינו: תינוק העומד להיוולד ולידתו מסכנת את אמו, אם \u0003יצא\u0004 כבר \u0003ראשו\u0004 החוצה בזמן הלידה — \u0003אין נוגעין בו\u0004 להמיתו כדי להציל את אמו, \u0003לפי שאין דוחין נפש מפני נפש.\u0004 ולפי דעתך \u0003אמאי\u0004 \u0005[מדוע]\u0006 עושים כן? והלא התינוק \u0003רודף הוא,\u0004 שהרי הוא בא להרוג את אמו, ומדוע לא נהרגנו אם אכן יש להרוג רודף קטן?! ודוחים: אין כאן קושיא שכן \u0003שאני התם דמשמיא קא רדפי לה\u0004 \u0005[שונה שם שמשמים רודפים אותה],\u0006 שהרי אין התינוק עושה כן מדעת עצמו ואין הדבר תלוי ברצונו, ולכן אין לדחות נפשו מפני נפש אמו.","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003רודף שהיה רודף אחר חבירו להורגו, אומר לו\u0004 לרודף: \u0003ראה שישראל הוא\u0004 הנרדף, \u0003ובן ברית הוא,\u0004 שאינו משומד שיצא מכלל ברית ישראל, \u0003והתורה אמרה: \"שפך דם האדם באדם דמו ישפך\"\u0004 (בראשית ט, ו). \u0003אמרה תורה: הצל דמו של זה\u0004 הנרדף \u0003בדמו של זה\u0004 הרודף,","וכיון שלא נאמר שצריך הרודף לומר ששמע את ההתראה, משמע שאין צורך להתרות וכרב הונא, ודוחים: משם אין ראיה, שכן המשנה \u0003ההיא\u0004 כשיטת \u0003ר' יוסי בר' יהודה היא.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא \u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: חבר\u0004 שיודע דיני התורה \u0003אין צריך התראה\u0004 כדי להיענש במיתת בית דין \u0003לפי שלא ניתנה התראה אלא להבחין בין שוגג למזיד.\u0004 ואף הרודף אחר חבירו, כיון שברור זדונו — אינו צריך להתראה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שיש להתרות ברודף, וגם קטן אין ניתן להצילו בנפשו, ממה ששנינו: \u0003רודף שהיה רודף אחר חבירו להורגו, אומר לו: ראה שישראל הוא\u0004 הנרדף, \u0003ובן ברית הוא, והתורה אמרה: \"שפך דם האדם באדם דמו ישפך\", אם אמר\u0004 הרודף \u0003\"יודע אני שהוא כן\"\u0004 — עדיין \u0003פטור,\u0004 ואם אמר \u0003\"על מנת כן אני עושה\"\u0004 — \u0003חייב,\u0004 ומשמע שצריכים להתרות אפילו ברודף!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דקאי בתרי עיברי דנהרא דלא מצי אצוליה\u0004 \u0005[שעומדים\u0006 המתרה והרודף \u0005בשני עברי הנהר שאינו יכול להציל]\u0006 את הנרדף על ידי הריגת הרודף. \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 לו לעשות — לפחות \u0003דבעי איתויי לבי דינא\u0004 \u0005[שרצונו להביאו לבית הדין],\u0006 שיתפסוהו לאחר זמן וידונוהו למוות, ואולם \u0003בי דינא בעי\u0004 \u0005[\u0006ב\u0005בית הדין צריך]\u0006 \u0003התראה\u0004 כדי לעונשו, ומשום כך נאמרה התראה זו, ולא לענין היתר הריגת רודף, וסתם רודף אפשר להרגו ללא התראתו.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר, \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי שמותר להרוג רודף קטן, \u0003כ\u0004פי שיטתו של ה\u0003תנא\u0004 שדיבר בענין \u0003מחתרת\u0004 אמרתי זאת. ש\u0003אמר\u0004 אותו תנא: \u0003מחתרתו זו היא התראתו.\u0004 ואף כאן כל הרודף אחר חבירו אינו צריך התראה, שעצם רדיפתו היא התראתו."],["\u0003ואלו הן שמצילין אותן\u0004 מלעבור עבירה אפילו \u0003בנפשן,\u0004 כלומר, שהורגים אותם כדי שלא יגיעו לידי עבירה: \u0003הרודף אחר חבירו להרגו, ו\u0004כן הרודף \u0003אחר הזכר\u0004 לרובעו, \u0003ו\u0004כן \u0003אחר הנערה המאורסה\u0004 לאונסה. \u0003אבל הרודף אחר בהמה\u0004 לרובעה, \u0003ו\u0004כן העומד ל\u0003חלל את השבת ו\u0004ה\u0003עובד עבודה זרה\u0004 — \u0003אין מצילין אותן בנפשן,\u0004 אלא מתרים בהם, ואחר כך מביאים אותם להידון בפני בית הדין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מניין לרודף אחר חבירו להרגו שניתן להצילו בנפשו?\u0004 — \u0003תלמוד לומר: \"לא תעמד על דם רעך\"\u0004 (ויקרא יט, טז), אלא הצילהו ממוות. ומקשים: \u0003והא להכי\u0004 \u0005[ו\u0006פסוק \u0005זה לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמדנו? והרי \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נחוץ לו]\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מניין לרואה את חבירו שהוא טובע בנהר או\u0004 ש\u0003חיה גוררתו\u0004 לטורפו, \u0003או לסטין\u0004 (שודדים) \u0003באין עליו, שהוא חייב להצילו\u0004 — \u0003תלמוד לומר: \"לא תעמד על דם רעך\"!\u0004 ומשיבים: \u0003אין, הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 באמת, פסוק זה לענין הצלת רעהו נאמר.","ושוב שואלים: \u0003ואלא\u0004 דין זה של \u0003להצילו בנפשו מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 \u0003בקל וחומר מנערה המאורסה: מה נערה המאורסה שלא בא\u0004 האונס \u0003אלא לפוגמה\u0004 על ידי אונס זה, \u0003אמרה תורה\u0004 כי \u0003ניתן להצילה בנפשו,\u0004 מי שהיה \u0003רודף אחר חבירו להרגו\u0004 שבא ליטול את נפשו \u0003על אחת כמה וכמה,\u0004 שניתן להצילו בנפשו.","ומקשים: \u0003וכי עונשין מן הדין?\u0004 וכי מצאנו שעונשים אדם רק על פי הוכחה מקל וחומר? ומסבירים: \u0003דבי רבי תנא\u0004 \u0005[\u0006חכם \u0005מבית\u0006 מדרשו \u0005של רבי\u0006 יהודה הנשיא \u0005שנה]\u0006 כי לימוד זה \u0003הקישא\u0004 \u0005[היקש,\u0006 השוואה של המקרא עצמו\u0005]\u0006 \u0003הוא.\u0004 כיצד? — נאמר בנערה האנוסה: \"ולנערה לא תעשה דבר אין לנערה חטא מות \u0003כי כאשר יקום איש על רעהו ורצחו נפש\u0004 כן הדבר הזה\" (דברים כב, כו) \u0003וכי מה למדנו\u0004 בדין זה \u0003מרוצח?\u0004","שהרי אין אנו למדים כל דבר נוסף מהשוואה זו \u0003מעתה הרי זה\u0004 (הדימוי לרוצח) \u0003בא ללמד ונמצא למד\u0004 שלמדים מנערה המאורסה לענין רוצח, כיצד? \u0003מקיש\u0004 \u0005[משוה]\u0006 הכתוב \u0003רוצח לנערה המאורסה, מה נערה המאורסה ניתן להצילה בנפשו\u0004 של האונס, \u0003אף רוצח ניתן להצילו בנפשו.\u0004","ושואלים: \u0003ונערה מאורסה גופה\u0004 (עצמה) \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שמותר להצילה בנפשו של האונס? ומסבירים: \u0003כדתנא דבי\u0004 \u0005[כפי ששנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על הכתוב: \u0003\"\u0004כי בשדה מצאה צעקה הנערה המאורסה \u0003ואין מושיע לה\"\u0004 (שם כז) \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש מושיע לה\u0004 — צריך להושיעה \u0003בכל דבר שיכול להושיע\u0004 ואפילו על ידי הריגת האונס.","אגב הדיון הקודם הבאנו את הברייתא בענין \"לא תעמוד על דם רעך\" (ויקרא יט, טז), ומעתה דנים בה \u0003גופא\u0004 \u0005[לגופה]:\u0006 \u0003מנין לרואה את חברו שהוא טובע בנהר או חיה גוררתו או לסטין באין עליו\u0004 או סכנה אחרת באה עליו, \u0003שהוא חייב להצילו\u0004 — \u0003תלמוד לומר: \"לא תעמד על דם רעך\".\u0004 ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[\u0006ודבר \u0005זה מכאן\u0006 הוא \u0005יוצא,\u0006 נלמד\u0005]?\u0006 והרי \u0003מהתם נפקא\u0004 \u0005[משם\u0006 מפסוק אחר הוא \u0005יוצא,\u0006 נלמד\u0005].\u0006 שכן שנינו: למדנו בתורה דין אבידת ממונו של חבירו, שחייב להשיב לו, \u0003אבדת גופו,\u0004 שאם רואה את חבירו במצב שמאבד מגופו או מבריאותו \u0003מניין\u0004 שחייב לעזור לו? — \u0003תלמוד לומר: \"והשבתו לו\"\u0004 (דברים כב, ב), ללמד שחייב להשיב הכל, ואבידת גופו בכלל. ואם כן אין צורך בפסוק נוסף!","ומשיבים: \u0003אי מהתם, הוה אמינא\u0004 \u0005[אם משם\u0006 בלבד, הרי \u0005הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בנפשיה\u0004 \u0005[\u0006שהוא \u0005בעצמו]\u0006 יבוא לעזור לחבירו אם יוכל, כבשאר מקרה של השבת אבידה, \u0003אבל מיטרח ומיגר אגורי\u0004 \u0005[לטרוח ולשכור שכירים]\u0006 לצורך הצלה זו \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתחייב, כשם שאינו חייב באבידה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב \"לא תעמוד על דם רעך\" שעובר אם יושב ואינו עושה דבר.","ועוד בענין הרודף \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד הרודף אחר חבירו להרגו ו\u0004אחד הרודף \u0003אחר הזכר ואחר נערה המאורסה\u0004 לאונסה, \u0003ואחר\u0004 עריות שהבאים עליהן הם \u0003חייבי מיתות בית דין, ואחר\u0004 עריות שהבאים עליהן \u0003חייבי כריתות\u0004 כל אלה \u0003מצילין אותן בנפשו\u0004 של העבריין. ואולם אם רואים \u0003אלמנה\u0004 שרודף אחריה \u0003כהן גדול\u0004 לאונסה, או \u0003גרושה\u0004 או \u0003חלוצה\u0004 שרודף אחריה \u0003כהן הדיוט\u0004 לאונסה — \u0003אין מצילין אותן בנפשו,\u0004 לפי שהם איסור \"לא תעשה\" בלבד.","ועוד, אם כבר \u0003נעבדה\u0004 \u0005[נעשתה]\u0006 \u0003בה,\u0004 בנערה המאורסה, \u0003עבירה\u0004 — \u0003אין מצילין אותה בנפשו.\u0004 וכן אם \u0003יש לה מושיע,\u0004 שיש לנערה אפשרות אחרת להינצל, שלא על ידי הריגת האונס — \u0003אין מצילין אותה בנפשו. ר' יהודה אומר: אף\u0004 נערה המאורסה \u0003האומרת\u0004 למציליה \u0003\"הניחו לו\"\u0004 ובקשתה זו היא כדי \u0003שלא יהרגנה\u0004 — אין הורגים אותו.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שבאותם מקרים שמנינו מצילים אותה בנפשו? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולנער לא תעשה דבר אין לנער חטא מות\"\u0004 (שם כו), אף על פי שהקרי הוא \"נערה\", אך הכתיב הוא \u0003\"נער\"\u0004 ו\u0003זה\u0004 רמז למשכב \u0003זכור, \"נערה\"\u0004 כפי הקרי — \u0003זו נערה המאורסה\u0004 כפשוטו, \u0003\"חטא\"\u0004 — \u0003אלו חייבי כריתות, \"מות\"\u0004 — \u0003אלו חייבי מיתות בית דין.\u0004","ושואלים: \u0003כל הני\u0004 \u0005[אלה]\u0006 \u0003למה לי\u0004 לפרטם, ומדוע לא תספיק דוגמה אחת שממנה נלמד כל השאר? ומשיבים: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 כולם. \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003נער\u0004 לענין משכב זכור, הייתי אומר שמה שמצילים אותו בנפש הורגו הוא \u0003משום דלאו אורחיה\u0004 \u0005[שאין\u0006 זו \u0005דרכו]\u0006 להיבעל, ונמצאת בושתו וצערו מרובים מאוד, ולכן מצילים אותו בנפשו של הרודף. \u0003אבל נערה דאורחה\u0004 \u0005[שדרכה],\u0006 כלומר, שסופה להיבעל, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהרגו את הרודף לאונסה.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו היתה כותבת התורה]\u0006 \u0003\"נערה\"\u0004 בלבד, הייתי אומר שהטעם הוא \u0003משום דקא פגים לה\u0004 \u0005[שהוא פוגם אותה]\u0006 בבתוליה, והיא מזולזלת בעיני בעלה. \u0003אבל נער דלא קא פגים ליה, אימא\u0004 \u0005[שאין הוא פוגם אותו, אמור]\u0006 ש\u0003לא\u0004 יצילוהו בנפש רודפו.","\u0003ואי כתב\u0004 \u0003רחמנא הני\u0004 \u0005[ואילו היתה כותבת התורה\u0006 שני \u0005אלה]\u0006"],["היינו אומרים ששניהם מיוחדים \u0003משום דהאי לאו אורחיה הוא, והא קא פגים לה\u0004 \u0005[שזה,\u0006 הנער, \u0005אין זו דרכו, ובזו,\u0006 בנערה, \u0005הוא פוגם אותה],\u0006 \u0003אבל\u0004 הבא על \u0003שאר עריות דאורחייהו\u0004 \u0005[שדרכן]\u0006 של נשים להיבעל \u0003ולא נפיש פיגמייהו\u0004 \u0005[ואין פגמן מרובה]\u0006 כל כך, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצילו אותן בנפשו — על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"חטא\",\u0004 לומר שגם אלו בכלל.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"חטא\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003אפילו חייבי לאוין\u0004 מצילים אותם בנפשם, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"מות\"\u0004 ללמד שדין זה נאמר רק בעבירות שיש עליהן עונש מוות.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"מות\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003חייבי מיתות בית דין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מצילים אותם בנפשם, שהרי חטא חמור הוא ועונשו מוות בידי אדם, אבל \u0003חייבי כריתות\u0004 שמותם בידי שמים — \u0003לא.\u0004 שהרי אין בית דין של מטה מענישים על חטא זה, על כן כתבה התורה \u0003\"חטא\",\u0004 ללמד שגם חייבי כריתות בכלל. ומקשים:","\u0003ולכתוב\u0004 \u0003רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 רק \u0003\"חטא מות\" ולא בעי\u0004 \u0005[יצטרך]\u0006 עוד לפרט \u0003\"נער\" ו\"נערה\"!\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 ולענין זה אין צריכים ללימוד משלה. \u0003ואלא \"נער\" \"נערה\"\u0004 לא לרבות באו אלא למעט, \u0003חד למעוטי\u0004 \u0005[אחד\u0006 מהם בא \u0005למעט]\u0006 \u0003עובד עבודה זרה\u0004 שאין הורגים אותו להצילו מעבירה, \u0003וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 מי שרוצה לבוא על \u0003בהמה\u0004 או לחלל \u0003שבת.\u0004","ושואלים: \u0003ול\u0004שיטת \u0003ר' שמעון בן יוחי\u0004 הסבור כי \u0003עובד עבודה זרה ניתן להצילו בנפשו, למה לי\u0004 שני מיעוטים אלה? ומשיבים: \u0003חד למעוטי\u0004 \u0005[אחד\u0006 מהם \u0005למעט]\u0006 \u0003בהמה, וחד למעוטי\u0004 \u0005[ואחד\u0006 מהם \u0005למעט]\u0006 \u0003שבת.\u0004","ומסבירים מה הצורך באלה: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 \u0003שבת\u0004 בדרך של גזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מעבודה זרה,\u0004 שבשתי עבירות אלה נאמר לשון \"חילול\", והיינו סבורים כי המחלל שבת ניצל בנפשו, על כן היה צריך להודיענו שמחלל שבת אין מצילים אותו בנפשו.","ושואלים: \u0003ול\u0004שיטת \u0003ר' אלעזר בר' שמעון\u0004 ש\u0003אמר\u0004 שה\u0003מחלל את השבת ניתן להצילו בנפשו,\u0004 שלדעתו \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ה\u0003שבת\u0004 בדרך של גזירה שווה מ\u0003\"חילול\" \"חילול\" מעבודה זרה, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 וכיצד להבין את המיעוטים בכתוב? ומשיבים: \u0003חד מיעוט למעוטי\u0004 \u0005[מיעוט אחד\u0006 בא \u0005למעט]\u0006 \u0003בהמה, ואידך\u0004 \u0005[והאחר]\u0006 \u0003איידי דכתב רחמנא\u0004 \u0005[מתוך שכתבה התורה]\u0006 \u0003\"נער\" כתב נמי\u0004 \u0005[כתבה גם כן]\u0006 \u0003\"נערה\",\u0004 כלומר, אין ללמוד שני עניינים נבדלים מהקרי והכתיב שבכתוב זה.","ועוד בביאור הברייתא. שנינו ש\u0003ר' יהודה\u0004 חולק על חכמים ו\u0003אומר: אף האומרת \"הניחו לו\",\u0004 ובקשתה זו היא כדי \u0003שלא יהרגנה\u0004 — אין הורגים אותו. ושואלים \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006","\u0003אמר רבא: במקפדת על פיגמה,\u0004 שאותה נערה מקפדת ומצטערת על פגמה שהיא נפגמת בביאה זו, אלא \u0003מניחתו\u0004 שיבעלנה כדי \u0003שלא יהרגנה. רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003אפיגמה קפיד רחמנא\u0004 \u0005[על פגמה הקפידה התורה],\u0006 \u0003והרי\u0004 זו \u0003מקפדת על פיגמה,\u0004 ולכן צריכים להצילה. \u0003ור' יהודה\u0004 סבור כי \u0003האי דקאמר רחמנא קטליה\u0004 \u0005[זו שאמרה התורה הרוג אותו,\u0006 את האונס\u0005]\u0006 \u0003משום דמסרה נפשה לקטלא\u0004 \u0005[ש\u0006היא \u0005מוסרת\u0006 את \u0005עצמה למיתה]\u0006 ותיאבק בו עד מוות, ואולם \u0003הא\u0004 \u0005[זו]\u0006 שמבקשת שיניחו לו, \u0003לא מסרה נפשה לקטלא\u0004 \u0005[מוסרת\u0006 את \u0005עצמה למיתה],\u0006 ולפיכך אין להרוג את רודפה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 אם הטעם הוא משום פגם, כדברי חכמים, הרי \u0003אלמנה לכהן גדול נמי קא פגים לה\u0004 \u0005[גם כן פוגם\u0006 הוא \u0005אותה]\u0006 בביאתו, שהרי לאחר שבא עליה הריהי מחוללת ומאז אסורה היא להינשא לכל כהן! ומדוע אין מצילים אותה בנפש רודפה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפיגמה רבה\u0004 \u0005[על פגם גדול]\u0006 שיש בו כרת והוולד ממזר — \u0003קפיד רחמנא\u0004 \u0005[הקפידה התורה],\u0006 ואולם \u0003אפיגמה זוטא\u0004 \u0005[על פגם קטן]\u0006 כגון זה — \u0003לא קפיד רחמנא\u0004 \u0005[הקפידה התורה].\u0006","שנינו בברייתא על הנאמר \u0003\"חטא\"\u0004 — \u0003אלו חייבי כריתות,\u0004 ומכאן שכל אדם המנסה לאנוס את הערוה — הורגים אותו. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במקור אחר: \u0003ואלו נערות שיש להן קנס,\u0004 שמשלם לאב חמישים כסף אם אונס אותן, וביניהן: \u0003הבא על אחותו\u0004 באונס. והרי הבא על האחות הוא בין חייבי הכרת שבתורה, ואמרנו שמצילים אותה בנפשו. ויודעים אנו כי בכל מקרה שיש בו חיוב מיתה בידי אדם ואפילו לא נהרג האשם — פטור העבריין מלשלם כל קנס ותשלום. וכיון שהאונס אחותו מצילים אותה בנפשו צריך היה להפטר מקנס!","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003רב חסדא\u0004 פתרון זה: \u0003משעת העראה\u0004 (תחילת הביאה) שכבר \u0003פגמה\u0004 הבועל, שמאז נחשבת היא כבעולה, כבר \u0003איפטר לה מקטלא\u0004 \u0005[נפטר ממיתה],\u0006 שהרי שנינו בברייתא שלאחר שנעבדה בה עבירה ונפגמה שוב אין הורגים אותו. ואילו \u0003ממונא\u0004 \u0005[ממון,\u0006 כסף\u0005]\u0006 הוא \u0003לא משלם,\u0004 כלומר, אינו מתחייב לשלם \u0003עד גמר ביאה\u0004 שיש בה השרת בתולים, ולפיכך יש כאן שני מעשים נבדלים, שסכנת המיתה שהיה לו בה כבר חלפה, ורק כאשר המשיך וגמר ביאתו נתחייב בתשלומים.","הקשה להם רב חסדא: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003העראה\u0004 שנאמרה בתורה (\"את מקורה הערה\" ויקרא כ, יח, וכיוצא בו) \u0003זו נשיקה,\u0004 כלומר, מגע של אברי המין בלבד. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003העראה זו הכנסת עטרה\u0004 של אבר המין הזכרי, הרי זו איפוא בעילה גמורה הראויה להשרת בתולים, ומשעת העראה שוב אינה בתולה, ומתחייב לשלם קנס בשעה שמצילים אותו בנפשו, ואם כן לשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא אמר רב חסדא:\u0004 לא כך יש לפרש, אלא בבא על אחותו \u0003כגון שבא עליה שלא כדרכה\u0004 תחילה, ובביאה ראשונה זו שלא כדרכה פגמה, אבל עדיין בתולה היא, \u0003ו\u0004אחר כך \u0003חזר ובא עליה כדרכה\u0004 ומתחייב אז בקנס כמי שבא על הבתולה והשיר בתוליה, אבל אז אין הורגים אותו שהרי כבר פגומה היא.","\u0003רבא אמר:\u0004 מדובר כאן במקרה שהיתה אחותו \u0003מניחתו,\u0004 שאומרת שיניחו לו כדי \u0003שלא יהרגנה,\u0004 \u0003ו\u0004כשיטת \u0003ר' יהודה היא,\u0004 שבמקרה כזה אין מצילים אותה בנפשו."]]};
